    #[test]
    fn mission_and_step_baselines_block_before_work_and_recheck_retries() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
            version 2

              mission "baseline" state="ready" {
                goal "Run only from an admitted baseline."
                completion { when "all-steps-exhausted" }

                  agent "worker" { workspace "/tmp"; command "true"; restart "never" }

                baseline "the release is open" {
                  field "state" "resource/release" is "open"
                }
                step "work" {
                  baseline "the source is clean" {
                    field "state" "resource/source" is "clean"
                  }
                  retry { attempts 2 }
                }
              }

        "#;
        apply_source(&store, source, "baseline-mission");
        let run = store
            .create_mission_run(&crate::model::MissionRunRequest {
                mission: "baseline".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: Some("run".into()),
                inputs: BTreeMap::new(),
                idempotency_key: "baseline-run".into(),
            })
            .unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );

        reconciler.reconcile_once().unwrap();
        let blocked = store.mission_run(&run.id).unwrap().unwrap();
        assert_eq!(blocked.status, "blocked");
        assert_eq!(blocked.steps[0].status, "pending");
        assert!(
            store
                .desired_subjects()
                .unwrap()
                .iter()
                .all(|subject| subject.subject != format!("agent/{}/worker", run.id))
        );

        for (subject, state, key) in [
            ("resource/release", "open", "release-open"),
            ("resource/source", "clean", "source-clean"),
        ] {
            store
                .append_claim(&ClaimInput {
                    subject: subject.into(),
                    kind: "resource.observed".into(),
                    actor: None,
                    fields: BTreeMap::from([
                        ("kind".into(), Value::String("custom.st3.state".into())),
                        ("state".into(), Value::String(state.into())),
                    ]),
                    evidence: Vec::new(),
                    expected_subject: None,
                    idempotency_key: Some(key.into()),
                })
                .unwrap();
        }
        reconciler.reconcile_once().unwrap();
        let admitted = store.mission_run(&run.id).unwrap().unwrap();
        assert_eq!(admitted.status, "running");
        assert_eq!(admitted.steps[0].status, "ready");
        assert!(
            store
                .desired_subjects()
                .unwrap()
                .iter()
                .any(|subject| subject.subject == format!("agent/{}/worker", run.id))
        );

        store
            .append_claim(&ClaimInput {
                subject: "resource/release".into(),
                kind: "resource.observed".into(),
                actor: None,
                fields: BTreeMap::from([("state".into(), Value::String("closed".into()))]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some("release-closed-after-admission".into()),
            })
            .unwrap();
        store
            .set_step_state(&admitted.steps[0].subject, "failed", Some("test failure"))
            .unwrap();
        store
            .append_claim(&ClaimInput {
                subject: "resource/source".into(),
                kind: "resource.observed".into(),
                actor: None,
                fields: BTreeMap::from([("state".into(), Value::String("dirty".into()))]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some("source-dirty".into()),
            })
            .unwrap();
        for _ in 0..3 {
            reconciler.reconcile_once().unwrap();
        }
        let retried = store.mission_run(&run.id).unwrap().unwrap();
        assert_eq!(retried.status, "running");
        assert_eq!(retried.steps[0].attempt, 2);
        assert_eq!(retried.steps[0].status, "blocked");
        assert!(
            retried.steps[0]
                .blocked_reason
                .as_deref()
                .unwrap()
                .contains("source is clean")
        );
    }

    /// A run blocked on a step baseline of `resource/allocation` being "resumed", evaluated by
    /// skipping passes until it is blocked and nothing it read changes.
    fn run_paused_on_its_allocation(
        store: Arc<Store>,
    ) -> (Arc<Store>, Arc<Reconciler<FakeRuntime>>, String) {
        let source = r#"
            version 2
              resource "allocation" { kind "custom.st3.document-source" }
              resource "elsewhere" { kind "custom.st3.document-source" }

              mission "paused" state="ready" {
                goal "Work only once the allocation resumes."

                  agent "worker" { workspace "/tmp"; command "true"; restart "never" }

                step "fix" {
                  baseline "allocation resumed" {
                    field "state" "resource/allocation" is "resumed"
                  }
                }
              }

        "#;
        apply_source(&store, source, "paused-mission");
        observe_state(&store, "resource/allocation", "paused", "allocation-paused");
        let run = store
            .create_mission_run(&crate::model::MissionRunRequest {
                mission: "paused".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: Some("run".into()),
                inputs: BTreeMap::new(),
                idempotency_key: "paused-run".into(),
            })
            .unwrap();
        let reconciler = Arc::new(
            Reconciler::new(
                store.clone(),
                Arc::new(FakeRuntime::default()),
                "node".into(),
                Arc::new(Notify::new()),
            )
            .skipping_unneeded(true),
        );
        for _ in 0..3 {
            reconciler.reconcile_once().unwrap();
        }
        let blocked = store.mission_run(&run.id).unwrap().unwrap().steps[0].clone();
        assert_eq!(blocked.status, "blocked");
        assert_eq!(
            blocked.blocked_reason.as_deref(),
            Some("step baseline `allocation resumed` does not hold")
        );
        (store, reconciler, run.id)
    }

    fn observe_state(store: &Store, subject: &str, state: &str, key: &str) {
        store
            .append_claim(&ClaimInput {
                subject: subject.into(),
                kind: "resource.observed".into(),
                actor: None,
                fields: BTreeMap::from([("state".into(), Value::String(state.into()))]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some(key.into()),
            })
            .unwrap();
    }

    #[test]
    fn a_change_to_a_baselines_resource_readies_its_step_without_waiting_for_a_pass() {
        let (store, reconciler, run) =
            run_paused_on_its_allocation(Arc::new(Store::open_memory("node").unwrap()));
        let fix = || store.mission_run(&run).unwrap().unwrap().steps[0].clone();
        let before = fix();
        // A claim no run read evaluates no run.
        observe_state(&store, "resource/elsewhere", "resumed", "elsewhere-resumed");
        assert_eq!(reconciler.evaluate_changed_mission_runs().unwrap(), (0, false));

        // No pass runs: the resource's own claim names the run that read it.
        observe_state(&store, "resource/allocation", "resumed", "allocation-resumed");
        assert_eq!(reconciler.evaluate_changed_mission_runs().unwrap(), (1, true));
        let ready = fix();
        assert_eq!((ready.status.as_str(), ready.blocked_reason.as_deref()), ("ready", None));
        assert_eq!(ready.readiness_epoch, before.readiness_epoch + 1);
        assert_eq!(ready.attempt, before.attempt, "the step is not reset");
    }

    #[tokio::test]
    async fn the_post_commit_feed_wakes_the_runs_a_change_touched() {
        // On disk, so this test's reads wait for the follower's writes rather than fail.
        let root = tempfile::tempdir().unwrap();
        let (store, reconciler, run) = run_paused_on_its_allocation(Arc::new(
            Store::open(&root.path().join("store.sqlite"), "node").unwrap(),
        ));
        let before = store.mission_run(&run).unwrap().unwrap().steps[0].clone();
        let follower = tokio::spawn(reconciler.clone().follow_mission_reads());
        observe_state(&store, "resource/allocation", "resumed", "allocation-resumed");
        // What a write through the API does after it commits.
        reconciler.event_notify.send_modify(|generation| *generation += 1);
        // The step is agentless, so the follower's next evaluation admits it and completes it:
        // `ready` can be gone before any read of the run. Its state history keeps it, and the
        // follower wakes the pass after every evaluation that wrote, after that write.
        let readied = || {
            store
                .claims_page(Some(&before.subject), None, 0, None, false, 500)
                .unwrap()
                .claims
                .into_iter()
                .find(|claim| {
                    claim.kind == "step-run.state"
                        && claim.body.pointer("/fields/status").and_then(Value::as_str)
                            == Some("ready")
                })
        };
        let ready = loop {
            if let Some(ready) = readied() {
                break ready;
            }
            reconciler.notify.notified().await;
        };
        assert_eq!(ready.body.pointer("/fields/reason"), Some(&Value::Null));
        assert_eq!(
            ready.body.pointer("/fields/readiness_epoch"),
            Some(&Value::from(before.readiness_epoch + 1))
        );
        follower.abort();
    }

    /// An agentless step's exec exits and its `driver exec` wrapper reports the exit. The next
    /// step's exec starts from that change alone: the follower completes the first step, readies
    /// the second, declares its exec and starts it, with no pass, which would first wait out
    /// `StartSpacing`.
    #[tokio::test]
    async fn an_exec_steps_exit_starts_the_next_steps_exec_without_a_pass() {
        use serde_json::json;
        // On disk, so this test's reads wait for the follower's writes rather than fail.
        let root = tempfile::tempdir().unwrap();
        let store = Arc::new(Store::open(&root.path().join("store.sqlite"), "node").unwrap());
        apply_source(
            &store,
            r#"
version 2
mission "relay" state="ready" {
  goal "Hand off from one agentless exec to the next."
  step "first" {
    agentless
    exec "first" { host "node"; workspace "/tmp"; command "true"; restart "never" }
    gate "first succeeded" { field "exit_code" "exec/${ST_MISSION_RUN}/first" is 0 }
  }
  step "second" {
    agentless
    depends-on { step "first" "completed" }
    exec "second" { host "node"; workspace "/tmp"; command "true"; restart "never" }
    gate "second succeeded" { field "exit_code" "exec/${ST_MISSION_RUN}/second" is 0 }
  }
}
"#,
            "relay",
        );
        let run = store
            .create_mission_run(&crate::model::MissionRunRequest {
                mission: "relay".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: Some("run".into()),
                inputs: BTreeMap::new(),
                idempotency_key: "relay-run".into(),
            })
            .unwrap();
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Arc::new(Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        ));
        let started = |step: &str| {
            store
                .desired_subject_with_writer(&format!("exec/{}/{step}", run.id))
                .unwrap()
                .is_some_and(|(desired, _)| {
                    let id = &desired.member.as_ref().unwrap().runtime_id;
                    runtime.started_members.lock().unwrap().iter().any(|member| &member.runtime_id == id)
                })
        };
        for _ in 0..4 {
            if started("first") {
                break;
            }
            reconciler.reconcile_once().unwrap();
        }
        assert!(started("first"), "a pass starts the first step's exec");
        assert!(!started("second"), "the first step has not completed");
        let follower = tokio::spawn(reconciler.clone().follow_mission_reads());
        store
            .append_claim(&ClaimInput {
                subject: format!("exec/{}/first", run.id),
                kind: "runtime.observed".into(),
                actor: Some(format!("exec/{}/first", run.id)),
                fields: BTreeMap::from([
                    ("status".into(), json!("exited")),
                    ("exit_code".into(), json!(0)),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: None,
            })
            .unwrap();
        // What the API does after the wrapper's claim commits.
        reconciler.event_notify.send_modify(|generation| *generation += 1);
        // A bound for a loaded machine, not an expected duration.
        tokio::time::timeout(Duration::from_secs(60), async {
            while !started("second") {
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .expect("the second step's exec starts from the first exec's exit alone");
        let steps = store.mission_run(&run.subject).unwrap().unwrap().steps;
        assert_eq!(
            steps.iter().map(|step| (step.step.as_str(), step.status.as_str())).collect::<Vec<_>>(),
            [("first", "completed"), ("second", "working")]
        );
        follower.abort();
    }

    /// `missions start` commits a new run and wakes the follower. The run's first step's exec
    /// starts from that change alone: no pass, which would first wait out `StartSpacing`, has to
    /// evaluate the run first. A host that does not originate the run leaves it alone.
    #[test]
    fn a_new_runs_first_step_starts_without_a_pass() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"
version 2
mission "single" state="ready" {
  goal "Start one agentless exec."
  step "first" {
    agentless
    exec "first" { host "node"; workspace "/tmp"; command "true"; restart "never" }
    gate "first succeeded" { field "exit_code" "exec/${ST_MISSION_RUN}/first" is 0 }
  }
}
"#,
            "single",
        );
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler =
            Reconciler::new(store.clone(), runtime.clone(), "node".into(), Arc::new(Notify::new()));
        let elsewhere = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "elsewhere".into(),
            Arc::new(Notify::new()),
        );
        // Each follower's cursor starts before the run exists, as it does in a running daemon.
        assert_eq!(reconciler.evaluate_changed_mission_runs().unwrap(), (0, false));
        assert_eq!(elsewhere.evaluate_changed_mission_runs().unwrap(), (0, false));
        let run = store
            .create_mission_run(&crate::model::MissionRunRequest {
                mission: "single".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: Some("run".into()),
                inputs: BTreeMap::new(),
                idempotency_key: "single-run".into(),
            })
            .unwrap();
        assert_eq!(
            elsewhere.evaluate_changed_mission_runs().unwrap(),
            (0, false),
            "another host's run is not its to evaluate"
        );
        let started = || {
            store
                .desired_subject_with_writer(&format!("exec/{}/first", run.id))
                .unwrap()
                .is_some_and(|(desired, _)| {
                    let id = &desired.member.as_ref().unwrap().runtime_id;
                    runtime.started_members.lock().unwrap().iter().any(|member| &member.runtime_id == id)
                })
        };
        // The follower's chain of evaluations after the run's creation, as
        // `follow_mission_reads` runs it: each evaluation moves the step one state.
        for _ in 0..=MISSION_READS_CONTINUATIONS {
            if started() {
                break;
            }
            reconciler.evaluate_changed_mission_runs().unwrap();
        }
        assert!(started(), "the new run's first step's exec starts without a pass");
        let steps = store.mission_run(&run.subject).unwrap().unwrap().steps;
        assert_eq!(steps[0].status, "working");
    }

    #[test]
    fn mission_products_and_gates_hold_completion_and_record_evidence() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
            version 2

              mission "release" state="ready" {
                goal "Publish an approved result."
                completion { when "all-steps-exhausted" }
                produces {
                  resource "result" { kind "custom.st3.release-result"; state "published" }
                }
                gate "the result is approved" {
                  field "approval" "resource/result" is "yes"
                }
                step "work" { }
              }

        "#;
        apply_source(&store, source, "release-mission");
        let run = store
            .create_mission_run(&crate::model::MissionRunRequest {
                mission: "release".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: Some("run".into()),
                inputs: BTreeMap::new(),
                idempotency_key: "release-run".into(),
            })
            .unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        for _ in 0..3 {
            reconciler.reconcile_once().unwrap();
        }
        let waiting = store.mission_run(&run.id).unwrap().unwrap();
        assert_eq!(waiting.steps[0].status, "completed");
        assert_eq!(waiting.status, "running");

        store
            .append_claim(&ClaimInput {
                subject: "resource/result".into(),
                kind: "resource.observed".into(),
                actor: None,
                fields: BTreeMap::from([
                    (
                        "kind".into(),
                        Value::String("custom.st3.release-result".into()),
                    ),
                    ("state".into(), Value::String("published".into())),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some("result-published".into()),
            })
            .unwrap();
        reconciler.reconcile_once().unwrap();
        assert_eq!(
            store.mission_run(&run.id).unwrap().unwrap().status,
            "running"
        );

        store
            .append_claim(&ClaimInput {
                subject: "resource/result".into(),
                kind: "resource.observed".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("state".into(), Value::String("published".into())),
                    ("approval".into(), Value::String("yes".into())),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some("result-approved".into()),
            })
            .unwrap();
        reconciler.reconcile_once().unwrap();
        reconciler.reconcile_once().unwrap();
        let completed = store.mission_run(&run.id).unwrap().unwrap();
        assert_eq!(completed.status, "completed");
        let evidence = store
            .claims_page(None, None, 0, None, false, 500)
            .unwrap()
            .claims
            .into_iter()
            .find(|claim| {
                claim.kind == "gate.result"
                    && claim.body.pointer("/fields/gate").and_then(Value::as_str)
                        == Some("the result is approved")
            })
            .expect("the gate did not record evidence");
        assert_eq!(
            evidence
                .body
                .pointer("/fields/verdict")
                .and_then(Value::as_str),
            Some("pass")
        );
    }

    #[test]
    fn step_members_and_gates_receive_automatic_st_context() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
            version 2

              mission "context" state="ready" {
                goal "Expose the run context."

                  exec "mission-task" {
                    command "true"
                    env { CUSTOM_PATH "/opt/st3-shims:${PATH}" }
                  }

                step "work" {

                    exec "task" {
                      command "true"
                      env { CUSTOM_RUN "${ST_MISSION_RUN}" }
                    }

                  gate "verify context" {
                    exec "true"
                    host "node"
                    workspace "."
                    time-limit "1m"
                  }
                }
              }

        "#;
        apply_source(&store, source, "context-mission");
        let run = store
            .create_mission_run(&crate::model::MissionRunRequest {
                mission: "context".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: Some("run".into()),
                inputs: BTreeMap::new(),
                idempotency_key: "context-run".into(),
            })
            .unwrap();
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(
            store,
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        );
        for _ in 0..3 {
            reconciler.reconcile_once().unwrap();
        }
        let task = runtime
            .started_members
            .lock()
            .unwrap()
            .iter()
            .find(|member| member.environment.contains_key("CUSTOM_RUN"))
            .cloned()
            .expect("the step task did not start");
        for name in [
            "ST_MISSION",
            "ST_MISSION_REVISION",
            "ST_MISSION_RUN",
            "ST_RUN_GENERATION",
            "ST_ROOT_MISSION_RUN",
            "ST_WORKSPACE",
            "ST_REQUESTER",
            "ST_STEP",
            "ST_STEP_RUN",
            "ST_ATTEMPT",
            "ST_ASSIGNEE",
            "ST_PARENT_STEP_RUN",
        ] {
            assert!(task.environment.contains_key(name), "missing {name}");
        }
        assert!(!task.environment.contains_key("ST_AGENT"));
        assert_eq!(task.environment["CUSTOM_RUN"], run.id);
        let mission_task = runtime
            .started_members
            .lock()
            .unwrap()
            .iter()
            .find(|member| member.environment.contains_key("CUSTOM_PATH"))
            .cloned()
            .expect("the mission task did not start");
        assert_eq!(
            mission_task.environment["CUSTOM_PATH"],
            "/opt/st3-shims:${PATH}"
        );

        runtime.execs.lock().unwrap().insert(
            task.runtime_id.clone(),
            RuntimeObservation {
                runtime_id: task.runtime_id,
                terminal: false,
                status: "exited".into(),
                exit_code: Some(0),
                incarnation_id: Some("task-one".into()),
            },
        );
        for _ in 0..3 {
            reconciler.reconcile_once().unwrap();
        }
        let gate = runtime
            .started_members
            .lock()
            .unwrap()
            .iter()
            .find(|member| member.driver.as_deref() == Some("mechanical-gate"))
            .cloned()
            .expect("the mechanical gate did not start");
        assert_eq!(gate.environment["ST_GATE"], "verify context");
        assert_eq!(gate.environment["ST_MISSION_RUN"], run.id);
        assert_eq!(gate.environment["ST_STEP"], "work");
    }

