    #[test]
    fn publication_launch_evidence_is_read_once_for_repeated_running_seat_passes() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let count = 12;
        let source = format!(
            "version 2\n{}",
            (0..count)
                .map(|i| format!(
                    "agent \"example/worker-{i}\" {{ workspace \"/tmp\"; command \"true\"; }}\n"
                ))
                .collect::<String>()
        );
        apply_source(&store, &source, "many-seats");
        let runtime = Arc::new(FakeRuntime::default());
        for (i, desired) in store.desired_subjects().unwrap().iter().enumerate() {
            let incarnation = format!("incarnation-{i}");
            let token = store
                .selected_desired_token(&desired.subject)
                .unwrap()
                .unwrap();
            store
                .append_claim(&ClaimInput {
                    subject: desired.subject.clone(),
                    kind: "runtime.action.succeeded".into(),
                    actor: None,
                    fields: BTreeMap::from([
                        ("action".into(), serde_json::json!("start")),
                        ("incarnation_id".into(), serde_json::json!(incarnation)),
                        ("desired_token".into(), serde_json::json!(token)),
                    ]),
                    evidence: vec![],
                    expected_subject: None,
                    idempotency_key: None,
                })
                .unwrap();
            let member = desired.member.as_ref().unwrap();
            runtime.ptys.lock().unwrap().push(RuntimeObservation {
                runtime_id: member.runtime_id.clone(),
                terminal: true,
                status: "running".into(),
                exit_code: None,
                incarnation_id: Some(incarnation),
            });
        }
        let reconciler = Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        );
        reconciler.reconcile_once().unwrap();
        assert_eq!(
            reconciler
                .launch_evidence_reads
                .load(std::sync::atomic::Ordering::Relaxed),
            count
        );
        for _ in 0..4 {
            reconciler.reconcile_once().unwrap();
        }
        assert_eq!(
            reconciler
                .launch_evidence_reads
                .load(std::sync::atomic::Ordering::Relaxed),
            count
        );
        let desired = store.desired_subjects().unwrap();
        let observations = runtime.ptys.lock().unwrap().clone();
        let source_epoch = store.publication_cache_epoch();
        for (subject, observation) in desired.iter().zip(&observations) {
            store.append_claim(&ClaimInput {
                subject: subject.subject.clone(), kind: "runtime.observed".into(),
                actor: Some("agent/example/writer".into()),
                fields: BTreeMap::from([
                    ("status".into(), serde_json::json!("running")),
                    ("incarnation_id".into(), serde_json::json!(observation.incarnation_id)),
                ]), evidence: vec![], expected_subject: None, idempotency_key: None,
            }).unwrap();
        }
        assert_eq!(store.publication_cache_epoch(), source_epoch,
            "runtime observations must not invalidate retained launch proofs");
        let scope = smallclaims::sqlite::work::SqliteWorkScope::start();
        for _ in 0..4 {
            for (subject, observation) in desired.iter().zip(&observations) {
                assert!(
                    reconciler
                        .declared_launch_changes(subject, observation)
                        .unwrap()
                        .is_none()
                );
            }
        }
        let cost = scope.finish();
        assert_eq!(
            cost.statements, 0,
            "found evidence must use no SQLite statements on repeated passes: {cost:?}"
        );
        assert!(runtime.stops.lock().unwrap().is_empty());
    }

    #[test]
    fn failed_start_restart_authority_expires_without_closing_the_producer() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            "version 2\nagent \"example/worker\" { workspace \"/tmp\"; command \"true\"; }",
            "original",
        );
        let subject = "agent/example/worker";
        let desired = store.desired_subject_with_writer(subject).unwrap().unwrap().0;
        let token = store.selected_desired_token(subject).unwrap().unwrap();
        let mut operation = RuntimeStartOperation {
            id: uuid::Uuid::now_v7().to_string(),
            subject: subject.into(),
            owner: "fixture".into(),
            body: serde_json::json!({
                "subject": desired, "selected_token": token, "request": null,
                "member": desired.member, "reason": "fixture failed start",
            }),
            revoked_by: None,
            finished: false,
            result: None,
            applied: false,
            cleanup_verified: false,
            dispatched: false,
            receipted: false,
        };
        store.admit_runtime_start(&mut operation, 2).unwrap();
        store.finish_runtime_start(&operation.id, &serde_json::json!({
            "error": "producer closure unverified", "producer_closed": false,
        })).unwrap();
        let request = store.append_claim(&ClaimInput {
            subject: subject.into(), kind: "runtime.action.requested".into(),
            actor: Some("person/avery".into()),
            fields: BTreeMap::from([("action".into(), Value::from("restart"))]),
            evidence: vec![token], expected_subject: None,
            idempotency_key: Some("age-bounded-restart".into()),
        }).unwrap();
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(store.clone(), runtime.clone(), "node".into(), Arc::new(Notify::new()));
        let deadline = request.accepted_at_unix_ms + 60 * 60 * 1000;
        assert!(!reconciler.retire_obsolete_failed_restart(&desired, deadline).unwrap());
        assert!(reconciler.retire_obsolete_failed_restart(&desired, deadline + 1).unwrap());
        let result = store.operation_claim(&format!("agent-restart-completed:{}", request.id))
            .unwrap().unwrap();
        assert_eq!(result.body["fields"]["operation_status"], "retired");
        assert_eq!(result.body["evidence"][0], request.id);
        let pending = store.runtime_start_for(subject).unwrap().unwrap();
        assert_eq!(pending.id, operation.id);
        assert!(!pending.cleanup_verified);
    }

    #[test]
    fn publication_found_launch_cache_invalidates_on_retained_source_mutations() {
        // Mutate the native source tables here to cover the same-frontier seam which
        // the append feed cannot see. Native admission/repair/trim paths are exercised
        // separately by the materialized evidence coverage tests.
        for mutation in [
            "local-trim",
            "shared-trim",
            "definition-trim",
            "definition-repair",
            "replay",
        ] {
            let store = Arc::new(Store::open_memory("node").unwrap());
            apply_source(
                &store,
                "version 2\nagent \"example/worker\" { workspace \"/tmp\"; command \"true\"; }",
                "original",
            );
            let subject = "agent/example/worker";
            let token = store.selected_desired_token(subject).unwrap().unwrap();
            let receipt = store
                .append_claim(&ClaimInput {
                    subject: subject.into(),
                    kind: "runtime.action.succeeded".into(),
                    actor: (mutation == "shared-trim").then(|| "agent/fixture".into()),
                    fields: BTreeMap::from([
                        ("action".into(), serde_json::json!("start")),
                        ("incarnation_id".into(), serde_json::json!("one")),
                        ("desired_token".into(), serde_json::json!(token)),
                    ]),
                    evidence: vec![],
                    expected_subject: None,
                    idempotency_key: None,
                })
                .unwrap();
            apply_source(
                &store,
                "version 2\nagent \"example/worker\" { workspace \"/tmp\"; command \"false\"; }",
                "proposed",
            );
            let proposed = store
                .desired_subject_with_writer(subject)
                .unwrap()
                .unwrap()
                .0;
            let observation = RuntimeObservation {
                runtime_id: proposed.member.as_ref().unwrap().runtime_id.clone(),
                terminal: true,
                status: "running".into(),
                exit_code: None,
                incarnation_id: Some("one".into()),
            };
            let reconciler = Reconciler::new(
                store.clone(),
                Arc::new(FakeRuntime::default()),
                "node".into(),
                Arc::new(Notify::new()),
            );
            assert_eq!(
                reconciler
                    .declared_launch_changes(&proposed, &observation)
                    .unwrap(),
                Some(vec!["launch"]),
                "{mutation}"
            );
            let epoch = store.publication_cache_epoch();
            {
                let mut writer = store.connection.write();
                let tx = writer.transaction().unwrap();
                tx.execute(/* sqlite-large-value: allow-for-now lv-h4416617b23b7 owner=fractal_reconcile::reconcile::tests TODO=bound-or-reference-values-and-reclamation */ "DELETE FROM local_publication_starts", [])
                    .unwrap();
                tx.rollback().unwrap();
            }
            assert_eq!(
                store.publication_cache_epoch(),
                epoch,
                "rollback must retain valid cache"
            );
            {
                let mut writer = store.connection.write();
                let tx = writer.transaction().unwrap();
                match mutation {
                    "local-trim" => {
                        tx.execute(/* sqlite-large-value: allow-for-now lv-h474b1baeda3f owner=fractal_reconcile::reconcile::tests TODO=bound-or-reference-values-and-reclamation */ "DELETE FROM local_observations WHERE subject=?1 AND kind='runtime.action.succeeded'", [subject]).unwrap();
                    }
                    "shared-trim" => {
                        tx.execute(/* sqlite-large-value: allow-for-now lv-h547f21c8d694 owner=fractal_reconcile::reconcile::tests TODO=prepare-body-and-predecessor-values */ "DELETE FROM claims WHERE id=?1", [&receipt.id])
                            .unwrap();
                    }
                    "definition-trim" => {
                        // Native trimming retires operation identities before their
                        // canonical claims. Preserve that foreign-key ordering here.
                        tx.execute(
                            /* sqlite-large-value: allow-for-now lv-h64896ad480c9 owner=fractal_reconcile::reconcile::tests TODO=bound-or-reference-values-and-reclamation */ "DELETE FROM operations WHERE canonical_claim_id=?1",
                            [&token],
                        )
                        .unwrap();
                        tx.execute(/* sqlite-large-value: allow-for-now lv-hc069f66097a6 owner=fractal_reconcile::reconcile::tests TODO=prepare-body-and-predecessor-values */ "DELETE FROM claims WHERE id=?1", [&token])
                            .unwrap();
                    }
                    "definition-repair" => {
                        tx.execute(
                            /* sqlite-large-value: allow-for-now lv-hbb1b1fcd43a4 owner=fractal_reconcile::reconcile::tests TODO=bound-or-reference-values-and-reclamation */ "INSERT INTO projection_digest_repaired_claims(id) VALUES(?1)",
                            [&token],
                        )
                        .unwrap();
                    }
                    "replay" => {
                        tx.execute(/* sqlite-large-value: allow-for-now lv-h9c242cf49e35 owner=fractal_reconcile::reconcile::tests TODO=bound-or-reference-values-and-reclamation */ "DELETE FROM local_publication_bootstrap", [])
                            .unwrap();
                    }
                    _ => unreachable!(),
                }
                tx.commit().unwrap();
            }
            assert_ne!(store.publication_cache_epoch(), epoch, "{mutation}");
            assert!(
                store.publication_launch(subject, "one").unwrap().is_none(),
                "{mutation}"
            );
            assert_eq!(
                reconciler
                    .declared_launch_changes(&proposed, &observation)
                    .unwrap(),
                None,
                "retired or unready proof must not cause a restart: {mutation}"
            );
        }
    }

