    #[test]
    fn fractal_only_authored_resume_selectors_survive_launch_selection() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let workspace = tempfile::tempdir().unwrap();
        let transcript = workspace.path().join("native.jsonl");
        apply_source(&store, &format!(r#"
version 2
agent "worker" {{
  workspace {:?}
  harness "omp" {{}}
  env {{
    FRACTAL_NATIVE_RESUME_SESSION "requested-session"
    FRACTAL_NATIVE_RESUME_PATH {:?}
  }}
}}
"#, workspace.path().to_str().unwrap(), transcript.to_str().unwrap()), "fractal-resume");
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(store, runtime.clone(), "node".into(), Arc::new(Notify::new()));
        reconciler.reconcile_once().unwrap();
        let members = runtime.started_members.lock().unwrap_or_else(|error| error.into_inner());
        assert_eq!(members.len(), 1);
        let env = &members[0].environment;
        assert_eq!(env[crate::suspension::RESUME_ENV], "requested-session");
        assert_eq!(env["FRACTAL_NATIVE_RESUME_SESSION"], "requested-session");
        assert_eq!(env[crate::rollout::RESUME_PATH_ENV], transcript.to_str().unwrap());
        assert_eq!(env["FRACTAL_NATIVE_RESUME_PATH"], transcript.to_str().unwrap());
        assert!(!env.contains_key(crate::suspension::CONTINUE_ENV));
        assert!(!env.contains_key("FRACTAL_NATIVE_CONTINUE_SESSION"));
    }

    fn account_source(logins: &Path, workspace: &Path, harness_body: &str) -> String {
        format!(
            r#"
            version 2

              account "ada/one" {{
                provider "openai"
                owner "person/ada"
                login {one:?}
              }}
              account "ada/two" {{
                provider "openai"
                owner "person/ada"
                login {two:?}
              }}
              agent "worker" {{
                workspace {workspace:?}
                harness "codex" {{ {harness_body} }}
              }}
              agent "plain" {{
                workspace {workspace:?}
                harness "codex" {{}}
              }}
        "#,
            one = logins.join("one").display().to_string(),
            two = logins.join("two").display().to_string(),
            workspace = workspace.display().to_string(),
        )
    }

    #[test]
    fn a_seat_bound_to_an_account_starts_on_its_login_and_an_unbound_seat_is_untouched() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let workspace = tempfile::tempdir().unwrap();
        let logins = tempfile::tempdir().unwrap();
        fs::create_dir(logins.path().join("one")).unwrap();
        fs::create_dir(logins.path().join("two")).unwrap();
        let source = account_source(logins.path(), workspace.path(), "account \"ada/two\"");
        apply_source(&store, &source, "bound-account");
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(
            store,
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        );

        reconciler.reconcile_once().unwrap();

        let members = runtime.started_members.lock().unwrap();
        let environment = |seat: &str| {
            members
                .iter()
                .find(|member| member.environment.get("ST_AGENT").map(String::as_str) == Some(seat))
                .unwrap_or_else(|| panic!("{seat} did not start"))
                .environment
                .clone()
        };
        let bound = environment("agent/node.worker");
        assert_eq!(
            bound.get("CODEX_HOME").map(String::as_str),
            Some(logins.path().join("two").to_str().unwrap())
        );
        assert_eq!(
            bound.get("ST3_ACCOUNT").map(String::as_str),
            Some("ada/two")
        );
        let plain = environment("agent/node.plain");
        assert!(plain.contains_key("CODEX_HOME") && !plain.contains_key("ST3_ACCOUNT"));
    }

