    /// A headless root `app` with the named execs, applied and launched once, each exec
    /// observed running.
    fn headless_root_with_running_execs(
        names: &[&str],
    ) -> (Arc<Store>, Arc<FakeRuntime>, Reconciler<FakeRuntime>) {
        headless_root_with_running_execs_skipping(names, false)
    }

    fn headless_root_with_running_execs_skipping(
        names: &[&str],
        skipping: bool,
    ) -> (Arc<Store>, Arc<FakeRuntime>, Reconciler<FakeRuntime>) {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let execs = names
            .iter()
            .map(|name| format!("  exec \"{name}\" {{ command \"sleep infinity\" }}\n"))
            .collect::<String>();
        apply_source(
            &store,
            &format!("version 2\nagent \"app\" {{\n  workspace \"/tmp\"\n  restart \"always\"\n{execs}}}\n"),
            "headless-root",
        );
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        )
        .skipping_unneeded(skipping);
        reconciler.reconcile_once().unwrap();
        for name in names {
            runtime.execs.lock().unwrap().insert(
                format!("exec.node.app.{name}"),
                RuntimeObservation {
                    runtime_id: format!("exec.node.app.{name}"),
                    terminal: false,
                    status: "running".into(),
                    exit_code: None,
                    incarnation_id: Some(format!("{name}-one")),
                },
            );
        }
        reconciler.reconcile_once().unwrap();
        (store, runtime, reconciler)
    }

    fn actual_status(store: &Store, subject: &str) -> Option<String> {
        store
            .latest_actual_value(subject)
            .unwrap()
            .and_then(|actual| {
                actual_field(&actual, "status")
                    .and_then(Value::as_str)
                    .map(str::to_owned)
            })
    }

    fn end_exec(runtime: &FakeRuntime, runtime_id: &str, status: &str) {
        runtime
            .execs
            .lock()
            .unwrap()
            .get_mut(runtime_id)
            .unwrap()
            .status = status.into();
    }

    #[test]
    fn headless_root_stop_stops_its_nested_execs_and_settles_after_they_end() {
        let (store, runtime, reconciler) = headless_root_with_running_execs(&["web", "worker"]);
        let started = runtime.starts.lock().unwrap().len();
        assert_eq!(started, 2, "both execs launch: {:?}", runtime.starts.lock().unwrap());
        apply_source(&store, "version 2\nstop \"agent/node.app\"\n", "stop-root");
        reconciler.reconcile_once().unwrap();
        let mut stops = runtime.stops.lock().unwrap().clone();
        stops.sort();
        assert_eq!(stops, ["exec.node.app.web", "exec.node.app.worker"]);
        // Both still run: the root is not stopped, and nothing starts again.
        assert_ne!(actual_status(&store, "agent/node.app").as_deref(), Some("absent"));
        assert_ne!(actual_status(&store, "agent/node.app").as_deref(), Some("stopped"));
        assert_eq!(runtime.starts.lock().unwrap().len(), started);
        end_exec(&runtime, "exec.node.app.web", "stopped");
        reconciler.reconcile_once().unwrap();
        assert_ne!(
            actual_status(&store, "agent/node.app").as_deref(),
            Some("absent"),
            "one exec still runs"
        );
        end_exec(&runtime, "exec.node.app.worker", "stopped");
        reconciler.reconcile_once().unwrap();
        for subject in ["exec/node.app/web", "exec/node.app/worker"] {
            assert_eq!(actual_status(&store, subject).as_deref(), Some("stopped"));
        }
        assert_eq!(actual_status(&store, "agent/node.app").as_deref(), Some("absent"));
        // Restart always does not bring either back.
        end_exec(&runtime, "exec.node.app.web", "exited");
        reconciler.reconcile_once().unwrap();
        assert_eq!(runtime.starts.lock().unwrap().len(), started);
    }

    #[test]
    fn headless_root_second_stop_changes_nothing() {
        let (store, runtime, reconciler) = headless_root_with_running_execs(&["web"]);
        apply_source(&store, "version 2\nstop \"agent/node.app\"\n", "stop-root");
        reconciler.reconcile_once().unwrap();
        end_exec(&runtime, "exec.node.app.web", "stopped");
        reconciler.reconcile_once().unwrap();
        let stops = runtime.stops.lock().unwrap().len();
        apply_source(&store, "version 2\nstop \"agent/node.app\"\n", "stop-root-again");
        reconciler.reconcile_once().unwrap();
        reconciler.reconcile_once().unwrap();
        assert_eq!(runtime.stops.lock().unwrap().len(), stops);
        assert_eq!(actual_status(&store, "agent/node.app").as_deref(), Some("absent"));
    }

    #[test]
    fn headless_root_stop_cleans_up_an_exec_that_exited_on_its_own() {
        let (store, runtime, reconciler) = headless_root_with_running_execs(&["web"]);
        end_exec(&runtime, "exec.node.app.web", "exited");
        apply_source(&store, "version 2\nstop \"agent/node.app\"\n", "stop-root");
        reconciler.reconcile_once().unwrap();
        assert!(runtime.stops.lock().unwrap().is_empty());
        assert_eq!(
            &*runtime.leftovers.lock().unwrap(),
            &[("exec.node.app.web".to_owned(), false)]
        );
        assert_eq!(actual_status(&store, "agent/node.app").as_deref(), Some("absent"));
    }

    #[test]
    fn headless_root_stays_unsettled_and_reports_a_failed_exec_stop() {
        let (store, runtime, reconciler) = headless_root_with_running_execs(&["web", "worker"]);
        runtime
            .failed_stops
            .lock()
            .unwrap()
            .insert("exec.node.app.web".into());
        apply_source(&store, "version 2\nstop \"agent/node.app\"\n", "stop-root");
        reconciler.reconcile_once().unwrap();
        // The healthy exec's stop is not starved by the failing one.
        assert!(runtime.stops.lock().unwrap().contains(&"exec.node.app.worker".to_owned()));
        assert!(
            store
                .member_reconcile_fault("exec/node.app/web", None)
                .unwrap()
                .unwrap()
                .contains("fake stop failed")
        );
        end_exec(&runtime, "exec.node.app.worker", "stopped");
        reconciler.reconcile_once().unwrap();
        assert_ne!(actual_status(&store, "agent/node.app").as_deref(), Some("absent"));
    }

    #[test]
    fn headless_root_settles_when_its_exec_ends_between_incremental_passes() {
        // Skipping mode: a stop item is evaluated again only when something it read changed.
        let (store, runtime, reconciler) =
            headless_root_with_running_execs_skipping(&["web"], true);
        apply_source(&store, "version 2\nstop \"agent/node.app\"\n", "stop-root");
        reconciler.reconcile_once().unwrap();
        assert_eq!(&*runtime.stops.lock().unwrap(), &["exec.node.app.web"]);
        assert_ne!(actual_status(&store, "agent/node.app").as_deref(), Some("absent"));
        // Nothing is written: only the exec's own status changes.
        reconciler.reconcile_once().unwrap();
        assert_ne!(actual_status(&store, "agent/node.app").as_deref(), Some("absent"));
        end_exec(&runtime, "exec.node.app.web", "stopped");
        reconciler.reconcile_once().unwrap();
        assert_eq!(actual_status(&store, "agent/node.app").as_deref(), Some("absent"));
    }

    #[test]
    fn headless_root_settles_when_its_pty_ends_between_incremental_passes() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            "version 2\nagent \"app\" {\n  workspace \"/tmp\"\n  restart \"always\"\n  pty \"shell\" { command \"sleep infinity\" }\n}\n",
            "headless-root-pty",
        );
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        )
        .skipping_unneeded(true);
        reconciler.reconcile_once().unwrap();
        let runtime_id = runtime
            .started_members
            .lock()
            .unwrap()
            .iter()
            .find(|member| member.terminal)
            .map(|member| member.runtime_id.clone())
            .expect("the pty task launches");
        let running = RuntimeObservation {
            runtime_id: runtime_id.clone(),
            terminal: true,
            status: "running".into(),
            exit_code: None,
            incarnation_id: Some("shell-one".into()),
        };
        runtime.ptys.lock().unwrap().push(running.clone());
        reconciler.reconcile_once().unwrap();
        apply_source(&store, "version 2\nstop \"agent/node.app\"\n", "stop-root");
        reconciler.reconcile_once().unwrap();
        assert_ne!(actual_status(&store, "agent/node.app").as_deref(), Some("absent"));
        // Only the pty's own state changes: the root's stop item must be needed again.
        runtime.ptys.lock().unwrap().clear();
        for _ in 0..3 {
            reconciler.reconcile_once().unwrap();
        }
        assert_eq!(actual_status(&store, "agent/node.app").as_deref(), Some("absent"));
    }

    #[test]
    fn headless_root_retries_after_its_exec_could_not_be_observed() {
        let (store, runtime, reconciler) = headless_root_with_running_execs(&["web"]);
        runtime
            .failed_observes
            .lock()
            .unwrap()
            .insert("exec.node.app.web".into());
        apply_source(&store, "version 2\nstop \"agent/node.app\"\n", "stop-root");
        reconciler.reconcile_once().unwrap();
        assert_ne!(actual_status(&store, "agent/node.app").as_deref(), Some("absent"));
        runtime.failed_observes.lock().unwrap().clear();
        end_exec(&runtime, "exec.node.app.web", "stopped");
        reconciler.reconcile_once().unwrap();
        assert_eq!(actual_status(&store, "agent/node.app").as_deref(), Some("absent"));
    }

    #[test]
    fn a_later_fault_or_decision_claim_does_not_unobserve_a_running_root() {
        // Negative control for the settle-absent filter: a root observed running keeps that
        // status across a later claim that carries none, so its stop still reaches the runtime
        // and the root is not settled absent.
        let (store, runtime, reconciler) = headless_root_with_running_execs(&["web"]);
        end_exec(&runtime, "exec.node.app.web", "stopped");
        runtime.ptys.lock().unwrap().push(RuntimeObservation {
            runtime_id: "pty.node.app".into(),
            terminal: true,
            status: "running".into(),
            exit_code: None,
            incarnation_id: Some("app-one".into()),
        });
        reconciler
            .record_once(
                "agent/node.app",
                "runtime.observed",
                BTreeMap::from([
                    ("status".into(), Value::String("running".into())),
                    ("runtime_id".into(), Value::String("pty.node.app".into())),
                    ("reachability".into(), Value::String("reachable".into())),
                ]),
            )
            .unwrap();
        reconciler
            .record_once(
                "agent/node.app",
                "runtime.reconcile-decision",
                BTreeMap::from([
                    ("decision".into(), Value::String("member-fault".into())),
                    ("reason".into(), Value::String("a later fault".into())),
                ]),
            )
            .unwrap();
        assert_eq!(actual_status(&store, "agent/node.app").as_deref(), Some("running"));
        apply_source(&store, "version 2\nstop \"agent/node.app\"\n", "stop-root");
        reconciler.reconcile_once().unwrap();
        assert_ne!(actual_status(&store, "agent/node.app").as_deref(), Some("absent"));
        assert!(
            runtime.stops.lock().unwrap().iter().any(|id| id == "pty.node.app"),
            "stops: {:?}",
            runtime.stops.lock().unwrap()
        );
    }

    #[test]
    fn a_superseded_member_stops_even_when_its_render_now_fails() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let workspace = tempfile::tempdir().unwrap();
        let first = format!(
            r#"version 2
mission "render-retire" state="ready" {{
 goal "Retire a broken renderer."
 agent "worker" {{ workspace {:?}; command "true"; render {{ file "output" "ready" }} }}
 step "wait" {{ goal "Wait for replacement."; gate "hold" {{ field "state" "resource/not-ready" is "ready" }} }}
}}
"#,
            workspace.path().display().to_string()
        );
        apply_source(&store, &first, "render-retire-first");
        let first_revision = store.mission_spec("render-retire", None).unwrap().unwrap();
        let second = r#"version 2
mission "render-retire" state="ready" { goal "Retire a broken renderer."; step "wait" { goal "Replacement without the worker." } }
"#;
        apply_source(&store, second, "render-retire-second");
        let intent = parse_intent(second, "node").unwrap();
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "render-retire".into(),
                revision: Some(first_revision.revision),
                workspace: workspace.path().display().to_string(),
                requester: Some("person/test".into()),
                mode: None,
                inputs: BTreeMap::new(),
                idempotency_key: "render-retire-run".into(),
            })
            .unwrap();
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        );
        for _ in 0..3 {
            reconciler.reconcile_once().unwrap();
        }
        let member = store
            .desired_subjects()
            .unwrap()
            .into_iter()
            .find(|s| s.subject == format!("agent/{}/worker", run.id))
            .unwrap();
        let runtime_id = member.member.as_ref().unwrap().runtime_id.clone();
        runtime.ptys.lock().unwrap().push(RuntimeObservation {
            runtime_id: runtime_id.clone(),
            terminal: true,
            status: "running".into(),
            exit_code: None,
            incarnation_id: Some("retired-one".into()),
        });
        fs::remove_file(workspace.path().join("output")).unwrap();
        fs::create_dir(workspace.path().join("output")).unwrap();
        assert!(crate::render::apply(&store, &member.desired, workspace.path()).is_err());
        store
            .adopt_mission_revision(
                &run.id,
                intent.missions.values().next().unwrap(),
                "person/test",
                "replace broken renderer",
                "render-retire-adopt",
            )
            .unwrap();
        for _ in 0..3 {
            reconciler.reconcile_once().unwrap();
        }
        assert!(runtime.stops.lock().unwrap().contains(&runtime_id));
        assert!(workspace.path().join("output").is_dir());
        assert!(
            store
                .member_reconcile_fault(&member.subject, None)
                .unwrap()
                .is_none()
        );
    }

    #[test]
    fn a_mission_step_waits_for_native_driver_readiness_before_starting_a_gate() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let workspace = tempfile::tempdir().unwrap();
        let source = r#"
            version 2

              mission "proof" state="ready" {
                goal "Complete mission proof."
                completion { when "all-steps-exhausted" }
                step "native-ready" {
                  title "The native agent is ready"

                    agent "worker" {
                      harness "codex" {}
                    }
                    message "kick" {
                      from "requester"
                      to "worker"
                      content "Start."
                    }

                  gate "verify" {
                    exec "true"
                    host "node"
                    workspace "."
                    time-limit "1m"
                  }
                }
              }

        "#;
        apply_source(&store, source, "mission-native-ready");
        let run = store
            .create_mission_run(&crate::model::MissionRunRequest {
                mission: "proof".into(),
                revision: None,
                workspace: workspace.path().display().to_string(),
                requester: Some("person/test".into()),
                mode: Some("run".into()),
                inputs: BTreeMap::new(),
                idempotency_key: "run-native-ready".into(),
            })
            .unwrap();
        let runtime_id = format!("{}.worker", run.id);
        let agent_subject = format!("agent/{}/worker", run.id);
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        );

        for _ in 0..3 {
            reconciler.reconcile_once().unwrap();
        }
        assert_eq!(
            &*runtime.starts.lock().unwrap(),
            std::slice::from_ref(&runtime_id)
        );

        runtime.ptys.lock().unwrap().push(RuntimeObservation {
            runtime_id: runtime_id.clone(),
            terminal: true,
            status: "running".into(),
            exit_code: None,
            incarnation_id: Some("worker-one".into()),
        });
        reconciler.reconcile_once().unwrap();
        assert_eq!(
            &*runtime.starts.lock().unwrap(),
            std::slice::from_ref(&runtime_id)
        );

        store
            .append_claim(&ClaimInput {
                subject: agent_subject.clone(),
                kind: "harness.observed".into(),
                actor: Some(agent_subject.clone()),
                fields: BTreeMap::from([
                    ("state".into(), Value::String("ready".into())),
                    ("transport".into(), Value::String("app-server".into())),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some("worker-ready".into()),
            })
            .unwrap();
        reconciler.reconcile_once().unwrap();
        assert_eq!(&*runtime.starts.lock().unwrap(), &[runtime_id]);

        store
            .append_claim(&ClaimInput {
                subject: "message/kick".into(),
                kind: "message.delivered".into(),
                actor: Some(agent_subject),
                fields: BTreeMap::from([("status".into(), Value::String("delivered".into()))]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some("kick-delivered".into()),
            })
            .unwrap();
        reconciler.reconcile_once().unwrap();

        let starts = runtime.starts.lock().unwrap();
        assert_eq!(starts.len(), 2);
        assert!(starts[1].starts_with("gate-operation."));
    }

    #[test]
    fn a_mission_step_fails_when_its_non_restarting_driver_exits_before_readiness() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let workspace = tempfile::tempdir().unwrap();
        let source = r#"
            version 2

              mission "driver-start-failure" state="ready" {
                goal "Expose a driver that cannot become ready."
                completion { when "all-steps-exhausted" }
                step "start-agent" timeout="10m" {
                  title "The native agent is ready"
                  agent "worker" {
                    harness "codex" {}
                    restart "never"
                  }
                }
              }

        "#;
        apply_source(&store, source, "driver-start-failure");
        let run = store
            .create_mission_run(&crate::model::MissionRunRequest {
                mission: "driver-start-failure".into(),
                revision: None,
                workspace: workspace.path().display().to_string(),
                requester: Some("person/test".into()),
                mode: Some("run".into()),
                inputs: BTreeMap::new(),
                idempotency_key: "run-driver-start-failure".into(),
            })
            .unwrap();
        let runtime_id = format!("{}.worker", run.id);
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        );

        for _ in 0..3 {
            reconciler.reconcile_once().unwrap();
        }
        runtime.ptys.lock().unwrap().push(RuntimeObservation {
            runtime_id,
            terminal: true,
            status: "exited".into(),
            exit_code: Some(2),
            incarnation_id: Some("failed-start".into()),
        });
        reconciler.reconcile_once().unwrap();

        let run = store.mission_run(&run.id).unwrap().unwrap();
        let step = run
            .steps
            .iter()
            .find(|step| step.step == "start-agent")
            .unwrap();
        assert_eq!(step.status, "failed");
        assert!(
            step.blocked_reason
                .as_deref()
                .unwrap()
                .contains("could not become ready: runtime status was exited with exit code 2")
        );
    }

