    #[test]
    fn scheduled_work_requests_on_two_members_converge() {
        let root = tempfile::tempdir().unwrap();
        let ivory = Arc::new(Store::open_memory("ivory").unwrap());
        let revision = scheduled_mission_revision(&ivory);
        apply_source(
            &ivory,
            &format!(r#"version 2
schedule "cycle" {{
  every "7d"; anchor "2030-01-01T00:00:00Z"; catch-up "latest"
  work {{ mission "scheduled-cycle@{revision}"; workspace "{}" }}
}}"#, root.path().display()),
            "cycle",
        );
        let jade = Arc::new(Store::open_memory("jade").unwrap());
        jade.import_replication("ivory", &ivory.export_replication(0).unwrap())
            .unwrap();
        // Both members own a local declaration and admit the same tick while apart. The later
        // request selects a different child definition; losing steps must not survive convergence.
        apply_source(
            &jade,
            r#"version 2
mission "scheduled-cycle" state="ready" {
  completion { when "all-steps-exhausted" }
  goal "Complete another harvest."
  step "other" { agentless }
}"#,
            "other-cycle",
        );
        let other = jade
            .mission_spec("scheduled-cycle", None)
            .unwrap()
            .unwrap()
            .revision;
        apply_source(
            &jade,
            &format!(
                r#"version 2
schedule "cycle" {{
  every "7d"; anchor "2030-01-01T00:00:00Z"; catch-up "latest"
  work {{ mission "scheduled-cycle@{other}"; workspace "{}" }}
}}"#,
                root.path().display()
            ),
            "jade-cycle",
        );
        let mut runs = Vec::new();
        for (store, revision, host) in [(&ivory, revision, "ivory"), (&jade, other, "jade")] {
            store
                .append_claim(&ClaimInput {
                    subject: "schedule/cycle".into(),
                    kind: "schedule.work-requested".into(),
                    actor: None,
                    fields: BTreeMap::from([
                        ("revision".into(), Value::String(host.into())),
                        ("occurrence".into(), Value::from(4)),
                        (
                            "mission".into(),
                            Value::String("mission/scheduled-cycle".into()),
                        ),
                        ("mission_revision".into(), Value::String(revision)),
                        (
                            "workspace".into(),
                            Value::String(root.path().to_string_lossy().into_owned()),
                        ),
                        ("inputs".into(), serde_json::json!({})),
                    ]),
                    evidence: vec![],
                    expected_subject: None,
                    idempotency_key: None,
                })
                .unwrap();
            let reconciler = Reconciler::new(
                store.clone(),
                Arc::new(FakeRuntime::default()),
                host.into(),
                Arc::new(Notify::new()),
            );
            reconciler.reconcile_once().unwrap();
            let started = store
                .claims_for("schedule/cycle", Some("schedule.work-started"))
                .unwrap();
            assert_eq!(started.len(), 1);
            runs.push(
                started[0].body["fields"]["mission_run"]
                    .as_str()
                    .unwrap()
                    .to_owned(),
            );
        }
        assert_eq!(
            runs[0], runs[1],
            "two members created different runs for one occurrence"
        );
        for (from, to, peer) in [(&jade, &ivory, "jade"), (&ivory, &jade, "ivory")] {
            let exchange = from.export_replication_exchange("orchard-fleet", &to.replication_inventory().unwrap()).unwrap();
            to.receive_replication_exchange(peer, "orchard-fleet", &exchange).unwrap();
            let admission = to.validate_replication_backlog().unwrap();
            assert_eq!((admission.invalid, admission.unknown), (0, 0));
            to.project_replication_backlog().unwrap();
        }
        let expected = ivory.mission_run(&runs[0]).unwrap().unwrap();
        assert_eq!(expected.steps.len(), 1);
        for store in [&ivory, &jade] {
            let before = store.mission_run(&runs[0]).unwrap().unwrap();
            assert_eq!(before.initial_revision, expected.initial_revision);
            assert_eq!(before.steps.len(), 1);
            assert_eq!(before.steps[0].step, expected.steps[0].step);
            let digest = store.replication_snapshot().unwrap().graph_digest.clone();
            store.replay_replication_graph().unwrap();
            assert_eq!(
                store.replication_snapshot().unwrap().graph_digest,
                digest,
                "replay changed the graph"
            );
        }
        assert_eq!(
            ivory.replication_snapshot().unwrap().graph_digest,
            jade.replication_snapshot().unwrap().graph_digest
        );
        // An older projector could mix steps from both creation claims. Upgrade repairs that
        // tree once from its claims, preserving the same canonical result as a fresh replay.
        let copy = root.path().join("upgrade.sqlite3");
        ivory.copy_store_to(&copy).unwrap();
        let connection = rusqlite::Connection::open(&copy).unwrap();
        smallclaims::store::projection_digest::register(&connection).unwrap();
        let columns = connection.prepare("PRAGMA table_info(step_runs)").unwrap()
            .query_map([], |row| row.get::<_, String>(1)).unwrap()
            .collect::<rusqlite::Result<Vec<_>>>().unwrap();
        let select = columns.iter().map(|column| match column.as_str() {
            "subject" => "subject || '-ghost'".into(),
            "step_path" => "'ghost'".into(),
            _ => column.clone(),
        }).collect::<Vec<_>>().join(",");
        connection.execute(&format!(/* sqlite-large-value: allow-for-now lv-h9f0f077d1c78 owner=fractal_reconcile::reconcile::tests TODO=bound-or-reference-values-and-reclamation */ "INSERT INTO step_runs ({}) SELECT {select} FROM step_runs LIMIT 1", columns.join(",")), []).unwrap();
        connection.execute(/* sqlite-large-value: allow-for-now lv-h9f6457320fc1 owner=fractal_reconcile::reconcile::tests TODO=bound-or-reference-values-and-reclamation */ "DELETE FROM meta WHERE key='occurrence_creation_projection_rules'", []).unwrap();
        connection.execute_batch(/* sqlite-large-value: allow-for-now lv-hd580525eecea owner=fractal_reconcile::reconcile::tests TODO=bound-or-reference-values-and-reclamation */ "INSERT OR REPLACE INTO meta(key,value) VALUES
            ('canonical_shared_projection_rules','2'), ('work_extended_projection_rules','1');").unwrap();
        drop(connection);
        let upgraded = Store::open(&copy, "ivory").unwrap();
        assert_eq!(upgraded.mission_run(&runs[0]).unwrap().unwrap().steps.len(), 1);
        assert_eq!(upgraded.replication_snapshot().unwrap().graph_digest, ivory.replication_snapshot().unwrap().graph_digest);
    }

    #[tokio::test]
    async fn scheduled_occurrence_waits_for_history_on_a_new_member() {
        let root = tempfile::tempdir().unwrap();
        let ivory = Arc::new(Store::open_memory("ivory").unwrap());
        let revision = scheduled_mission_revision(&ivory);
        let anchor = (Utc::now() - chrono::Duration::seconds(10))
            .to_rfc3339_opts(SecondsFormat::Millis, true);
        apply_source(
            &ivory,
            &format!(
                r#"version 2
schedule "orchard" {{
  host "jade"; every "7d"; anchor "{anchor}"; catch-up "latest"
  work {{ mission "scheduled-cycle@{revision}"; workspace "{}" }}
}}"#, root.path().display()
            ),
            "orchard",
        );
        let jade = Arc::new(Store::open_memory("jade").unwrap());
        jade.import_replication("ivory", &ivory.export_replication(0).unwrap())
            .unwrap();
        ivory
            .append_claim(&ClaimInput {
                subject: "schedule/orchard".into(),
                kind: "schedule.occurrence-reached".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("revision".into(), Value::String("old-revision".into())),
                    ("occurrence".into(), Value::from(0)),
                    (
                        "scheduled_at_unix_ms".into(),
                        Value::String((now_ms() - 10_000).to_string()),
                    ),
                ]),
                evidence: vec![],
                expected_subject: None,
                idempotency_key: None,
            })
            .unwrap();
        let reconciler = Reconciler::new(
            jade.clone(),
            Arc::new(FakeRuntime::default()),
            "jade".into(),
            Arc::new(Notify::new()),
        )
        .with_schedule_peers(vec!["ivory".into()]);
        reconciler.reconcile_once().unwrap();
        tokio::time::sleep(Duration::from_millis(20)).await;
        assert!(
            jade.claims_for("schedule/orchard", Some("schedule.occurrence-scheduled"))
                .unwrap()
                .is_empty(),
            "cold member armed a tick before receiving its history"
        );
        let exchange = ivory
            .export_replication_exchange("orchard-fleet", &jade.replication_inventory().unwrap())
            .unwrap();
        jade.receive_replication_exchange("ivory", "orchard-fleet", &exchange)
            .unwrap();
        jade.validate_replication_backlog().unwrap();
        jade.project_replication_backlog().unwrap();
        reconciler.reconcile_once().unwrap();
        let armed = jade
            .claims_for("schedule/orchard", Some("schedule.occurrence-scheduled"))
            .unwrap();
        assert_eq!(
            armed.len(),
            1,
            "caught-up member did not resume its schedule"
        );
        assert_eq!(armed[0].body["fields"]["occurrence"], 1);
        tokio::time::sleep(Duration::from_millis(20)).await;
        assert_eq!(
            jade.claims_for("schedule/orchard", Some("schedule.occurrence-reached"))
                .unwrap()
                .len(),
            1
        );
    }
    #[test]
    fn daily_calendar_gap_fold_and_catch_up_keep_local_date_keys() {
        let berlin = CalendarSchedule {
            at_minute: 150,
            weekday: None,
            timezone: "Europe/Berlin".into(),
        };
        let date = |value| NaiveDate::parse_from_str(value, "%Y-%m-%d").unwrap();
        let utc = |value| {
            chrono::DateTime::parse_from_rfc3339(value)
                .unwrap()
                .timestamp_millis()
        };
        assert_eq!(
            calendar_instant(chrono_tz::Europe::Berlin, berlin.at_minute, date("2027-03-28")).unwrap(),
            utc("2027-03-28T01:00:00Z"),
            "02:30 is nonexistent: fire at the first valid instant 03:00 local"
        );
        assert_eq!(
            calendar_instant(chrono_tz::Europe::Berlin, berlin.at_minute, date("2026-10-25")).unwrap(),
            utc("2026-10-25T00:30:00Z"),
            "02:30 occurs twice: choose the earlier offset"
        );
        let morning = CalendarSchedule {
            at_minute: 480,
            weekday: None,
            timezone: "Europe/Berlin".into(),
        };
        let now = utc("2027-03-30T05:00:00Z"); // Before today's 08:00 local.
        assert_eq!(
            calendar_occurrence(&morning, Some(20270327), now, "latest", None).unwrap(),
            (20270329, utc("2027-03-29T06:00:00Z"))
        );
        assert_eq!(
            calendar_occurrence(&morning, Some(20270327), now, "skip", None).unwrap().0,
            20270330
        );
        assert!(calendar_occurrence(&morning, Some(20270327), now, "all", Some(1))
            .unwrap_err().to_string().contains("max-catch-up 1"));
        assert_eq!(
            calendar_occurrence(&morning, Some(20270327), now, "all", Some(2)).unwrap().0,
            20270328
        );
        // The second instant of the fold is after the first local 02:30,
        // but the already-reached date is never selected again.
        assert_eq!(
            calendar_occurrence(&berlin, Some(20261025), utc("2026-10-25T01:30:00Z"), "latest", None).unwrap().0,
            20261026
        );
    }
    #[test]
    fn weekly_calendar_tracks_berlin_mondays_across_dst_and_catch_up() {
        let weekly = CalendarSchedule {
            at_minute: 540, weekday: Some(1), timezone: "Europe/Berlin".into(),
        };
        let utc = |value| {
            chrono::DateTime::parse_from_rfc3339(value)
                .unwrap()
                .timestamp_millis()
        };
        assert_eq!(
            calendar_occurrence(&weekly, Some(20260323), utc("2026-03-29T12:00:00Z"), "latest", None).unwrap(),
            (20260330, utc("2026-03-30T07:00:00Z")),
            "the spring transition moves Monday 09:00 one UTC hour earlier"
        );
        let before_monday = utc("2026-10-26T07:00:00Z");
        assert_eq!(
            calendar_occurrence(&weekly, Some(20261005), before_monday, "latest", None).unwrap(),
            (20261019, utc("2026-10-19T07:00:00Z"))
        );
        assert_eq!(
            calendar_occurrence(&weekly, Some(20261005), before_monday, "skip", None).unwrap(),
            (20261026, utc("2026-10-26T08:00:00Z")),
            "the autumn transition moves Monday 09:00 one UTC hour later"
        );
        assert!(calendar_occurrence(&weekly, Some(20261005), before_monday, "all", Some(1))
            .unwrap_err().to_string().contains("max-catch-up 1"));
        assert_eq!(
            calendar_occurrence(&weekly, Some(20261005), before_monday, "all", Some(2)).unwrap().0,
            20261012
        );
        assert_eq!(
            calendar_occurrence(&weekly, None, utc("2026-10-27T12:00:00Z"), "all", Some(1)).unwrap().0,
            20261102,
            "first publication starts at the next matching weekday, not an unbounded history"
        );
        let sunday = CalendarSchedule {
            at_minute: 150, weekday: Some(7), timezone: "Europe/Berlin".into(),
        };
        assert_eq!(
            calendar_occurrence(&sunday, Some(20270321), utc("2027-03-28T01:30:00Z"), "latest", None).unwrap(),
            (20270328, utc("2027-03-28T01:00:00Z")),
            "a weekly spring gap fires at the first valid local instant"
        );
        assert_eq!(
            calendar_occurrence(&sunday, Some(20261018), utc("2026-10-25T01:30:00Z"), "latest", None).unwrap(),
            (20261025, utc("2026-10-25T00:30:00Z")),
            "a weekly autumn fold fires at its earlier instant"
        );
        assert_eq!(
            calendar_occurrence(&sunday, Some(20261025), utc("2026-10-25T01:30:00Z"), "latest", None).unwrap().0,
            20261101,
            "the repeated local clock cannot fire the same Sunday twice"
        );
    }

