    #[test]
    fn a_cancelled_runs_final_exec_started_but_not_yet_observed_keeps_its_step() {
        final_exec_during_cancellation(false);
    }

    #[test]
    fn a_cancelled_runs_final_exec_that_disappears_without_an_exit_still_ends_its_step() {
        final_exec_during_cancellation(true);
    }

    /// A final exec launched during cancellation keeps its step until its end is proven: by an
    /// observed exit, or, when its process is gone with no exit recorded (a crash or a kill), by
    /// the vanished observation the member reconciler records for it.
    fn final_exec_during_cancellation(gone_without_exit: bool) {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"version 2
mission "orchid/final-launch" state="ready" timeout="1m" {
  goal "Keep final work that has just been started."
  step "wait" { agentless }
  finally {
    step "report" {
      agentless
      exec "final-worker" { command "sleep 60"; restart "never" }
      gate "the report is posted" { field "state" "resource/orchid/report" is "ready" }
    }
  }
}
"#,
            "final-launch-mission",
        );
        let run = store
            .create_mission_run(&crate::model::MissionRunRequest {
                mission: "orchid/final-launch".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: None,
                inputs: BTreeMap::new(),
                idempotency_key: "final-launch-run".into(),
            })
            .unwrap();
        store
            .request_mission_run_cancellation(&run.id, "no longer needed")
            .unwrap();
        // Starts run on launch workers: until one has spawned the process, the exec is recorded
        // as starting and the runtime has no observation of it.
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        );
        let started = || {
            runtime.started_members.lock().unwrap().iter()
                .find(|member| member.runtime_id.ends_with("final-worker"))
                .map(|member| member.runtime_id.clone())
        };
        let report = || {
            store.mission_run(&run.id).unwrap().unwrap().steps.into_iter()
                .find(|step| step.step == "report").unwrap()
        };
        let observe = |runtime_id: &str, status: &str| {
            runtime.execs.lock().unwrap().insert(runtime_id.into(), RuntimeObservation {
                runtime_id: runtime_id.into(),
                terminal: false,
                status: status.into(),
                exit_code: (status == "exited").then_some(0),
                incarnation_id: Some("final-worker-generation".into()),
            });
        };
        let mut runtime_id = None;
        for _ in 0..8 {
            reconciler.reconcile_once().unwrap();
            if let Some(id) = started() {
                runtime_id = Some(id);
                break;
            }
        }
        let runtime_id = runtime_id.expect("cancellation runs the final exec");
        // The launch has spawned it now.
        observe(&runtime_id, "running");
        let waiting = report();
        assert_eq!(waiting.status, "working", "a starting exec is not proof of no process: {waiting:?}");
        for _ in 0..4 {
            reconciler.reconcile_once().unwrap();
        }
        assert_eq!(report().status, "working");
        assert!(!runtime.stops.lock().unwrap().contains(&runtime_id), "the final exec was stopped");
        if gone_without_exit {
            runtime.execs.lock().unwrap().remove(&runtime_id);
        } else {
            observe(&runtime_id, "exited");
        }
        // Either is proof the process ended: then the processless shortcut still cancels the step.
        for _ in 0..4 {
            reconciler.reconcile_once().unwrap();
        }
        assert_eq!(report().status, "cancelled");
    }

    #[tokio::test]
    async fn one_cancellation_wake_converges_through_runtime_cleanup() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
            version 2

              mission "cancel-convergence" state="ready" timeout="1m" {
                goal "Keep one worker ready until cancellation."
                agent "worker" { workspace "/tmp"; command "true"; restart "never" }
                step "wait" {
                  assigned-to "agent/${ST_MISSION_RUN}/worker"
                  goal "Wait for cancellation."
                }
                finally {
                  step "cleanup" { agentless }
                }
              }

        "#;
        apply_source(&store, source, "cancel-convergence-source");
        let run = store
            .create_mission_run(&crate::model::MissionRunRequest {
                mission: "cancel-convergence".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: Some("eval".into()),
                inputs: BTreeMap::new(),
                idempotency_key: "cancel-convergence-run".into(),
            })
            .unwrap();
        let notify = Arc::new(Notify::new());
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Arc::new(Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            notify.clone(),
        ));
        // This oracle checks convergence/lifecycle, at the fastest supported configured cap.
        // Default30 start spacing is independently covered by deterministic gate controls.
        reconciler.set_max_passes_per_minute(600).unwrap();
        let task = tokio::spawn(reconciler.clone().run());
        // Headroom for a loaded build host, where a debug test shares the CPU with others: well
        // under FULL_PASS_INTERVAL_MS, so a lost wake still fails instead of a full pass hiding it.
        const CONVERGES_WITHIN: Duration = Duration::from_secs(15);
        assert!(CONVERGES_WITHIN.as_millis() < crate::incremental::FULL_PASS_INTERVAL_MS);

        tokio::time::timeout(CONVERGES_WITHIN, async {
            loop {
                if runtime
                    .started_members
                    .lock()
                    .unwrap()
                    .iter()
                    .any(|member| member.runtime_id.ends_with(".worker"))
                {
                    break;
                }
                tokio::time::sleep(Duration::from_millis(1)).await;
            }
        })
        .await
        .expect("the worker did not start");

        let cancellation = format!(
            "version 2\nmission-run {:?} {{ cancellation \"operator-stop\" {{ reason \"the test ended\" }} }}\n",
            run.id
        );
        apply_source_beside_the_loop(&store, &cancellation, "cancel-convergence-stop");
        notify.notify_one();

        tokio::time::timeout(CONVERGES_WITHIN, async {
            loop {
                let current = beside_the_loop(|| store.mission_run(&run.id)).unwrap();
                let cleaned = beside_the_loop(|| store.desired_subjects())
                    .iter()
                    .all(|desired| desired.owner_run.as_deref() != Some(run.subject.as_str()));
                if current.status == "cancelled" && current.phase == "terminal" && cleaned {
                    break;
                }
                tokio::time::sleep(Duration::from_millis(1)).await;
            }
        })
        .await
        .unwrap_or_else(|error| {
            let current = beside_the_loop(|| store.mission_run(&run.id)).unwrap();
            let pending = beside_the_loop(|| store.pending_runtime_starts());
            let starts = pending
                .iter()
                .map(|operation| (
                    operation.subject.as_str(),
                    operation.finished,
                    operation.applied,
                    operation.cleanup_verified,
                    operation.revoked_by.as_deref(),
                    operation.result.as_ref().map(|result| &result["verification"]),
                ))
                .collect::<Vec<_>>();
            let drops = reconciler.runtime_observation_drops.lock().unwrap().clone();
            panic!("one cancellation wake did not finish cleanup: {error}; task_finished={}; run={}/{}; starts={starts:?}; drops={drops:?}",
                task.is_finished(), current.status, current.phase);
        });
        task.abort();

        assert!(
            beside_the_loop(|| store.desired_subjects())
                .iter()
                .all(|desired| desired.owner_run.as_deref() != Some(run.subject.as_str()))
        );
    }

    #[tokio::test]
    async fn a_declared_checkout_exists_before_its_agent_starts_and_leaves_with_its_run() {
        let root = tempfile::tempdir().unwrap();
        let repository = crate::checkout::test_support::repository(root.path());
        let workspace = root.path().join("worker");
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = format!(
            r#"
            version 2

              mission "checkout-lifecycle" state="ready" timeout="1m" {{
                goal "Work in a worktree that st creates and removes."
                agent "worker" {{
                  workspace {workspace:?}
                  checkout {repository:?} base="origin/main" branch="example/${{ST_MISSION_RUN}}" remove-at-run-end=#true
                  command "true"
                  restart "never"
                }}
                step "wait" {{
                  assigned-to "agent/${{ST_MISSION_RUN}}/worker"
                  goal "Wait for cancellation."
                }}
              }}
            "#,
            workspace = workspace.display().to_string(),
            repository = repository.display().to_string(),
        );
        apply_source(&store, &source, "checkout-lifecycle-source");
        let run = store
            .create_mission_run(&crate::model::MissionRunRequest {
                mission: "checkout-lifecycle".into(),
                revision: None,
                workspace: root.path().display().to_string(),
                requester: Some("person/test".into()),
                mode: Some("eval".into()),
                inputs: BTreeMap::new(),
                idempotency_key: "checkout-lifecycle-run".into(),
            })
            .unwrap();
        let notify = Arc::new(Notify::new());
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Arc::new(Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            notify.clone(),
        ));
        // This oracle checks convergence/lifecycle, at the fastest supported configured cap.
        // Default30 start spacing is independently covered by deterministic gate controls.
        reconciler.set_max_passes_per_minute(600).unwrap();
        let task = tokio::spawn(reconciler.run());

        tokio::time::timeout(Duration::from_secs(10), async {
            loop {
                if runtime
                    .started_members
                    .lock()
                    .unwrap()
                    .iter()
                    .any(|member| member.runtime_id.ends_with(".worker"))
                {
                    break;
                }
                tokio::time::sleep(Duration::from_millis(1)).await;
            }
        })
        .await
        .expect("the worker did not start");
        let branch = crate::test_support::git()
            .arg("-C")
            .arg(&workspace)
            .args(["branch", "--show-current"])
            .output()
            .unwrap();
        assert_eq!(
            String::from_utf8_lossy(&branch.stdout).trim(),
            format!("example/{}", run.id),
            "the worktree existed on its branch when the worker started"
        );
        assert_eq!(
            std::fs::read_to_string(workspace.join("README")).unwrap(),
            "second\n",
            "the checkout started from the fetched base"
        );

        let cancellation = format!(
            "version 2\nmission-run {:?} {{ cancellation \"operator-stop\" {{ reason \"the test ended\" }} }}\n",
            run.id
        );
        apply_source_beside_the_loop(&store, &cancellation, "checkout-lifecycle-stop");
        notify.notify_one();
        tokio::time::timeout(Duration::from_secs(10), async {
            while workspace.exists() {
                tokio::time::sleep(Duration::from_millis(1)).await;
            }
        })
        .await
        .expect("the finished run did not remove its checkout");
        task.abort();
        crate::checkout::test_support::git(
            &repository,
            &[
                "rev-parse",
                "--verify",
                "--quiet",
                &format!("refs/heads/example/{}", run.id),
            ],
        );
    }

    #[test]
    fn a_finished_checkout_stays_while_in_use_or_changed() {
        let root = tempfile::tempdir().unwrap();
        let repository = crate::checkout::test_support::repository(root.path());
        let workspace = root.path().join("shared");
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = format!(
            "version 2\nagent \"worker\" {{ workspace {:?}; checkout {:?} base=\"main\" branch=\"example/shared\" remove-at-run-end=#true; command \"true\"; restart \"never\" }}\n",
            workspace.display().to_string(),
            repository.display().to_string(),
        );
        apply_source(&store, &source, "checkout-shared");
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        );
        reconciler.reconcile_once().unwrap();
        assert!(workspace.join("README").is_file());
        assert_eq!(runtime.started_members.lock().unwrap().len(), 1);

        let agent = store
            .desired_subjects()
            .unwrap()
            .into_iter()
            .find(|subject| subject.kind == "agent")
            .unwrap();
        let checkout = Checkout::from_desired(&agent.desired).unwrap();
        let path = workspace.display().to_string();
        reconciler
            .remove_finished_checkout(
                &agent.subject,
                &checkout,
                &workspace,
                &BTreeSet::from([path.as_str()]),
            )
            .unwrap();
        assert!(
            workspace.is_dir(),
            "a current member still uses the workspace"
        );

        std::fs::write(workspace.join("notes.txt"), "unfinished\n").unwrap();
        reconciler
            .remove_finished_checkout(&agent.subject, &checkout, &workspace, &BTreeSet::new())
            .unwrap();
        assert!(workspace.join("notes.txt").is_file(), "changed work stays");
        let kept = store
            .latest_observation(&agent.subject, "harness.diagnostic")
            .unwrap()
            .unwrap();
        assert_eq!(
            kept.body.pointer("/fields/code").and_then(Value::as_str),
            Some("checkout-kept")
        );

        std::fs::remove_file(workspace.join("notes.txt")).unwrap();
        reconciler.checkout_retries.lock().unwrap().clear();
        reconciler
            .remove_finished_checkout(&agent.subject, &checkout, &workspace, &BTreeSet::new())
            .unwrap();
        assert!(!workspace.exists());
    }

    #[test]
    fn a_failed_checkout_keeps_its_agent_from_starting() {
        let root = tempfile::tempdir().unwrap();
        let repository = crate::checkout::test_support::repository(root.path());
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = format!(
            "version 2\nagent \"worker\" {{ workspace {:?}; checkout {:?} base=\"no-such-base\" branch=\"example/missing\"; command \"true\" }}\n",
            root.path().join("missing").display().to_string(),
            repository.display().to_string(),
        );
        apply_source(&store, &source, "checkout-missing-base");
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        );
        reconciler.reconcile_once().unwrap();
        reconciler.reconcile_once().unwrap();

        assert!(runtime.started_members.lock().unwrap().is_empty());
        let subject = store
            .desired_subjects()
            .unwrap()
            .into_iter()
            .find(|subject| subject.kind == "agent")
            .unwrap()
            .subject;
        let diagnostics = store
            .claims_for(&subject, Some("runtime.reconcile-decision"))
            .unwrap();
        assert_eq!(
            diagnostics.len(),
            1,
            "a retry within the backoff adds nothing"
        );
        assert_eq!(
            diagnostics[0]
                .body
                .pointer("/fields/decision")
                .and_then(Value::as_str),
            Some("member-fault")
        );
        assert!(
            diagnostics[0]
                .body
                .pointer("/fields/reason")
                .and_then(Value::as_str)
                .is_some_and(|reason| reason.contains("checkout of")),
            "{diagnostics:?}"
        );
    }

    #[test]
