        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"
version 2
mission "ready-deadline" state="ready" timeout="1ms" {
  goal "Expire while assigned work is ready."
  step "work" { assigned-to "agent/absent" }
}
"#,
            "ready-deadline-source",
        );
