    #[test]
    fn nested_loops_keep_round_results_and_feedback_separate() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"version 2
resource "left-result" { kind "custom.test.loop-result"; }
resource "right-result" { kind "custom.test.loop-result"; }
mission "collision" state="ready" {
  goal "Keep nested histories separate."
  completion { when "all-steps-exhausted"; }
  step "left" { mission "left-inner" { goal "Left."; completion { when "all-steps-exhausted"; };
    loop "repeat" { max-rounds 2; until { gate "left-ready" { field "state" "resource/left-result" is "ready"; }; }
      round { completion { when "all-steps-exhausted"; }; step "work" { agentless; goal "Left round."; }; }
    }
  }; }
  step "right" { mission "right-inner" { goal "Right."; completion { when "all-steps-exhausted"; };
    loop "repeat" { max-rounds 2; until { gate "right-ready" { field "state" "resource/right-result" is "ready"; }; }
      round { completion { when "all-steps-exhausted"; }; step "work" { agentless; goal "Right round."; }; }
    }
  }; }
}"#,
            "nested-loop-collision",
        );
        let mut request = MissionRunRequest {
            mission: "collision".into(),
            revision: None,
            workspace: ".".into(),
            requester: Some("person/test".into()),
            mode: Some("run".into()),
            inputs: BTreeMap::new(),
            idempotency_key: "nested-loop-collision-run".into(),
        };
        let run = store.create_mission_run(&request).unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        for _ in 0..24 {
            reconciler.reconcile_once().unwrap();
        }
        let generation = run.generation.strip_prefix("run-generation/").unwrap();
        let mut feedbacks = Vec::new();
        for (path, own_gate, other_gate) in [
            ("left/left-inner/repeat", "left-ready", "right-ready"),
            ("right/right-inner/repeat", "right-ready", "left-ready"),
        ] {
            let subject = format!("loop-run/{generation}/{path}");
            let results = store
                .claims_for(&subject, Some("loop.round-result"))
                .unwrap();
            let first = results
                .iter()
                .find(|claim| claim.body.pointer("/fields/round") == Some(&Value::from(1)))
                .expect("each nested loop records its own first-round result");
            let [child, second] = [1, 2].map(|round| {
                store
                    .mission_run(&store.mission_run_subject_for_idempotency_key(&format!(
                        "loop-round:step-run/{generation}/{path}:{round}"
                    )))
                    .unwrap()
                    .unwrap()
            });
            assert_eq!(
                first
                    .body
                    .pointer("/fields/mission_run")
                    .and_then(Value::as_str),
                Some(child.subject.as_str())
            );
            let feedback = &second.inputs[LOOP_FEEDBACK_INPUT].value;
            let (name, hash) = feedback.rsplit_once('@').unwrap();
            let document = store.get_document(name, hash).unwrap().unwrap();
            let body = String::from_utf8(document).unwrap();
            assert!(body.contains(own_gate), "{body}");
            assert!(!body.contains(other_gate), "{body}");
            assert_eq!(
                name,
                format!("doc/loop-feedback/{generation}/{path}/1/outcome")
            );
            feedbacks.push(feedback.clone());
        }
        assert_ne!(feedbacks[0], feedbacks[1]);
        let old_subject = format!("loop-run/{generation}/repeat");
        assert!(
            store
                .claims_for(&old_subject, Some("loop.round-result"))
                .unwrap()
                .is_empty()
        );
        let id = "x".repeat(150);
        let leaf = "y".repeat(62);
        let source = format!(
            r#"version 2
mission "long" state="ready" {{ goal "Long.";
  step "{id}" {{ mission "a" {{ goal "A.";
    step "{id}" {{ mission "b" {{ goal "B.";
      step "{leaf}" {{ mission "c" {{ goal "C.";
        loop "repeat" {{ max-rounds 1; round {{ completion {{ when "all-steps-exhausted"; }}; }}; }}
      }}; }}; }}; }}; }}; }}
}}"#
        );
        apply_source(&store, &source, "long-loop");
        request.mission = "long".into();
        request.idempotency_key = "long-loop-run".into();
        let long = store.create_mission_run(&request).unwrap();
        for _ in 0..16 {
            reconciler.reconcile_once().unwrap();
        }
        let generation = long.generation.strip_prefix("run-generation/").unwrap();
        // The unchanged legacy writer admits both the name and its boundary name@hash reference.
        let name =
            format!("doc/loop-feedback/{generation}/{id}/a/{id}/b/{leaf}/c/repeat/1/outcome");
        let hash = store.latest_document_hash(&name).unwrap().unwrap();
        assert!(format!("{name}@{hash}").len() < 512);
        let subject = format!("loop-run/{generation}/{id}/a/{id}/b/{leaf}/c/repeat");
        assert!(
            !store
                .claims_for(&subject, Some("loop.round-result"))
                .unwrap()
                .is_empty()
        );
        // Every retry fits, including the full u32 attempt width beyond max-rounds.
        let name = format!(
            "doc/loop-feedback/{generation}/{id}/a/{id}/b/{leaf}/c/repeat/{}/outcome",
            u32::MAX
        );
        let document = store
            .put_document(&name, b"{}", &None, "max-attempt-outcome")
            .unwrap();
        let reference = format!("{}@{}", document.name, document.hash);
        assert_eq!(reference.len(), 512);
        reconciler
            .record_once(
                &subject,
                "loop.state",
                BTreeMap::from([
                    ("status".into(), Value::String("failed".into())),
                    ("round".into(), Value::from(u32::MAX)),
                    ("feedback".into(), Value::String(reference)),
                ]),
            )
            .unwrap();
    }

    #[test]
    fn a_first_class_loop_runs_bounded_child_missions_until_its_gate_passes() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
version 2

resource "loop-result" { kind "custom.test.loop-result" }
mission "loop" state="ready" {
  goal "Repeat a bounded graph until its result is ready."
  input "expected" kind="text"
  completion { when "all-steps-exhausted" }
  loop "improve" {
    max-rounds 3
    until { gate "ready" { field "state" "resource/loop-result" is "${input.expected}" } }
    round {
      completion { when "all-steps-exhausted" }
      step "work" {
        agentless
        goal "Complete round ${loop.round}."
      }
    }

  }
}
"#;
        apply_source(&store, source, "first-class-loop");
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "loop".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: Some("run".into()),
                inputs: BTreeMap::from([("expected".into(), "ready".into())]),
                idempotency_key: "first-class-loop-run".into(),
            })
            .unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        for _ in 0..12 {
            reconciler.reconcile_once().unwrap();
        }
        let first = store.mission_run(&run.id).unwrap().unwrap();
        assert_eq!(first.steps[0].attempt, 2);
        assert_ne!(first.status, "completed");
        let second_round = store
            .mission_run(&store.mission_run_subject_for_idempotency_key(&format!(
                "loop-round:{}:2",
                first.steps[0].subject
            )))
            .unwrap()
            .unwrap();
        assert_eq!(second_round.inputs[LOOP_ROUND_INPUT].value, "2");

        store
            .append_claim(&ClaimInput {
                subject: "resource/loop-result".into(),
                kind: "resource.observed".into(),
                actor: None,
                fields: BTreeMap::from([
                    (
                        "kind".into(),
                        Value::String("custom.test.loop-result".into()),
                    ),
                    ("state".into(), Value::String("ready".into())),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some("loop-result-ready".into()),
            })
            .unwrap();
        for _ in 0..8 {
            reconciler.reconcile_once().unwrap();
        }
        let completed = store.mission_run(&run.id).unwrap().unwrap();
        assert_eq!(completed.status, "completed");
        assert_eq!(completed.loops.len(), 1);
        assert_eq!(completed.loops[0].status, "completed");
        assert_eq!(completed.loops[0].round, 2);
        assert_eq!(completed.loops[0].results.len(), 2);
        let reference = completed.loops[0].results[0].feedback.as_ref().unwrap();
        let (name, _) = reference.rsplit_once('@').unwrap();
        let generation = run.generation.strip_prefix("run-generation/").unwrap();
        assert_eq!(name, format!("doc/loop-feedback/{generation}/improve/1"));
    }

    #[test]
    fn an_untimed_loop_does_not_read_the_root_execution_history() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"version 2
mission "untimed-clock" state="ready" {
  goal "Wait for a round without a loop timeout."
  loop "improve" {
    max-rounds 2
    round {
      completion { when "all-steps-exhausted" }
      step "work" { assigned-to "agent/worker" }
    }
  }
}
"#;
        apply_source(&store, source, "untimed-clock-source");
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "untimed-clock".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: None,
                mode: None,
                inputs: BTreeMap::new(),
                idempotency_key: "untimed-clock-run".into(),
            })
            .unwrap();
        let mission = store
            .mission_spec("untimed-clock", Some(&run.revision))
            .unwrap()
            .unwrap();
        let steps = flatten_mission_steps(&mission);
        let step = &steps[0];
        let view = &run.steps[0];
        let loop_spec = step.spec.loop_spec.as_ref().unwrap();
        assert!(loop_spec.timeout_ms.is_none());
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        assert!(
            reconciler
                .evaluate_loop_step(&run, step, view, loop_spec)
                .unwrap()
        );
        let (changed, reads) = smallclaims::touched::record(|| {
            reconciler
                .evaluate_loop_step(&run, step, view, loop_spec)
                .unwrap()
        });
        assert!(!changed);
        assert!(
            !reads.contains(&format!("children:{}", run.root_mission_run))
                && !reads.contains(&format!("children-of-step:{}", view.subject)),
            "an untimed loop must not load the root's round history: {reads:?}"
        );
    }

    #[test]
    fn a_timed_loop_is_due_again_when_its_timeout_passes() {
        struct TestClock;
        impl Drop for TestClock {
            fn drop(&mut self) {
                smallclaims::store::set_thread_clock(None);
            }
        }
        let _clock = TestClock;
        const START: u128 = 1_800_000_000_000;
        smallclaims::store::set_thread_clock(Some(START));
        let store = Arc::new(Store::open_memory("node").unwrap());
        store.set_write_clock_at(START).unwrap();
        // The round waits on a document nobody writes, so nothing marks the run again before
        // the loop's hour is up.
        let source = r#"version 2
mission "timed-clock" state="ready" {
  goal "Stop the loop when its hour is up, though nothing else changes."
  loop "improve" timeout="1h" {
    max-rounds 2
    round {
      completion { when "all-steps-exhausted" }
      step "work" { agentless; gate "wait" { document "doc/invented-never" } }
    }
  }
}
"#;
        apply_source(&store, source, "timed-clock-source");
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "timed-clock".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: Some("run".into()),
                inputs: BTreeMap::new(),
                idempotency_key: "timed-clock-run".into(),
            })
            .unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        for _ in 0..6 {
            reconciler.reconcile_once().unwrap();
        }
        let run = store.mission_run(&run.id).unwrap().unwrap();
        let mission = store
            .mission_spec("timed-clock", Some(&run.revision))
            .unwrap()
            .unwrap();
        let steps = flatten_mission_steps(&mission);
        let (step, view) = (&steps[0], &run.steps[0]);
        let loop_spec = step.spec.loop_spec.as_ref().unwrap();
        let started = store
            .loop_first_execution_at(&run.root_mission_run, &view.subject)
            .unwrap()
            .expect("the first round has started");
        let (_, due) = smallclaims::touched::record_due(|| {
            reconciler
                .evaluate_loop_step(&run, step, view, loop_spec)
                .unwrap()
        });
        assert_eq!(due, Some(started + 3_600_000), "the loop is due when its timeout passes");
        // Once the timeout has passed the loop ends, and notes no due time in the past.
        smallclaims::store::set_thread_clock(Some(started + 3_600_000));
        store.set_write_clock_at(started + 3_600_000).unwrap();
        let (_, due) = smallclaims::touched::record_due(|| {
            reconciler
                .evaluate_loop_step(&run, step, view, loop_spec)
                .unwrap()
        });
        assert!(
            due.is_none_or(|due| due > started + 3_600_000),
            "a passed loop timeout is not a due time: {due:?}"
        );
    }

    #[test]
    fn an_unclaimed_timed_out_round_is_redispatched_without_spending_a_round() {
        struct TestClock;
        impl Drop for TestClock {
            fn drop(&mut self) {
                smallclaims::store::set_thread_clock(None);
            }
        }
        let _clock = TestClock;
        const START: u128 = 1_800_000_000_000;
        smallclaims::store::set_thread_clock(Some(START));
        let store = Arc::new(Store::open_memory("node").unwrap());
        store.set_write_clock_at(START).unwrap();
        let source = r#"
version 2

agent "worker" { workspace "/tmp"; command "true"; restart "never" }
mission "unclaimed-loop" state="ready" {
  goal "Do not call scheduling failure an execution failure."
  completion { when "all-steps-exhausted" }
  loop "improve" timeout="20ms" {
    max-rounds 2
    round {
      completion { when "all-steps-exhausted" }
      step "work" { assigned-to "agent/node.worker" }
    }
  }
}
"#;
        apply_source(&store, source, "unclaimed-loop-source");
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "unclaimed-loop".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: Some("run".into()),
                inputs: BTreeMap::new(),
                idempotency_key: "unclaimed-loop-run".into(),
            })
            .unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        for _ in 0..6 {
            reconciler.reconcile_once().unwrap();
        }
        let loop_subject = format!(
            "loop-run/{}/improve",
            run.generation.strip_prefix("run-generation/").unwrap()
        );
        assert!(
            store
                .claims_for(&loop_subject, Some("loop.round-dispatch"))
                .unwrap()
                .is_empty(),
            "fixed-clock setup must not redispatch a round"
        );
        let child_subject = store.mission_run_subject_for_idempotency_key(&format!(
            "loop-round:{}:1",
            run.steps[0].subject
        ));
        let child = store.mission_run(&child_subject).unwrap().unwrap();
        assert_eq!(
            child.parent_step_run.as_deref(),
            Some(run.steps[0].subject.as_str())
        );
        let deadline = child.deadline_at_unix_ms.expect("the round has a timeout");
        assert_eq!(deadline, child.created_at_unix_ms + 20);
        // Expire this child once, independently of setup speed or child/parent ordering.
        let expired_at = deadline + 1;
        smallclaims::store::set_thread_clock(Some(expired_at));
        store.set_write_clock_at(expired_at).unwrap();
        for _ in 0..12 {
            reconciler.reconcile_once().unwrap();
            if !store
                .claims_for(&loop_subject, Some("loop.round-dispatch"))
                .unwrap()
                .is_empty()
            {
                break;
            }
        }

        let current = store.mission_run(&run.id).unwrap().unwrap();
        assert_eq!(current.steps[0].attempt, 1);
        assert!(
            !matches!(current.status.as_str(), "failed" | "cancelled"),
            "unexpected parent state: status={} phase={} step={} reason={:?}",
            current.status,
            current.phase,
            current.steps[0].status,
            current.steps[0].blocked_reason
        );
        assert!(
            store
                .claims_for(&loop_subject, Some("loop.round-result"))
                .unwrap()
                .is_empty(),
            "a never-claimed dispatch is not a loop result"
        );
        let dispatches = store
            .claims_for(&loop_subject, Some("loop.round-dispatch"))
            .unwrap();
        assert_eq!(dispatches.len(), 1);
        assert_eq!(
            dispatches[0]
                .body
                .pointer("/fields/dispatch")
                .and_then(Value::as_u64),
            Some(1)
        );
        assert_eq!(
            dispatches[0]
                .body
                .pointer("/fields/reason")
                .and_then(Value::as_str),
            Some(
                "the round mission timeout expired before any worker claimed its work; rescheduled without consuming max-rounds"
            )
        );
    }

    #[test]
    fn loop_stop_rules_use_durable_round_results() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
version 2
mission "stops" state="ready" {
  goal "Evaluate durable loop stop rules."
  loop "improve" {
    max-rounds 5
    metric "quality" direction="higher" min-improvement=0.1 {
      field "score" "resource/result"
    }
    stop { plateau metric="quality" rounds=2; repeated-failure 2; token-budget 100 }
    round { completion { when "all-steps-exhausted" } }
  }
}
"#;
        let intent = crate::graph::parse_intent(source, "node").unwrap();
        let spec = intent.missions["stops"].steps["improve"]
            .loop_spec
            .as_ref()
            .unwrap()
            .as_ref()
            .clone();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        let subject = "loop-run/01990000000070008000000000000000/improve";
        for (round, quality) in [(1, 1.0), (2, 1.05), (3, 1.06)] {
            store
                .append_claim(&ClaimInput {
                    subject: subject.into(),
                    kind: "loop.round-result".into(),
                    actor: None,
                    fields: BTreeMap::from([
                        ("round".into(), Value::from(round)),
                        ("status".into(), Value::String("completed".into())),
                        (
                            "mission_run".into(),
                            Value::String(format!("mission-run/round-{round}")),
                        ),
                        ("metrics".into(), serde_json::json!({"quality": quality})),
                        ("token_usage".into(), Value::from(10)),
                    ]),
                    evidence: Vec::new(),
                    expected_subject: None,
                    idempotency_key: Some(format!("stop-round-{round}")),
                })
                .unwrap();
        }
        assert_eq!(
            reconciler.loop_stop_reason(subject, &spec).unwrap(),
            Some("the loop metric did not improve for 2 rounds".into())
        );

        let mut token_spec = spec.clone();
        token_spec.stop.plateau_metric = None;
        token_spec.stop.plateau_rounds = None;
        token_spec.stop.token_budget = Some(30);
        assert_eq!(
            reconciler.loop_stop_reason(subject, &token_spec).unwrap(),
            Some("the loop token budget of 30 was reached".into())
        );

        for round in 4..=5 {
            store
                .append_claim(&ClaimInput {
                    subject: subject.into(),
                    kind: "loop.round-result".into(),
                    actor: None,
                    fields: BTreeMap::from([
                        ("round".into(), Value::from(round)),
                        ("status".into(), Value::String("failed".into())),
                        (
                            "mission_run".into(),
                            Value::String(format!("mission-run/round-{round}")),
                        ),
                        ("metrics".into(), serde_json::json!({})),
                        ("token_usage".into(), Value::from(0)),
                    ]),
                    evidence: Vec::new(),
                    expected_subject: None,
                    idempotency_key: Some(format!("stop-failure-{round}")),
                })
                .unwrap();
        }
        assert_eq!(reconciler.repeated_loop_failures(subject).unwrap(), 2);
    }

    fn run_never_ready_loop(stop: &str, max_rounds: u32, key: &str) -> (Arc<Store>, MissionRunView) {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = format!(
            r#"
version 2
resource "result" {{ kind "custom.test.loop-result" }}
mission "stuck" state="ready" {{
  goal "Repeat a bounded graph whose exit gate never answers differently."
  completion {{ when "all-steps-exhausted" }}
  loop "review" {{
    max-rounds {max_rounds}
    {stop}
    until {{ gate "ready" {{ field "state" "resource/result" is "ready" }} }}
    round {{
      completion {{ when "all-steps-exhausted" }}
      step "work" {{
        agentless
        goal "Complete round ${{loop.round}}."
      }}
    }}
  }}
}}
"#
        );
        apply_source(&store, &source, key);
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "stuck".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: Some("run".into()),
                inputs: BTreeMap::new(),
                idempotency_key: format!("{key}-run"),
            })
            .unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        for _ in 0..80 {
            reconciler.reconcile_once().unwrap();
        }
        let run = store.mission_run(&run.id).unwrap().unwrap();
        (store, run)
    }

    #[test]
    fn a_loop_that_makes_no_progress_ends_with_a_verdict_naming_the_gate_not_max_rounds() {
        let (store, run) = run_never_ready_loop("stop { no-progress 3 }", 6, "no-progress-loop");
        assert_eq!(run.status, "failed");
        let view = &run.loops[0];
        assert_eq!(view.status, "failed");
        let states: Vec<String> = store
            .claims_for(&view.subject, Some("loop.state"))
            .unwrap()
            .iter()
            .map(|claim| claim.body["fields"].to_string())
            .collect();
        assert_eq!(
            view.round, 3,
            "the loop stops after three identical rounds, not at max-rounds: {:?} {states:#?}",
            view.reason
        );
        let reason = view.reason.as_deref().unwrap();
        assert!(reason.contains("made no progress"), "{reason}");
        assert!(reason.contains("3 rounds in a row"), "{reason}");
        assert!(reason.contains("failing exit gates: `ready`"), "{reason}");
        assert!(!reason.contains("max-rounds"), "{reason}");

        // The round after the first receives what the first round's exit gates said.
        let second = store
            .mission_run(&store.mission_run_subject_for_idempotency_key(&format!(
                "loop-round:{}:2",
                run.steps[0].subject
            )))
            .unwrap()
            .unwrap();
        let feedback = &second.inputs[LOOP_FEEDBACK_INPUT].value;
        let (name, hash) = loop_outcome_reference(feedback)
            .unwrap_or_else(|| panic!("round 2 received `{feedback}`"));
        assert!(name.ends_with("/1/outcome"), "{name}");
        let outcome: Value =
            serde_json::from_slice(&store.get_document(name, hash).unwrap().unwrap()).unwrap();
        assert_eq!(outcome["failing_gates"], serde_json::json!(["ready"]));
        assert_eq!(outcome["exit_gates"][0]["gate"], "ready");
        assert_eq!(outcome["decision"], "keep");
    }

    #[test]
    fn without_a_no_progress_rule_the_max_rounds_verdict_still_names_the_failing_gate() {
        let (_store, run) = run_never_ready_loop("", 3, "max-rounds-loop");
        let view = &run.loops[0];
        assert_eq!(view.status, "failed");
        assert_eq!(view.round, 3);
        let reason = view.reason.as_deref().unwrap();
        assert!(reason.contains("max-rounds"), "{reason}");
        assert!(reason.contains("failing exit gates: `ready`"), "{reason}");
    }

    #[test]
    fn a_no_progress_rule_needs_two_to_a_hundred_rounds_and_appears_once() {
        let parse = |stop: &str| {
            let source = format!(
                "version 2\nmission \"m\" state=\"ready\" {{ goal \"g\"; loop \"l\" {{ max-rounds 3; stop {{ {stop} }}; round {{ completion {{ when \"all-steps-exhausted\" }}; step \"s\" {{ agentless }} }} }} }}"
            );
            crate::graph::parse_intent(&source, "node")
        };
        assert!(parse("no-progress 2").is_ok());
        assert!(parse("no-progress 100").is_ok());
        assert!(parse("no-progress 1").is_err());
        assert!(parse("no-progress 101").is_err());
        assert!(parse("no-progress 2; no-progress 3").is_err());
    }

    #[test]
    fn rounds_with_different_gate_answers_are_progress_and_equal_ones_are_not() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let intent = crate::graph::parse_intent(
            "version 2\nmission \"m\" state=\"ready\" { goal \"g\"; loop \"l\" { max-rounds 9; stop { no-progress 3 }; round { completion { when \"all-steps-exhausted\" }; step \"s\" { agentless } } } }",
            "node",
        )
        .unwrap();
        let spec = intent.missions["m"].steps["l"]
            .loop_spec
            .as_ref()
            .unwrap()
            .as_ref()
            .clone();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        let subject = "loop-run/01990000000070008000000000000001/l";
        let written = std::cell::Cell::new(0_u32);
        let state = |round: u32, hash: &str| {
            written.set(written.get() + 1);
            store
                .append_claim(&ClaimInput {
                    subject: subject.into(),
                    kind: "loop.state".into(),
                    actor: None,
                    fields: BTreeMap::from([
                        ("status".into(), Value::String("running".into())),
                        ("round".into(), Value::from(round)),
                        (
                            "feedback".into(),
                            Value::String(format!("doc/loop-feedback/x/l/{round}/outcome@{hash}")),
                        ),
                    ]),
                    evidence: Vec::new(),
                    expected_subject: None,
                    idempotency_key: Some(format!("state-{round}-{hash}-{}", written.get())),
                })
                .unwrap();
        };
        let stop = || reconciler.loop_stop_reason(subject, &spec).unwrap();
        state(1, "aaaa");
        state(2, "aaaa");
        assert_eq!(stop(), None, "two equal rounds are fewer than three");
        state(3, "bbbb");
        assert_eq!(stop(), None, "a changed answer is progress");
        state(4, "bbbb");
        state(5, "bbbb");
        assert!(stop().unwrap().contains("no progress"));
        // A second state claim for the same round counts that round once.
        state(5, "bbbb");
        assert!(stop().unwrap().contains("3 rounds in a row"));
    }

