    #[test]
    fn a_retried_step_reopens_its_failed_run_and_the_run_completes() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
version 2

  mission "takeover" state="ready" {
    goal "Take over one service."
    agent "watcher" { workspace "/tmp"; command "true"; restart "never" }
    step "prepare" { agentless }
    step "deploy-check" { agentless; depends-on { step "prepare" completed } }
    step "announce" { agentless; depends-on { step "deploy-check" completed } }
    finally { step "report" { agentless } }
  }

"#;
        apply_source(&store, source, "publish-takeover");
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "takeover".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: None,
                inputs: BTreeMap::new(),
                idempotency_key: "run-takeover".into(),
            })
            .unwrap();
        let step = |run: &crate::model::MissionRunView, path: &str| {
            run.steps
                .iter()
                .find(|step| step.step == path)
                .unwrap()
                .clone()
        };
        store
            .set_step_state(&step(&run, "prepare").subject, "completed", None)
            .unwrap();
        store
            .set_step_state(
                &step(&run, "deploy-check").subject,
                "failed",
                Some("the deploy check failed"),
            )
            .unwrap();
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        );
        let settle = || {
            for _ in 0..20 {
                reconciler.reconcile_once().unwrap();
                if store.mission_run(&run.id).unwrap().unwrap().phase == "terminal" {
                    break;
                }
            }
            store.mission_run(&run.id).unwrap().unwrap()
        };
        let failed = settle();
        assert_eq!(failed.status, "failed");
        assert_eq!(step(&failed, "announce").status, "cancelled");
        assert_eq!(step(&failed, "report").status, "completed");
        // The watcher is the only member this mission declares.
        let watcher_starts = || runtime.started_members.lock().unwrap().len();
        assert_eq!(watcher_starts(), 1);

        let reopened = store
            .retry_failed_step(
                &step(&failed, "deploy-check").subject,
                "person/test",
                "the deploy check host is back",
                "retry-deploy-check",
            )
            .unwrap();
        assert_eq!(reopened.status, "running");

        let finished = settle();
        assert_eq!(finished.status, "completed");
        assert_eq!(finished.generation, reopened.generation);
        assert_eq!(step(&finished, "deploy-check").attempt, 2);
        assert_eq!(
            watcher_starts(),
            2,
            "the reopened run relaunches its mission agent"
        );
        assert!(
            finished.steps.iter().all(|step| step.status == "completed"),
            "{:?}",
            finished.steps
        );
    }

    #[test]
    fn one_agent_can_claim_only_one_independent_pool_step_and_a_claim_is_exclusive() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
version 2

  agent "one" { workspace "/tmp"; command "true"; restart "never" }
  mission "pool" state="ready" {
    goal "Expose two steps to one explicit pool."
    available-to "agent/node.one"
    available-to "agent/node.missing"
    step "a" { }
    step "b" { }
  }

"#;
        apply_source(&store, source, "publish-pool");
        store
            .append_claim(&ClaimInput {
                subject: "agent/node.one".into(),
                kind: "harness.observed".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("state".into(), Value::String("ready".into())),
                    (
                        "incarnation_id".into(),
                        Value::String("incarnation-one".into()),
                    ),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some("pool-agent-ready".into()),
            })
            .unwrap();
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "pool".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: None,
                inputs: BTreeMap::new(),
                idempotency_key: "run-pool".into(),
            })
            .unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        reconciler.evaluate_mission_runs().unwrap();
        let work = store.work(Some("agent/node.one"), false).unwrap();
        assert_eq!(work.len(), 2);
        let claim = |step: &crate::model::StepRunView, key: &str| {
            store.work_action(
                &step.subject,
                "claim",
                &crate::model::WorkRequest {
                    wait_ms: None,
                    actor: Some("agent/node.one".into()),
                    incarnation: Some("incarnation-one".into()),
                    summary: None,
                    reason: None,
                    evidence: Vec::new(),
                    idempotency_key: key.into(),
                },
            )
        };
        claim(&work[0], "pool-claim-a").unwrap();
        let capacity = claim(&work[1], "pool-claim-b").unwrap_err();
        assert_eq!(capacity.code, "agent-capacity");
        let run = store.mission_run(&run.id).unwrap().unwrap();
        assert_eq!(
            run.steps
                .iter()
                .filter(|step| step.claimant.as_deref() == Some("agent/node.one"))
                .count(),
            1
        );
        let error = store
            .work_action(
                &work[0].subject,
                "claim",
                &crate::model::WorkRequest {
                    wait_ms: None,
                    actor: Some("agent/node.missing".into()),
                    incarnation: Some("other".into()),
                    summary: None,
                    reason: None,
                    evidence: Vec::new(),
                    idempotency_key: "pool-lost-race".into(),
                },
            )
            .unwrap_err();
        assert!(
            matches!(
                error.code,
                "work-already-claimed"
                    | "invalid-work-transition"
                    | "work-not-eligible"
                    | "agent-not-active"
            ),
            "{}",
            error.code
        );
    }

    struct FakeResourceProvider;

    struct InvalidRepositoryProvider {
        calls: Arc<AtomicUsize>,
    }

    impl ResourceProvider for InvalidRepositoryProvider {
        fn observe(
            &self,
            _request: ObservationRequest,
        ) -> std::pin::Pin<
            Box<
                dyn std::future::Future<Output = Result<crate::resource::ProviderObservation>>
                    + Send
                    + '_,
            >,
        > {
            Box::pin(async {
                self.calls.fetch_add(1, Ordering::SeqCst);
                Ok(crate::resource::ProviderObservation {
                    facts: serde_json::json!({"issues": "not-an-array"}),
                    cursor: Some("invalid-cursor".into()),
                    next_check_unix_ms: now_ms().saturating_add(60_000),
                })
            })
        }
    }

    #[tokio::test]
    async fn a_rejected_observation_degrades_and_pauses_its_revision() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"version 2
resource "repo" { kind "vcs.repository" }
observer "repo" {
  resource "resource/repo"
  provider "github.repository"
  locator "owner/repo"
  field "issues"
}"#,
            "rejected-observation",
        );
        let calls = Arc::new(AtomicUsize::new(0));
        let (event_notify, mut event_changed) = watch::channel(0_u64);
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        )
        .with_resource_provider(Arc::new(InvalidRepositoryProvider {
            calls: calls.clone(),
        }))
        .with_event_notify(event_notify);
        reconciler.reconcile_once().unwrap();
        tokio::time::timeout(Duration::from_secs(1), event_changed.changed())
            .await
            .unwrap()
            .unwrap();
        let state = store.latest_actual_value("observer/repo").unwrap().unwrap();
        assert_eq!(state["state"], "degraded");
        assert!(state["reason"].as_str().unwrap().contains("issues"));
        assert!(
            store
                .claims_for("resource/repo", Some("resource.observed"))
                .unwrap()
                .is_empty()
        );
        reconciler.reconcile_once().unwrap();
        assert_eq!(calls.load(Ordering::SeqCst), 1);

        // A refresh request still polls the paused observer, once.
        let revision = store
            .selected_desired_revision("observer/repo")
            .unwrap()
            .unwrap();
        store
            .append_claim(&ClaimInput {
                subject: "observer/repo".into(),
                kind: "observer.refresh-requested".into(),
                actor: Some("person/test".into()),
                fields: BTreeMap::from([
                    ("revision".into(), Value::String(revision)),
                    ("attempt".into(), Value::String("refresh-1".into())),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: None,
            })
            .unwrap();
        reconciler.reconcile_once().unwrap();
        tokio::time::timeout(Duration::from_secs(1), event_changed.changed())
            .await
            .unwrap()
            .unwrap();
        assert_eq!(calls.load(Ordering::SeqCst), 2);
        assert_eq!(
            store
                .pending_observer_refresh_attempt("observer/repo")
                .unwrap(),
            None
        );
        reconciler.reconcile_once().unwrap();
        assert_eq!(calls.load(Ordering::SeqCst), 2);
    }

    struct RateLimitedResourceProvider {
        calls: Arc<AtomicUsize>,
        retry_at_unix_ms: u128,
    }

    impl ResourceProvider for RateLimitedResourceProvider {
        fn observe(
            &self,
            _request: ObservationRequest,
        ) -> std::pin::Pin<
            Box<
                dyn std::future::Future<Output = Result<crate::resource::ProviderObservation>>
                    + Send
                    + '_,
            >,
        > {
            Box::pin(async {
                self.calls.fetch_add(1, Ordering::SeqCst);
                Err(anyhow::Error::new(crate::resource::ProviderRateLimit {
                    retry_at_unix_ms: self.retry_at_unix_ms,
                    status: 429,
                }))
            })
        }
    }

    #[tokio::test]
    async fn a_rate_limited_observer_waits_until_the_provider_reset() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"version 2
resource "repo" { kind "vcs.repository" }
observer "repo" {
  resource "resource/repo"
  provider "github.repository"
  locator "example/repo"
  field "issues"
}"#,
            "rate-limited-observer",
        );
        let revision = store
            .selected_desired_revision("observer/repo")
            .unwrap()
            .unwrap();
        let deadline_key = format!("observer/repo:{revision}");
        let reset = now_ms() + 180_000;
        let calls = Arc::new(AtomicUsize::new(0));
        let (event_notify, mut event_changed) = watch::channel(0_u64);
        let reconciler = Reconciler::new(
            store,
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        )
        .with_resource_provider(Arc::new(RateLimitedResourceProvider {
            calls: calls.clone(),
            retry_at_unix_ms: reset,
        }))
        .with_event_notify(event_notify);
        reconciler.reconcile_once().unwrap();
        tokio::time::timeout(Duration::from_secs(1), event_changed.changed())
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            reconciler.observer_deadlines.lock().unwrap()[&deadline_key],
            reset
        );
        reconciler.reconcile_once().unwrap();
        tokio::time::sleep(Duration::from_millis(20)).await;
        assert_eq!(calls.load(Ordering::SeqCst), 1);
    }

    #[tokio::test]
    async fn standing_watch_cadence_preserves_rate_limit_deadlines() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            &SCRIPTED_OBSERVER.replace("observer \"repo\"", "observer \"github/example/repo\""),
            "standing-rate-limit",
        );
        let subject = "observer/github/example/repo";
        let revision = store.selected_desired_revision(subject).unwrap().unwrap();
        let key = format!("{subject}:{revision}");
        let reset = now_ms() + 900_000;
        let calls = Arc::new(AtomicUsize::new(0));
        let (events, mut changed) = watch::channel(0_u64);
        let reconciler = Reconciler::new(
            store, Arc::new(FakeRuntime::default()), "node".into(), Arc::new(Notify::new()),
        ).with_resource_provider(Arc::new(RateLimitedResourceProvider {
            calls: calls.clone(), retry_at_unix_ms: reset,
        })).with_event_notify(events);
        reconciler.reconcile_resource_observers(&reconciler.store.desired_subjects().unwrap(), &[]).unwrap();
        tokio::time::timeout(Duration::from_secs(2), changed.changed()).await.unwrap().unwrap();
        assert_eq!(
            reconciler.observer_deadlines.lock().unwrap_or_else(PoisonError::into_inner)[&key],
            reset,
        );
        assert!(reconciler.observer_intervals.lock().unwrap_or_else(PoisonError::into_inner).is_empty());
        reconciler.reconcile_resource_observers(&reconciler.store.desired_subjects().unwrap(), &[]).unwrap();
        assert_eq!(calls.load(Ordering::SeqCst), 1);
    }

    #[tokio::test]
    async fn an_observer_unreachable_for_an_hour_requests_attention_once() {
        let root = tempfile::tempdir().unwrap();
        let database = root.path().join("observer.sqlite");
        let store = Arc::new(Store::open(&database, "node").unwrap());
        apply_source(
            &store,
            r#"version 2
resource "repo" { kind "vcs.repository" }
observer "repo" {
  resource "resource/repo"
  provider "github.repository"
  locator "example/repo"
  field "issues"
}"#,
            "prolonged-unreachable-observer",
        );
        let revision = store
            .selected_desired_revision("observer/repo")
            .unwrap()
            .unwrap();
        let old = store
            .append_claim(&ClaimInput {
                subject: "observer/repo".into(),
                kind: "observer.state".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("state".into(), Value::String("unreachable".into())),
                    ("reason".into(), Value::String("old failure".into())),
                    ("revision".into(), Value::String(revision)),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: None,
            })
            .unwrap();
        let connection = rusqlite::Connection::open(&database).unwrap();
        crate::store::configure_projection_writer(&connection).unwrap();
        connection
            .execute(
                /* sqlite-large-value: allow-for-now lv-h5a3e28993af6 owner=fractal_reconcile::reconcile::tests TODO=prepare-body-and-predecessor-values */ "UPDATE claims SET accepted_at_unix_ms=?1 WHERE id=?2",
                rusqlite::params![(now_ms() - 3_600_001).to_string(), old.id],
            )
            .unwrap();
        let calls = Arc::new(AtomicUsize::new(0));
        let (event_notify, mut event_changed) = watch::channel(0_u64);
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        )
        .with_resource_provider(Arc::new(ScriptedResourceProvider::new(
            calls,
            [ScriptedObservation::Fail, ScriptedObservation::Fail],
        )))
        .with_event_notify(event_notify);
        reconciler.reconcile_once().unwrap();
        tokio::time::timeout(Duration::from_secs(1), event_changed.changed())
            .await
            .unwrap()
            .unwrap();
        let attention = store.fault_items(None).unwrap();
        assert_eq!(
            attention
                .iter()
                .filter(|item| item.title == "An observer has failed for an hour")
                .count(),
            1
        );
        assert_eq!(
            attention
                .iter()
                .find(|item| item.title == "An observer has failed for an hour")
                .unwrap()
                .person,
            "person/operator"
        );
        reconciler.reconcile_once().unwrap();
        assert_eq!(
            store
                .fault_items(None)
                .unwrap()
                .iter()
                .filter(|item| item.title == "An observer has failed for an hour")
                .count(),
            1
        );
    }

    /// Answers every observation with one open pull request on `branch`.
    struct OnePullRequestProvider {
        branch: String,
    }

    impl ResourceProvider for OnePullRequestProvider {
        fn observe(
            &self,
            _request: ObservationRequest,
        ) -> std::pin::Pin<
            Box<
                dyn std::future::Future<Output = Result<crate::resource::ProviderObservation>>
                    + Send
                    + '_,
            >,
        > {
            Box::pin(async {
                Ok(crate::resource::ProviderObservation {
                    facts: serde_json::json!({"repository_id": 7, "pull_requests": [{
                        "number": 7, "head": "a".repeat(40), "branch": self.branch,
                        "state": "open", "draft": false, "title": "Feature",
                    }]}),
                    cursor: Some("one".into()),
                    next_check_unix_ms: now_ms().saturating_add(60_000),
                })
            })
        }
    }

    /// A reconcile pass hands the repository observer every agent declaration, so the agent
    /// whose workspace has a new pull request's branch checked out is named its opener. The
    /// intake stage once passed only observers, subscriptions, and schedules, and no pull request
    /// was ever named.
    #[tokio::test]
    async fn a_reconcile_pass_names_the_agent_with_a_new_pull_requests_branch() {
        use crate::checkout::test_support::{git, repository};
        let root = tempfile::tempdir().unwrap();
        let clone = repository(root.path());
        git(&clone, &["checkout", "--quiet", "-b", "agent/feature"]);
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            &format!(
                r#"version 2
resource "repo" {{ kind "vcs.repository" }}
agent "builder" {{ workspace {:?}; command "true" }}
observer "repo" {{ resource "resource/repo"; provider "github.repository"; locator "acme/garden"; field "pull_requests" }}"#,
                clone.display().to_string()
            ),
            "watch",
        );
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        )
        .with_resource_provider(Arc::new(OnePullRequestProvider {
            branch: "agent/feature".into(),
        }));
        reconciler.reconcile_once().unwrap();
        let facts = tokio::time::timeout(Duration::from_secs(5), async {
            loop {
                if let Some(actual) = store
                    .latest_actual_value("resource/repo/pull-request/7")
                    .unwrap()
                {
                    break actual["facts"].clone();
                }
                tokio::time::sleep(Duration::from_millis(20)).await;
            }
        })
        .await
        .expect("the observation recorded the pull request");
        assert_eq!(facts["opened_by"], "agent/node.builder");
    }

    /// What a scripted observation answers.
    enum ScriptedObservation {
        Observe,
        /// An observation that asks to continue at once, as a listing longer than one read does.
        Continue,
        RateLimitAt(u128),
        LocalBudget(u128),
        Forbidden,
        Fail,
    }

    /// Answers each observation with the next scripted outcome.
    struct ScriptedResourceProvider {
        calls: Arc<AtomicUsize>,
        outcomes: Mutex<std::collections::VecDeque<ScriptedObservation>>,
    }

    impl ScriptedResourceProvider {
        fn new(
            calls: Arc<AtomicUsize>,
            outcomes: impl IntoIterator<Item = ScriptedObservation>,
        ) -> Self {
            Self {
                calls,
                outcomes: Mutex::new(outcomes.into_iter().collect()),
            }
        }
    }

    impl ResourceProvider for ScriptedResourceProvider {
        fn observe(
            &self,
            _request: ObservationRequest,
        ) -> std::pin::Pin<
            Box<
                dyn std::future::Future<Output = Result<crate::resource::ProviderObservation>>
                    + Send
                    + '_,
            >,
        > {
            Box::pin(async {
                let outcome = self
                    .outcomes
                    .lock()
                    .unwrap()
                    .pop_front()
                    .expect("an observation was scripted");
                self.calls.fetch_add(1, Ordering::SeqCst);
                match outcome {
                    ScriptedObservation::Observe => Ok(crate::resource::ProviderObservation {
                        facts: serde_json::json!({"issues": []}),
                        cursor: Some("no-issues".into()),
                        next_check_unix_ms: now_ms().saturating_add(60_000),
                    }),
                    ScriptedObservation::Continue => Ok(crate::resource::ProviderObservation {
                        facts: serde_json::json!({"issues": []}),
                        cursor: Some("more-issues".into()),
                        next_check_unix_ms: now_ms()
                            .saturating_add(crate::resource::PROVIDER_CONTINUE_MS),
                    }),
                    ScriptedObservation::RateLimitAt(deadline) => {
                        Err(anyhow::Error::new(crate::resource::ProviderRateLimit {
                            retry_at_unix_ms: deadline,
                            status: 403,
                        }))
                    }
                    ScriptedObservation::LocalBudget(deadline) => {
                        Err(anyhow::Error::new(crate::resource::LocalObserverBudget {
                            retry_at_unix_ms: deadline,
                        }))
                    }
                    ScriptedObservation::Forbidden => {
                        Err(anyhow::Error::new(crate::resource::ProviderForbidden {
                            status: 403,
                            message: "Resource not accessible by personal access token".into(),
                        }))
                    }
                    ScriptedObservation::Fail => Err(anyhow::anyhow!("connection reset by peer")),
                }
            })
        }
    }

    const SCRIPTED_OBSERVER: &str = r#"version 2
resource "repo" { kind "vcs.repository" }
observer "repo" {
  resource "resource/repo"
  provider "github.repository"
  locator "example/repo"
  field "issues"
}"#;

    #[tokio::test]
    async fn standing_watch_cadence_adapts_without_migrating_declarations() {
        struct AdaptiveProvider {
            calls: Arc<AtomicUsize>,
            changed: Arc<AtomicUsize>,
            continuation: Arc<AtomicBool>,
            covered: Arc<AtomicBool>,
        }
        impl ResourceProvider for AdaptiveProvider {
            fn observe(&self, request: ObservationRequest) -> std::pin::Pin<Box<
                dyn Future<Output = Result<crate::resource::ProviderObservation>> + Send + '_
            >> {
                // Scheduling must keep passing the opaque provider cursor through.
                if request.previous_facts.is_some() {
                    assert_eq!(request.cursor.as_deref(), Some("etag-and-pagination-state"));
                }
                self.calls.fetch_add(1, Ordering::SeqCst);
                self.covered.store(request.webhook_covered, Ordering::SeqCst);
                let change = self.changed.load(Ordering::SeqCst);
                let continuing = self.continuation.load(Ordering::SeqCst);
                let mut facts = serde_json::json!({"repository_id": 7});
                if change != 2 {
                    facts["issues"] = serde_json::json!([{
                        "node_id": "I_fixture", "number": 1, "state": "open",
                        "url": "https://github.com/example/repo/issues/1",
                        "title": if change == 0 { "before" } else { "after" },
                    }]);
                }
                Box::pin(async move { Ok(crate::resource::ProviderObservation {
                    facts,
                    cursor: Some("etag-and-pagination-state".into()),
                    next_check_unix_ms: now_ms() + if continuing {
                        crate::resource::PROVIDER_CONTINUE_MS
                    } else {
                        300_000
                    },
                }) })
            }
        }

        async fn poll(
            reconciler: &Reconciler<FakeRuntime>,
            calls: &AtomicUsize,
            subject: &str,
            force: bool,
            interval: u128,
        ) {
            let revision = reconciler.store.selected_desired_revision(subject).unwrap().unwrap();
            let key = format!("{subject}:{revision}");
            if force {
                reconciler.armed_observers.lock().unwrap()
                    .retain(|operation| !operation.starts_with(&format!("{subject}:")));
                reconciler.observer_deadlines.lock().unwrap().insert(key.clone(), 0);
            }
            let old = reconciler.observer_deadlines.lock().unwrap().get(&key).copied();
            let expected = calls.load(Ordering::SeqCst) + 1;
            let before = now_ms();
            // This scheduler fixture has no live subscription; the full pass would
            // correctly stop an unwatched standing observer before it can poll.
            reconciler.reconcile_resource_observers(&reconciler.store.desired_subjects().unwrap(), &[]).unwrap();
            tokio::time::timeout(Duration::from_secs(2), async {
                loop {
                    let deadline = reconciler.observer_deadlines.lock().unwrap().get(&key).copied();
                    if calls.load(Ordering::SeqCst) == expected
                        && let Some(deadline) = deadline.filter(|deadline| Some(*deadline) != old) {
                        let actual = reconciler.store.latest_actual_value(subject).unwrap().unwrap();
                        assert_eq!(actual["state"], "healthy", "{subject} poll {expected}: {actual}");
                        assert!(deadline >= before + interval,
                            "{subject} poll {expected}: next delay {}ms, expected at least {interval}ms", deadline.saturating_sub(before));
                        assert!(deadline <= now_ms() + interval,
                            "{subject} poll {expected}: next delay {}ms, expected at most {interval}ms", deadline.saturating_sub(now_ms()));
                        break;
                    }
                    tokio::task::yield_now().await;
                }
            }).await.expect("scheduled observation completes");
        }

        for subject in ["github/example/repo", "custom"] {
            let standing = subject.starts_with("github/");
            let subject_id = format!("observer/{subject}");
            let source = format!(r#"version 2
resource "github/example/repo" {{ kind "vcs.repository" }}
observer "{subject}" {{
  resource "resource/github/example/repo"
  provider "github.repository"
  locator "example/repo"
  field "issues"
  every "30s"
}}"#);
            let store = Arc::new(Store::open_memory("node").unwrap());
            apply_source(&store, &source, "adaptive-watch");
            let calls = Arc::new(AtomicUsize::new(0));
            let changed = Arc::new(AtomicUsize::new(0));
            let continuation = Arc::new(AtomicBool::new(false));
            let covered = Arc::new(AtomicBool::new(false));
            let reconciler = Reconciler::new(
                store.clone(), Arc::new(FakeRuntime::default()), "node".into(), Arc::new(Notify::new()),
            ).with_resource_provider(Arc::new(AdaptiveProvider {
                calls: calls.clone(), changed: changed.clone(), continuation: continuation.clone(), covered: covered.clone(),
            }));
            // Legacy standing every=30s adapts, while an explicitly faster custom observer
            // stays at 30s through every quiet/change boundary.
            for interval in [180_000, 360_000, 600_000, 600_000] {
                poll(&reconciler, &calls, &subject_id, true,
                    if standing { interval } else { 30_000 }).await;
            }
            changed.store(1, Ordering::SeqCst);
            poll(&reconciler, &calls, &subject_id, true,
                if standing { 180_000 } else { 30_000 }).await;
            // Real repository observations are item deltas. An identity-only quiet poll
            // after a changed item, and re-emitting the identical item, are both quiet.
            changed.store(2, Ordering::SeqCst);
            poll(&reconciler, &calls, &subject_id, true,
                if standing { 360_000 } else { 30_000 }).await;
            changed.store(3, Ordering::SeqCst);
            poll(&reconciler, &calls, &subject_id, true,
                if standing { 600_000 } else { 30_000 }).await;
            continuation.store(true, Ordering::SeqCst);
            poll(&reconciler, &calls, &subject_id, true,
                crate::resource::PROVIDER_CONTINUE_MS).await;
            continuation.store(false, Ordering::SeqCst);
            poll(&reconciler, &calls, &subject_id, true,
                if standing { 600_000 } else { 30_000 }).await;

            let revision = store.selected_desired_revision(&subject_id).unwrap().unwrap();
            store.append_claim(&ClaimInput {
                subject: subject_id.clone(),
                kind: "observer.refresh-requested".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("revision".into(), Value::String(revision)),
                    ("attempt".into(), Value::String("adaptive-refresh".into())),
                ]),
                evidence: Vec::new(), expected_subject: None, idempotency_key: None,
            }).unwrap();
            // No forced deadline: refresh must interrupt the existing sleeping arm.
            poll(&reconciler, &calls, &subject_id, false,
                if standing { 180_000 } else { 30_000 }).await;
            assert!(store.pending_observer_refresh_attempt(&subject_id).unwrap().is_none());

            // A new revision starts immediately at active cadence, not the old deadline.
            apply_source(&store, &source.replace("30s", "31s"), "adaptive-watch-revision");
            poll(&reconciler, &calls, &subject_id, false,
                if standing { 180_000 } else { 31_000 }).await;
            assert!(!covered.load(Ordering::SeqCst), "a declared refresh is not webhook coverage");

            // A webhook-requested refresh, from whichever member received the delivery, covers
            // the repository: quiet polls take the ceiling at once and changes stay active.
            let revision = store.selected_desired_revision(&subject_id).unwrap().unwrap();
            store.append_claim(&ClaimInput {
                subject: subject_id.clone(),
                kind: "observer.refresh-requested".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("revision".into(), Value::String(revision)),
                    ("attempt".into(), Value::String(crate::github_webhook::attempt("delivery", &subject_id))),
                ]),
                evidence: Vec::new(), expected_subject: None, idempotency_key: None,
            }).unwrap();
            poll(&reconciler, &calls, &subject_id, false,
                if standing { 600_000 } else { 31_000 }).await;
            assert!(covered.load(Ordering::SeqCst));
            changed.store(0, Ordering::SeqCst);
            poll(&reconciler, &calls, &subject_id, true,
                if standing { 180_000 } else { 31_000 }).await;
            // The same facts again are quiet: straight to the ceiling, not through 360s.
            poll(&reconciler, &calls, &subject_id, true,
                if standing { 600_000 } else { 31_000 }).await;
        }
    }

    /// Run one observation now and wait until it has recorded its outcome. An unchanged or
    /// backing-off poll keeps its arm sleeping toward its own deadline, so retire that arm, as
    /// a refresh would, and wait for the completion to publish its next deadline instead.
    async fn observe_now(reconciler: &Reconciler<FakeRuntime>, calls: &AtomicUsize) {
        let revision = reconciler
            .store
            .selected_desired_revision("observer/repo")
            .unwrap()
            .unwrap();
        let key = format!("observer/repo:{revision}");
        let expected = calls.load(Ordering::SeqCst) + 1;
        // Persisted refusal deadlines deliberately override an in-memory deadline. Use the
        // public refresh contract to force the next scripted refusal without sleeping.
        if reconciler.store.latest_actual_value("observer/repo").unwrap().is_some_and(|actual|
            matches!(actual["error_code"].as_str(), Some("rate-limited" | "local-observer-budget")))
        {
            reconciler.store.append_claim(&ClaimInput {
                subject: "observer/repo".into(),
                kind: "observer.refresh-requested".into(),
                actor: Some("person/test".into()),
                fields: BTreeMap::from([
                    ("revision".into(), Value::String(revision)),
                    ("attempt".into(), Value::String(format!("scripted-{expected}"))),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: None,
            }).unwrap();
        }
        reconciler
            .armed_observers
            .lock()
            .unwrap()
            .retain(|operation| !operation.starts_with("observer/repo:"));
        reconciler.observer_deadlines.lock().unwrap().insert(key.clone(), 0);
        reconciler.reconcile_once().unwrap();
        tokio::time::timeout(Duration::from_secs(2), async {
            while calls.load(Ordering::SeqCst) < expected
                || reconciler.observer_deadlines.lock().unwrap().get(&key).is_none_or(|deadline| *deadline == 0)
            {
                tokio::time::sleep(Duration::from_millis(5)).await;
            }
        })
        .await
        .expect("the observation finished");
    }

    #[tokio::test]
    async fn local_budget_health_uses_every_complete_poll_not_changed_receipts() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(&store, SCRIPTED_OBSERVER, "budget-freshness");
        let calls = Arc::new(AtomicUsize::new(0));
        let retry = now_ms() + 180_000;
        let reconciler = Reconciler::new(
            store.clone(), Arc::new(FakeRuntime::default()), "node".into(), Arc::new(Notify::new()),
        ).with_resource_provider(Arc::new(ScriptedResourceProvider::new(calls.clone(), [
            ScriptedObservation::Observe,
            ScriptedObservation::Observe,
            ScriptedObservation::LocalBudget(retry),
            ScriptedObservation::LocalBudget(retry),
            ScriptedObservation::Observe,
            ScriptedObservation::LocalBudget(retry),
        ])));
        observe_now(&reconciler, &calls).await;
        let receipts = store.claims_for("observer/repo", Some("observer.state")).unwrap().len();
        let age_clock = || {
            let mut clock = reconciler.github_plugin.observer_freshness("observer/repo", now_ms()).unwrap();
            reconciler.github_plugin.complete_observation(
                "observer/repo", &mut clock, now_ms() - 31 * 60_000,
            ).unwrap();
        };
        age_clock();
        // Identical facts and cursor suppress receipts but must reset local freshness.
        observe_now(&reconciler, &calls).await;
        assert_eq!(store.claims_for("observer/repo", Some("observer.state")).unwrap().len(), receipts);
        observe_now(&reconciler, &calls).await;
        assert_eq!(store.latest_actual_value("observer/repo").unwrap().unwrap()["state"], "healthy");
        age_clock();
        // A new arm reads the durable clock, just as a restarted reconciler does.
        observe_now(&reconciler, &calls).await;
        let actual = store.latest_actual_value("observer/repo").unwrap().unwrap();
        assert_eq!(actual["state"], "degraded");
        assert_eq!(actual["error_code"], "local-observer-budget");
        assert_eq!(actual["next_check_unix_ms"], retry.to_string());
        assert!(actual["reason"].as_str().unwrap().contains("local observer budget reached"));
        assert!(observer_items(&store).is_empty(), "local budget does not require a person");
        observe_now(&reconciler, &calls).await;
        observe_now(&reconciler, &calls).await;
        assert_eq!(store.latest_actual_value("observer/repo").unwrap().unwrap()["state"], "healthy");
    }

    #[tokio::test]
    async fn failed_freshness_write_degrades_with_backoff_instead_of_repolling() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(&store, SCRIPTED_OBSERVER, "failed-freshness");
        let calls = Arc::new(AtomicUsize::new(0));
        let reconciler = Reconciler::new(
            store.clone(), Arc::new(FakeRuntime::default()), "node".into(), Arc::new(Notify::new()),
        ).with_resource_provider(Arc::new(ScriptedResourceProvider::new(
            calls.clone(), [ScriptedObservation::Observe],
        )));
        reconciler.github_plugin.fail_freshness_writes();
        let before = now_ms();
        observe_now(&reconciler, &calls).await;
        let actual = store.latest_actual_value("observer/repo").unwrap().unwrap();
        assert_eq!(actual["state"], "degraded");
        assert_eq!(actual["error_code"], "github-plugin-database");
        assert!(actual["reason"].as_str().unwrap().contains("freshness write failed"));
        let revision = store.selected_desired_revision("observer/repo").unwrap().unwrap();
        let key = format!("observer/repo:{revision}");
        assert!(reconciler.observer_deadlines.lock().unwrap()[&key] >= before + 60_000);
        reconciler.reconcile_once().unwrap();
        tokio::task::yield_now().await;
        assert_eq!(calls.load(Ordering::SeqCst), 1);
    }

    #[tokio::test]
    async fn main_performance_failures_subscription_extends_the_existing_observer_request() {
        struct Capture {
            calls: Arc<AtomicUsize>,
            fields: Arc<Mutex<Vec<BTreeSet<String>>>>,
        }
        impl ResourceProvider for Capture {
            fn observe(&self, request: ObservationRequest) -> std::pin::Pin<Box<
                dyn std::future::Future<Output = Result<crate::resource::ProviderObservation>> + Send + '_
            >> {
                self.fields.lock().unwrap().push(request.fields);
                self.calls.fetch_add(1, Ordering::SeqCst);
                Box::pin(async { Ok(crate::resource::ProviderObservation {
                    facts: serde_json::json!({"repository_id": 7, "issues": [], "main_performance_failures": []}),
                    cursor: Some("workflow-baseline".into()),
                    next_check_unix_ms: now_ms().saturating_add(60_000),
                }) })
            }
        }
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(&store, &format!(r#"{SCRIPTED_OBSERVER}
agent "target" {{ workspace "."; command "true" }}
subscription "performance" {{ observer "observer/repo"; to "agent/node.target"; on "main_performance_failures"; delivery "message" }}
"#), "subscribe-workflow");
        let calls = Arc::new(AtomicUsize::new(0));
        let fields = Arc::new(Mutex::new(Vec::new()));
        let reconciler = Reconciler::new(store.clone(), Arc::new(FakeRuntime::default()),
            "node".into(), Arc::new(Notify::new()))
            .with_resource_provider(Arc::new(Capture { calls: calls.clone(), fields: fields.clone() }));
        observe_now(&reconciler, &calls).await;
        assert!(fields.lock().unwrap().iter().any(|fields|
            fields.contains("issues") && fields.contains("main_performance_failures")));
        let observers = store.desired_subjects().unwrap().into_iter()
            .filter(|item| item.kind == "observer").collect::<Vec<_>>();
        assert_eq!(observers.len(), 1);
        assert_eq!(crate::graph::observer_spec(&observers[0].desired).unwrap().fields, ["issues"]);
        assert!(store.messages(None, true).unwrap().is_empty());
    }

    #[tokio::test]
    async fn a_repository_observer_records_each_completed_ci_run_once_in_the_graph() {
        const RUN: &str = "github-workflow-run/example/repo/9001";
        struct Recorder {
            calls: Arc<AtomicUsize>,
            written: Arc<Mutex<Vec<bool>>>,
        }
        impl ResourceProvider for Recorder {
            fn observe(&self, request: ObservationRequest) -> std::pin::Pin<Box<
                dyn Future<Output = Result<crate::resource::ProviderObservation>> + Send + '_
            >> {
                let ledger = request.workflow_runs.expect("a repository observer is given the graph's ledger");
                let fields = BTreeMap::from([
                    ("version".to_owned(), serde_json::json!(1)), ("repository".to_owned(), serde_json::json!("example/repo")),
                    ("workflow".to_owned(), serde_json::json!("Workspace CI")), ("run_id".to_owned(), serde_json::json!(9001)),
                    ("attempt".to_owned(), serde_json::json!(1)), ("event".to_owned(), serde_json::json!("merge_group")),
                    ("conclusion".to_owned(), serde_json::json!("failure")), ("head_sha".to_owned(), serde_json::json!("a".repeat(40))),
                    ("created_at".to_owned(), serde_json::json!("2026-11-13T10:00:00Z")),
                    ("started_at".to_owned(), serde_json::json!("2026-11-13T10:00:30Z")),
                    ("completed_at".to_owned(), serde_json::json!("2026-11-13T10:09:30Z")),
                    ("duration_ms".to_owned(), serde_json::json!(540_000)), ("flaky_tests".to_owned(), serde_json::json!(0)),
                    ("flakes".to_owned(), serde_json::json!(1)),
                ]);
                let mut written = self.written.lock().unwrap();
                written.push(ledger.written(RUN).unwrap());
                ledger.write(RUN, &fields).unwrap();
                written.push(ledger.written(RUN).unwrap());
                ledger.write(RUN, &fields).unwrap();
                drop(written);
                self.calls.fetch_add(1, Ordering::SeqCst);
                Box::pin(async { Ok(crate::resource::ProviderObservation {
                    facts: serde_json::json!({"repository_id": 7, "issues": []}),
                    cursor: Some("runs".into()),
                    next_check_unix_ms: now_ms().saturating_add(60_000),
                }) })
            }
        }
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(&store, SCRIPTED_OBSERVER, "record-runs");
        let calls = Arc::new(AtomicUsize::new(0));
        let written = Arc::new(Mutex::new(Vec::new()));
        let reconciler = Reconciler::new(store.clone(), Arc::new(FakeRuntime::default()),
            "node".into(), Arc::new(Notify::new()))
            .with_resource_provider(Arc::new(Recorder { calls: calls.clone(), written: written.clone() }));
        observe_now(&reconciler, &calls).await;
        assert_eq!(*written.lock().unwrap(), [false, true], "a written run reads as written");
        let claims = store.claims_for(RUN, None).unwrap();
        assert_eq!(claims.len(), 1, "an identical second write is the same claim");
        assert_eq!(claims[0].kind, fractal_schema::github_plugin::WORKFLOW_RUN);
        assert_eq!(claims[0].body["fields"]["observer"], "observer/repo");
        assert_eq!(claims[0].body["fields"]["flakes"], 1);
    }

    fn failure_for_item(
        store: &Store,
        item: &crate::model::AttentionItemView,
    ) -> Result<Option<crate::model::AttentionRequestView>> {
        let claim = store.claim_by_id(&item.episode)?.unwrap();
        store.operational_failure(claim.body["fields"]["episode"].as_str().unwrap())
    }

    fn observer_items(store: &Store) -> Vec<crate::model::AttentionItemView> {
        store
            .fault_items(None)
            .unwrap()
            .into_iter()
            .filter(|item| item.targets == ["observer/repo"])
            .collect()
    }

    /// An observer's declared interval replaces the provider's next check, except when the
    /// provider asks to continue at once, such as a listing longer than one read.
    #[tokio::test]
    async fn a_declared_interval_does_not_delay_a_provider_that_continues_at_once() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            &SCRIPTED_OBSERVER.replace("field \"issues\"", "field \"issues\"\n  every \"1h\""),
            "continue-at-once",
        );
        let calls = Arc::new(AtomicUsize::new(0));
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        )
        .with_resource_provider(Arc::new(ScriptedResourceProvider::new(
            calls.clone(),
            [ScriptedObservation::Continue, ScriptedObservation::Observe],
        )));
        let revision = store
            .selected_desired_revision("observer/repo")
            .unwrap()
            .unwrap();
        let deadline = || {
            *reconciler
                .observer_deadlines
                .lock()
                .unwrap()
                .get(&format!("observer/repo:{revision}"))
                .unwrap()
        };
        observe_now(&reconciler, &calls).await;
        assert!(
            deadline() <= now_ms() + crate::resource::PROVIDER_CONTINUE_MS,
            "a continuation keeps its own deadline"
        );
        observe_now(&reconciler, &calls).await;
        assert!(
            deadline() >= now_ms() + 50 * 60_000,
            "otherwise the declared hour applies"
        );
    }

    #[tokio::test]
    async fn a_rate_limit_persists_each_new_deadline_and_clears_stale_attention() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(&store, SCRIPTED_OBSERVER, "outlasted-rate-limit");
        let calls = Arc::new(AtomicUsize::new(0));
        let reset = now_ms() + 180_000;
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        )
        .with_resource_provider(Arc::new(ScriptedResourceProvider::new(
            calls.clone(),
            [
                ScriptedObservation::RateLimitAt(reset),
                ScriptedObservation::RateLimitAt(reset + 180_000),
                ScriptedObservation::RateLimitAt(reset + 360_000),
                ScriptedObservation::Observe,
            ],
        )));

        // A rate limit resets on its own, so it raises nothing.
        observe_now(&reconciler, &calls).await;
        let state = store.latest_actual_value("observer/repo").unwrap().unwrap();
        assert_eq!(state["error_code"], "rate-limited");
        assert!(observer_items(&store).is_empty());

        // Until another refusal is observed, a missed reset can ask for attention.
        let revision = store
            .selected_desired_revision("observer/repo")
            .unwrap()
            .unwrap();
        store
            .append_claim(&ClaimInput {
                subject: "observer/repo".into(),
                kind: "observer.state".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("state".into(), Value::String("unreachable".into())),
                    (
                        "reason".into(),
                        Value::String("GitHub HTTP 403 rate limit".into()),
                    ),
                    ("error_code".into(), Value::String("rate-limited".into())),
                    ("revision".into(), Value::String(revision)),
                    (
                        "next_check_unix_ms".into(),
                        Value::String((now_ms() - crate::resource::RATE_LIMIT_RESET_GRACE_MS - 1).to_string()),
                    ),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: None,
            })
            .unwrap();
        let items = observer_items(&store);
        assert_eq!(items.len(), 1);
        assert_eq!(items[0].title, "A GitHub rate limit outlasted its reset");
        assert!(
            items[0]
                .detail
                .contains(&format!("`st doctor` on {}", store.origin())),
            "{}",
            items[0].detail
        );
        observe_now(&reconciler, &calls).await;
        let state = store.latest_actual_value("observer/repo").unwrap().unwrap();
        assert_eq!(state["next_check_unix_ms"], (reset + 180_000).to_string());
        assert!(observer_items(&store).is_empty(), "the new refusal supersedes the old reset");
        observe_now(&reconciler, &calls).await;
        let state = store.latest_actual_value("observer/repo").unwrap().unwrap();
        assert_eq!(state["next_check_unix_ms"], (reset + 360_000).to_string());
        assert!(observer_items(&store).is_empty());

        // Observing again closes it.
        observe_now(&reconciler, &calls).await;
        assert!(observer_items(&store).is_empty());
        assert_eq!(
            store
                .latest_claim("observer/repo", Some("observer.state"))
                .unwrap()
                .unwrap()
                .body["fields"]["state"],
            "healthy"
        );
    }

    #[tokio::test]
    async fn a_local_observer_refusal_persists_its_slot_without_provider_attention() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(&store, SCRIPTED_OBSERVER, "local-budget");
        let calls = Arc::new(AtomicUsize::new(0));
        let slot = now_ms() + 180_000;
        let reconciler = Reconciler::new(
            store.clone(), Arc::new(FakeRuntime::default()), "node".into(), Arc::new(Notify::new()),
        ).with_resource_provider(Arc::new(ScriptedResourceProvider::new(
            calls.clone(), [ScriptedObservation::LocalBudget(slot)],
        )));
        observe_now(&reconciler, &calls).await;
        let state = store.latest_actual_value("observer/repo").unwrap().unwrap();
        assert_eq!(state["error_code"], "local-observer-budget");
        assert_eq!(state["state"], "healthy", "compatible non-fault deferred receipt");
        assert_eq!(state["next_check_unix_ms"], slot.to_string());
        assert_eq!(state["reason"], format!("local observer budget reached, next slot at {slot} (Unix ms)"));
        assert!(observer_items(&store).is_empty());
        reconciler.reconcile_once().unwrap();
        assert_eq!(calls.load(Ordering::SeqCst), 1);
    }

    #[tokio::test]
    async fn a_permission_refusal_asks_a_person_at_once_and_again_after_it_recovers() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(&store, SCRIPTED_OBSERVER, "forbidden-observer");
        let calls = Arc::new(AtomicUsize::new(0));
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        )
        .with_resource_provider(Arc::new(ScriptedResourceProvider::new(
            calls.clone(),
            [
                ScriptedObservation::Forbidden,
                ScriptedObservation::Forbidden,
                ScriptedObservation::Observe,
                ScriptedObservation::Forbidden,
            ],
        )));

        observe_now(&reconciler, &calls).await;
        observe_now(&reconciler, &calls).await;
        let first = observer_items(&store);
        assert_eq!(first.len(), 1, "one item for the whole failure");
        assert_eq!(first[0].title, "An observer has no access to GitHub");
        assert_eq!(first[0].person, "person/operator");
        assert!(first[0].detail.contains("gh auth"), "{}", first[0].detail);

        observe_now(&reconciler, &calls).await;
        assert!(observer_items(&store).is_empty());
        assert_eq!(
            store
                .latest_claim("observer/repo", Some("observer.state"))
                .unwrap()
                .unwrap()
                .body["fields"]["state"],
            "healthy"
        );

        // A later failure is a new episode, and raises a new item.
        observe_now(&reconciler, &calls).await;
        let second = observer_items(&store);
        assert_eq!(second.len(), 1);
        assert_eq!(second[0].subject, first[0].subject);
        assert_ne!(second[0].episode, first[0].episode);
    }

    #[test]
    fn a_lasting_fault_raises_one_item_per_cause_and_closes_when_it_reconciles() {
        let root = tempfile::tempdir().unwrap();
        let database = root.path().join("faults.sqlite");
        let store = Arc::new(Store::open(&database, "node").unwrap());
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        let fail = |reason: &'static str| {
            reconciler.isolate("stage/example", "daemon/node", || -> Result<()> {
                anyhow::bail!(reason)
            });
        };
        let age_open_fault = || {
            let fault = store
                .open_reconcile_fault_claim("daemon/node", "stage/example")
                .unwrap()
                .unwrap();
            let connection = rusqlite::Connection::open(&database).unwrap();
            crate::store::configure_projection_writer(&connection).unwrap();
            connection
                .execute(
                    /* sqlite-large-value: allow-for-now lv-h9657cbe4f49a owner=fractal_reconcile::reconcile::tests TODO=prepare-body-and-predecessor-values */ "UPDATE claims SET accepted_at_unix_ms=?1 WHERE id=?2",
                    rusqlite::params![
                        (now_ms() - FAULT_ATTENTION_AFTER_MS - 1).to_string(),
                        fault.id
                    ],
                )
                .unwrap();
        };
        let items = || {
            store
                .fault_items(None)
                .unwrap()
                .into_iter()
                .filter(|item| item.targets == ["daemon/node"])
                .collect::<Vec<_>>()
        };

        // st retries a fault on every pass, so a fresh one asks no one.
        fail("the disk is full");
        fail("the disk is full");
        assert!(items().is_empty());

        age_open_fault();
        fail("the disk is full");
        fail("the disk is full");
        let first = items();
        assert_eq!(first.len(), 1);
        assert_eq!(first[0].title, "st cannot reconcile daemon/node");
        assert!(first[0].detail.contains("the disk is full"));
        assert!(first[0].detail.contains("`st subject show daemon/node`"));

        // A new cause replaces the item.
        fail("the database is locked");
        assert!(items().is_empty());
        age_open_fault();
        fail("the database is locked");
        let second = items();
        assert_eq!(second.len(), 1);
        assert!(second[0].detail.contains("the database is locked"));

        // Reconciling closes it.
        reconciler.isolate("stage/example", "daemon/node", || -> Result<()> { Ok(()) });
        assert!(items().is_empty());
        assert_eq!(
            store
                .latest_claim(&second[0].subject, Some("reconcile.fault"))
                .unwrap()
                .unwrap()
                .body["fields"]["status"],
            "recovered"
        );
    }

    #[test]
    fn low_disk_space_raises_one_host_item_until_the_space_recovers() {
        const GIB: u64 = 1 << 30;
        let store = Arc::new(Store::open_memory("node").unwrap());
        let available = Arc::new(Mutex::new(GIB));
        let reading = available.clone();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        )
        .with_disk_probe(
            vec![PathBuf::from("/state"), PathBuf::from("/missing")],
            Arc::new(move |path: &Path| {
                if path != Path::new("/state") {
                    return Err(std::io::ErrorKind::NotFound.into());
                }
                Ok(crate::disk::DiskSpace {
                    filesystem: 7,
                    available: *reading.lock().unwrap(),
                    total: 100 * GIB,
                })
            }),
        );
        let set = |bytes: u64| *available.lock().unwrap() = bytes;
        let items = || {
            store
                .fault_items(Some("person/operator"))
                .unwrap()
                .into_iter()
                .filter(|item| item.title == "Disk space is low on node")
                .collect::<Vec<_>>()
        };

        for _ in 0..3 {
            reconciler.reconcile_once().unwrap();
        }
        let first = items();
        assert_eq!(first.len(), 1);
        assert_eq!(first[0].targets, vec!["daemon/node".to_owned()]);
        for expected in [
            "On node, `/state` has 1.0 GiB of 100.0 GiB free (1.0%).",
            "`cargo clean`",
            "`st doctor`",
            "closes once each filesystem has 4 GiB and 4% free",
        ] {
            assert!(first[0].detail.contains(expected), "{}", first[0].detail);
        }

        // Between low and recovered the item stays open.
        set(3 * GIB);
        reconciler.reconcile_once().unwrap();
        assert_eq!(items().len(), 1);

        set(10 * GIB);
        reconciler.reconcile_once().unwrap();
        assert!(items().is_empty());
        let closed = failure_for_item(&store, &first[0]).unwrap().unwrap();
        assert_eq!(closed.status, "resolved");

        // A new episode raises a new item. A person who closes it early is not asked again
        // while the space stays low.
        set(GIB);
        reconciler.reconcile_once().unwrap();
        let second = items();
        assert_eq!(second.len(), 1);
        assert_eq!(second[0].subject, first[0].subject);
        assert_ne!(second[0].episode, first[0].episode);
        for _ in 0..3 {
            reconciler.reconcile_once().unwrap();
        }
        assert_eq!(items().len(), 1, "the source is still low");
    }

    #[test]
    fn a_failing_reconciler_raises_one_host_item_until_a_pass_succeeds() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        reconciler
            .request_reconciler_attention("A reconcile pass failed: the store is locked")
            .unwrap();
        reconciler
            .request_reconciler_attention(
                "The reconciler panicked and restarts: index out of bounds",
            )
            .unwrap();
        let items = store.fault_items(None).unwrap();
        assert_eq!(items.len(), 1);
        assert_eq!(items[0].title, "The reconciler is failing");
        assert_eq!(items[0].targets, ["daemon/node"]);
        assert!(items[0].detail.contains("the store is locked"));

        reconciler.resolve_reconciler_attention().unwrap();
        assert!(store.fault_items(None).unwrap().is_empty());
    }

    struct SharedDiscoveryProvider {
        calls: Arc<AtomicUsize>,
    }

    impl ResourceProvider for SharedDiscoveryProvider {
        fn observe(
            &self,
            _request: ObservationRequest,
        ) -> std::pin::Pin<
            Box<
                dyn std::future::Future<Output = Result<crate::resource::ProviderObservation>>
                    + Send
                    + '_,
            >,
        > {
            Box::pin(async {
                self.calls.fetch_add(1, Ordering::SeqCst);
                Ok(crate::resource::ProviderObservation {
                    facts: serde_json::json!({"issues": [{"number": 7}]}),
                    cursor: Some("issue-seven".into()),
                    next_check_unix_ms: now_ms().saturating_add(60_000),
                })
            })
        }
    }

    #[tokio::test]
    async fn observers_on_one_resource_deliver_to_both_subscriptions() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"version 2
mission "review" state="ready" {
  input "source" kind="resource"
  goal "Review a discovered issue."
  step "review" { agentless }
}"#,
            "shared-discovery-mission",
        );
        let revision = store
            .mission_spec("review", None)
            .unwrap()
            .unwrap()
            .revision;
        let source = format!(
            r#"version 2
resource "repo" {{ kind "vcs.repository" }}
observer "a" {{ resource "resource/repo"; provider "github.repository"; locator "example/repo"; field "issues" }}
observer "b" {{ resource "resource/repo"; provider "github.repository"; locator "example/repo"; field "issues" }}
subscription "a" {{
  observer "observer/a"
  on "issues"
  delivery "mission" {{ mission "review@{revision}"; resource "source"; workspace "/tmp/st3-review" }}
}}
subscription "b" {{
  observer "observer/b"
  on "issues"
  delivery "mission" {{ mission "review@{revision}"; resource "source"; workspace "/tmp/st3-review" }}
}}"#
        );
        apply_source(&store, &source, "shared-discovery-watch");
        store.record_resource_observation("observer/a", &store
            .selected_desired_revision("observer/a")
            .unwrap()
            .unwrap(), None, "resource/repo", Some("baseline"), &serde_json::json!({"issues": []}), now_ms() + 60_000, &[], None)
            .unwrap();
        let calls = Arc::new(AtomicUsize::new(0));
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        )
        .with_resource_provider(Arc::new(SharedDiscoveryProvider {
            calls: calls.clone(),
        }));
        reconciler
            .reconcile_resource_observers(
                &store.desired_subjects().unwrap(),
                &store.desired_subjects().unwrap(),
            )
            .unwrap();
        for _ in 0..100 {
            if calls.load(Ordering::SeqCst) == 2
                && reconciler.armed_observers.lock().unwrap().is_empty()
            {
                break;
            }
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
        assert_eq!(calls.load(Ordering::SeqCst), 2);
        for subscription in ["subscription/a", "subscription/b"] {
            assert_eq!(
                store
                    .claims_for(subscription, Some("subscription.mission-requested"))
                    .unwrap()
                    .len(),
                1,
                "{subscription} did not receive issue 7"
            );
        }
    }

    struct BlockingResourceProvider {
        calls: Arc<AtomicUsize>,
        release: Arc<Notify>,
    }

    impl ResourceProvider for BlockingResourceProvider {
        fn observe(
            &self,
            _request: ObservationRequest,
        ) -> std::pin::Pin<
            Box<
                dyn std::future::Future<Output = Result<crate::resource::ProviderObservation>>
                    + Send
                    + '_,
            >,
        > {
            Box::pin(async {
                self.calls.fetch_add(1, Ordering::SeqCst);
                self.release.notified().await;
                Ok(crate::resource::ProviderObservation {
                    facts: serde_json::json!({"state": "open"}),
                    cursor: Some("one".into()),
                    next_check_unix_ms: now_ms().saturating_add(60_000),
                })
            })
        }
    }

    #[tokio::test]
    async fn an_observer_has_only_one_provider_call_in_flight() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
version 2

resource "one" { kind "custom.example.state" }
observer "one" {
  resource "resource/one"
  provider "example.state"
  locator "one"
  field "state"
}
"#;
        apply_source(&store, source, "publish-one-observer");
        let calls = Arc::new(AtomicUsize::new(0));
        let release = Arc::new(Notify::new());
        let reconciler = Reconciler::new(
            store,
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        )
        .with_resource_provider(Arc::new(BlockingResourceProvider {
            calls: calls.clone(),
            release: release.clone(),
        }));

        reconciler.reconcile_once().unwrap();
        for _ in 0..100 {
            if calls.load(Ordering::SeqCst) == 1 {
                break;
            }
            tokio::time::sleep(Duration::from_millis(1)).await;
        }
        assert_eq!(calls.load(Ordering::SeqCst), 1);
        reconciler.reconcile_once().unwrap();
        tokio::time::sleep(Duration::from_millis(10)).await;
        assert_eq!(calls.load(Ordering::SeqCst), 1);
        release.notify_waiters();
    }

    #[test]
    fn an_invalid_subscription_request_is_recorded_and_does_not_block_reconciliation() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"version 2
mission "review" state="ready" {
  input "source" kind="resource"
  completion { when "all-steps-exhausted" }
  goal "Review a discovered item."
  step "review" { agentless }
}"#,
            "subscription-request-mission",
        );
        let revision = store
            .mission_spec("review", None)
            .unwrap()
            .unwrap()
            .revision;
        apply_source(
            &store,
            &format!(
                r#"version 2
resource "repo" {{ kind "vcs.repository" }}
observer "repo" {{
  resource "resource/repo"
  provider "github.repository"
  locator "example/repo"
  field "issues"
}}
subscription "reviews" {{
  observer "observer/repo"
  on "issues"
  delivery "mission" {{
    mission "review@{revision}"
    resource "source"
    workspace "/tmp/st3-review"
  }}
}}"#
            ),
            "subscription-request-failure",
        );
        let discovery = store
            .append_claim(&ClaimInput {
                subject: "resource/repo".into(),
                kind: "resource.observed".into(),
                actor: None,
                fields: BTreeMap::from([("kind".into(), Value::String("vcs.repository".into()))]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: None,
            })
            .unwrap();
        let bad = store
            .append_claim(&ClaimInput {
                subject: "subscription/reviews".into(),
                kind: "subscription.mission-requested".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("mission".into(), Value::String("mission/review".into())),
                    ("mission_revision".into(), Value::String(revision.clone())),
                    ("resource".into(), Value::String("resource/repo".into())),
                    ("resource_input".into(), Value::String("item".into())),
                    ("workspace".into(), Value::String("/tmp/st3-review".into())),
                    ("discovery".into(), Value::String(discovery.id.clone())),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: None,
            })
            .unwrap();
        let good = store
            .append_claim(&ClaimInput {
                subject: "subscription/reviews".into(),
                kind: "subscription.mission-requested".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("mission".into(), Value::String("mission/review".into())),
                    ("mission_revision".into(), Value::String(revision)),
                    ("resource".into(), Value::String("resource/repo".into())),
                    ("resource_input".into(), Value::String("source".into())),
                    ("workspace".into(), Value::String("/tmp/st3-review".into())),
                    ("discovery".into(), Value::String(discovery.id)),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: None,
            })
            .unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        let desired = store.desired_subjects().unwrap();
        reconciler
            .reconcile_subscription_missions(&desired)
            .unwrap();
        reconciler
            .reconcile_subscription_missions(&desired)
            .unwrap();
        let failures = store
            .claims_for("subscription/reviews", Some("subscription.mission-failed"))
            .unwrap();
        assert_eq!(failures.len(), 1);
        assert_eq!(failures[0].body["fields"]["request"], bad.id);
        assert_eq!(failures[0].body["fields"]["code"], "invalid-mission-inputs");
        let starts = store
            .claims_for("subscription/reviews", Some("subscription.mission-started"))
            .unwrap();
        assert_eq!(starts.len(), 1);
        assert_eq!(starts[0].body["fields"]["request"], good.id);
        assert!(
            store
                .fault_items(None)
                .unwrap()
                .iter()
                .any(|item| { item.kind == "fault" && item.targets == ["subscription/reviews"] })
        );
        let failure_attention = store
            .fault_items(None)
            .unwrap()
            .into_iter()
            .find(|item| item.kind == "fault" && item.targets == ["subscription/reviews"])
            .unwrap();
        assert_eq!(failure_attention.subject, "subscription/reviews");
        apply_source(
            &store,
            r#"version 2
subscription "reviews" { stop }"#,
            "stop-failed-subscription",
        );
        assert!(
            store
                .fault_items(None)
                .unwrap()
                .iter()
                .all(|item| item.subject != failure_attention.subject)
        );
    }

    #[test]
    fn a_person_closes_an_agent_requested_subscription_failure_and_a_stop_ends_the_rest() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"version 2
mission "review" state="ready" {
  input "source" kind="resource"
  completion { when "all-steps-exhausted" }
  goal "Review a discovered item."
  step "review" { agentless }
}"#,
            "agent-failure-mission",
        );
        let revision = store
            .mission_spec("review", None)
            .unwrap()
            .unwrap()
            .revision;
        apply_source(
            &store,
            &format!(
                r#"version 2
resource "repo" {{ kind "vcs.repository" }}
observer "repo" {{
  resource "resource/repo"
  provider "github.repository"
  locator "example/repo"
  field "issues"
}}
subscription "reviews" {{
  observer "observer/repo"
  on "issues"
  delivery "mission" {{
    mission "review@{revision}"
    resource "source"
    workspace "/tmp/st3-review"
    requester "agent/example/steward"
  }}
}}"#
            ),
            "agent-failure-subscription",
        );
        let discovery = store
            .append_claim(&ClaimInput {
                subject: "resource/repo".into(),
                kind: "resource.observed".into(),
                actor: None,
                fields: BTreeMap::from([("kind".into(), Value::String("vcs.repository".into()))]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: None,
            })
            .unwrap();
        for input in ["first", "second"] {
            store
                .append_claim(&ClaimInput {
                    subject: "subscription/reviews".into(),
                    kind: "subscription.mission-requested".into(),
                    actor: None,
                    fields: BTreeMap::from([
                        ("mission".into(), Value::String("mission/review".into())),
                        ("mission_revision".into(), Value::String(revision.clone())),
                        ("resource".into(), Value::String("resource/repo".into())),
                        ("resource_input".into(), Value::String(input.into())),
                        ("workspace".into(), Value::String("/tmp/st3-review".into())),
                        ("discovery".into(), Value::String(discovery.id.clone())),
                        (
                            "requester".into(),
                            Value::String("agent/example/steward".into()),
                        ),
                    ]),
                    evidence: Vec::new(),
                    expected_subject: None,
                    idempotency_key: None,
                })
                .unwrap();
        }
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        reconciler
            .reconcile_subscription_missions(&store.desired_subjects().unwrap())
            .unwrap();
        let failures = || {
            store
                .fault_items(None)
                .unwrap()
                .into_iter()
                .filter(|item| item.subject == "subscription/reviews")
                .collect::<Vec<_>>()
        };
        let open = failures();
        assert_eq!(open.len(), 2);
        assert!(open.iter().all(|item| item.person == "person/operator"));

        // A stopped subscription starts nothing more, so its failures end on their own.
        apply_source(
            &store,
            "version 2\nsubscription \"reviews\" { stop }\n",
            "agent-failure-subscription-stop",
        );
        assert!(failures().is_empty());
    }

