    #[test]
    fn a_changed_subscription_starts_one_exact_resource_input_mission() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"version 2
mission "review" state="ready" {
  concurrent-runs max=1
  input "source" kind="resource"
  completion { when "all-steps-exhausted" }
  goal "Review one discovered item."
  step "review" { agentless }
}"#,
            "review-mission",
        );
        let revision = store
            .mission_spec("review", None)
            .unwrap()
            .unwrap()
            .revision;
        let source = format!(
            r#"version 2
resource "repo" {{ kind "vcs.repository" }}
observer "repo" {{ resource "resource/repo"; provider "github.repository"; locator "owner/repo"; field "pull_requests" }}
subscription "reviews" {{
  observer "observer/repo"
  on "pull_requests"
  delivery "mission" {{
    mission "review@{revision}"
    resource "source"
    workspace "/tmp/st3-review"
    requester "agent/example/repository/standing/owner"
  }}
}}"#
        );
        apply_source(&store, &source, "repository-watch");
        let desired = store.desired_subjects().unwrap();
        let subscription = desired
            .iter()
            .find(|item| item.kind == "subscription")
            .unwrap();
        let spec = crate::graph::subscription_spec(&subscription.desired).unwrap();
        let subscriptions = vec![(subscription.subject.clone(), spec)];
        let baseline = store.record_resource_observation("observer/repo", &store
            .selected_desired_revision("observer/repo")
            .unwrap()
            .unwrap(), None, "resource/repo", Some("one"), &serde_json::json!({"pull_requests": []}), now_ms() + 60_000, &subscriptions, None)
            .unwrap();
        let baseline_claim = baseline
            .observation_claim
            .expect("the baseline creates a resource claim");
        let occupied = store
            .create_mission_run(&MissionRunRequest {
                mission: "review".into(),
                revision: Some(revision.clone()),
                workspace: "/tmp/st3-review/occupied".into(),
                requester: None,
                mode: None,
                inputs: BTreeMap::from([(
                    "source".into(),
                    format!("resource/repo@{baseline_claim}"),
                )]),
                idempotency_key: "occupied-review".into(),
            })
            .unwrap();
        let changed = store.record_resource_observation("observer/repo", &store
            .selected_desired_revision("observer/repo")
            .unwrap()
            .unwrap(), None, "resource/repo", Some("two"), &serde_json::json!({"pull_requests": [{"number": 7, "head": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}]}), now_ms() + 60_000, &subscriptions, None)
            .unwrap();
        // The repository's own facts did not change; only the new item records a claim.
        assert!(changed.observation_claim.is_none());
        assert_eq!(changed.changed_fields, vec!["pull_requests".to_owned()]);
        let item_claim = store
            .claims_for("resource/repo/pull-request/7", Some("resource.observed"))
            .unwrap()
            .pop()
            .expect("the repository discovery creates one pull request resource")
            .id;
        let request = store
            .pending_subscription_mission_requests("subscription/reviews")
            .unwrap()
            .pop()
            .unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        let before_deferral = store.index().unwrap();
        reconciler
            .reconcile_subscription_missions(&desired)
            .unwrap();
        assert!(
            store
                .claims_for("subscription/reviews", Some("subscription.mission-started"))
                .unwrap()
                .is_empty(),
            "capacity must leave the event pending"
        );
        assert_eq!(store.index().unwrap(), before_deferral);
        let (deadline, attempts) = store
            .subscription_mission_deferral("subscription/reviews", &request.id)
            .unwrap()
            .unwrap();
        assert_eq!(attempts, 1);
        assert!(deadline > now_ms());
        let subscription_key = "subscription:subscription/reviews";
        assert!(!reconciler.incremental.needs(subscription_key, deadline - 1));
        assert!(
            reconciler.incremental.needs(subscription_key, deadline),
            "a capacity retry must run when its deadline arrives"
        );
        reconciler
            .reconcile_subscription_missions(&desired)
            .unwrap();
        assert_eq!(
            store
                .subscription_mission_deferral("subscription/reviews", &request.id)
                .unwrap()
                .unwrap(),
            (deadline, 1)
        );
        assert!(
            reconciler.incremental.needs(subscription_key, deadline),
            "reading an existing deferral must keep its retry deadline"
        );
        for _ in 0..5 {
            reconciler.evaluate_mission_runs().unwrap();
        }
        assert_eq!(
            store.mission_run(&occupied.id).unwrap().unwrap().status,
            "completed"
        );
        std::thread::sleep(Duration::from_millis(1_100));
        reconciler
            .reconcile_subscription_missions(&desired)
            .unwrap();
        let runs = store.active_mission_runs_for_mission("review").unwrap();
        assert_eq!(runs.len(), 1);
        assert_eq!(runs[0].revision, revision);
        assert_eq!(runs[0].requester, "agent/example/repository/standing/owner");
        assert_eq!(
            runs[0].inputs["source"].subject.as_deref(),
            Some("resource/repo/pull-request/7")
        );
        assert_eq!(runs[0].inputs["source"].claim_id, Some(item_claim));
        reconciler
            .reconcile_subscription_missions(&desired)
            .unwrap();
        assert_eq!(
            store
                .active_mission_runs_for_mission("review")
                .unwrap()
                .len(),
            1
        );
    }

    const REDELIVERY_REVIEW_SOURCE: &str = r#"version 2
mission "review" state="ready" {
  concurrent-runs max=10
  input "source" kind="resource"
  goal "Review one discovered item."
  step "review" { agentless }
}"#;

    /// The host that starts a requested mission reads the request's discovery when the request
    /// arrives, so an observation seals a request in the batch that holds its discovery, and the
    /// two reach every member in one envelope.
    #[test]
    fn a_mission_request_travels_in_the_batch_of_its_discovery() {
        let store = Store::open_memory("node").unwrap();
        apply_source(&store, REDELIVERY_REVIEW_SOURCE, "review-mission");
        let revision = store.mission_spec("review", None).unwrap().unwrap().revision;
        let source = format!(
            r#"version 2
resource "repo" {{ kind "vcs.repository" }}
observer "repo" {{ resource "resource/repo"; provider "github.repository"; locator "example/repo"; field "pull_requests" }}
subscription "reviews" {{
  observer "observer/repo"
  on "pull_requests"
  delivery "mission" {{ mission "review@{revision}"; resource "source"; workspace "/srv/reviews" }}
}}"#
        );
        apply_source(&store, &source, "watch");
        let observer_revision = store.selected_desired_revision("observer/repo").unwrap().unwrap();
        let subscriptions = store
            .desired_subjects()
            .unwrap()
            .into_iter()
            .filter(|item| item.subject == "subscription/reviews")
            .map(|item| (item.subject, crate::graph::subscription_spec(&item.desired).unwrap()))
            .collect::<Vec<_>>();
        for pulls in [serde_json::json!([]), serde_json::json!([{"number": 4, "head": "a".repeat(40), "state": "open", "draft": false}])] {
            store
                .record_resource_observation("observer/repo", &observer_revision, None, "resource/repo", None,
                    &serde_json::json!({"repository_id": 17, "pull_requests": pulls}), now_ms() + 60_000, &subscriptions, None)
                .unwrap();
        }
        let request = store
            .claims_for("subscription/reviews", Some("subscription.mission-requested"))
            .unwrap()
            .remove(0);
        let discovery = request.body["fields"]["discovery"].as_str().unwrap();
        let discovered = store.claim_by_id(discovery).unwrap().unwrap();
        assert_eq!(discovered.kind, "resource.observed");
        assert_eq!(request.batch_id, discovered.batch_id);
    }

    #[test]
    fn replacement_intake_does_not_request_an_already_delivered_head() {
        let store = Store::open_memory("node").unwrap();
        apply_source(&store, REDELIVERY_REVIEW_SOURCE, "review-mission");
        let revision = store
            .mission_spec("review", None)
            .unwrap()
            .unwrap()
            .revision;
        let watch = |name: &str| {
            let source = format!(
                r#"version 2
resource "repo" {{ kind "vcs.repository" }}
observer "repo" {{ resource "resource/repo"; provider "github.repository"; locator "example/repo"; field "pull_requests" }}
subscription "reviews" {{
  observer "observer/repo"
  on "pull_requests"
  delivery "mission" {{ mission "review@{revision}"; resource "source"; workspace "/srv/reviews" }}
}}"#
            );
            apply_source(&store, &source, &format!("watch-{name}"));
            let desired = store.desired_subjects().unwrap();
            let observer_revision = store
                .selected_desired_revision("observer/repo")
                .unwrap()
                .unwrap();
            let subscription = desired
                .iter()
                .find(|item| item.subject == "subscription/reviews")
                .unwrap();
            (
                observer_revision,
                vec![(
                    subscription.subject.clone(),
                    crate::graph::subscription_spec(&subscription.desired).unwrap(),
                )],
            )
        };
        let (observer_revision, subscriptions) = watch("old");
        let observe = |observer_revision: &str,
                       subscriptions: &Vec<(String, crate::model::SubscriptionSpec)>,
                       head: Option<&str>,
                       state: &str| {
            let pulls = head.map(|head| serde_json::json!([{"number": 4, "head": head, "state": state, "draft": false}])).unwrap_or_else(|| serde_json::json!([]));
            store.record_resource_observation("observer/repo", observer_revision, None, "resource/repo", None, &serde_json::json!({"repository_id": 17, "pull_requests": pulls}), now_ms() + 60_000, subscriptions, None)
                .unwrap();
        };
        let a = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
        let b = "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
        observe(&observer_revision, &subscriptions, None, "open");
        observe(&observer_revision, &subscriptions, Some(a), "open");
        assert_eq!(
            store
                .claims_for(
                    "subscription/reviews",
                    Some("subscription.mission-requested")
                )
                .unwrap()
                .len(),
            1
        );

        let (observer_revision, subscriptions) = watch("new");
        observe(&observer_revision, &subscriptions, Some(a), "closed");
        assert!(
            store
                .claims_for(
                    "subscription/reviews",
                    Some("subscription.mission-requested")
                )
                .unwrap()
                .len()
                == 1
        );
        observe(&observer_revision, &subscriptions, Some(b), "open");
        assert_eq!(
            store
                .claims_for(
                    "subscription/reviews",
                    Some("subscription.mission-requested")
                )
                .unwrap()
                .len(),
            2
        );
        observe(&observer_revision, &subscriptions, Some(b), "closed");
        assert_eq!(
            store
                .claims_for(
                    "subscription/reviews",
                    Some("subscription.mission-requested")
                )
                .unwrap()
                .len(),
            2
        );
    }

    /// The pty-rust intake of 2026-09-29: a replacement intake run observed a listing whose
    /// items gained a per-item state that the older build had not recorded. Items merged weeks
    /// earlier read as changed, and their heads were reviewed and routed to a person.
    #[test]
    fn a_replacement_intake_over_older_history_reviews_only_new_open_heads() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(&store, REDELIVERY_REVIEW_SOURCE, "review");
        let publish_watch = |run: &str| {
            apply_source(
                &store,
                &format!(
                    r#"version 2
resource "repo" {{ kind "vcs.repository" }}
observer "repo" {{ resource "resource/repo"; provider "github.repository"; locator "example/repo"; field "pull_requests" }}
subscription "run/{run}/reviews" {{
  observer "observer/repo"; on "pull_requests"
  delivery "mission" {{ mission "review"; resource "source"; workspace "/srv/reviews" }}
}}"#
                ),
                &format!("watch-{run}"),
            );
            let subject = format!("subscription/run/{run}/reviews");
            let desired = store.desired_subjects().unwrap();
            let spec = desired.iter().find(|item| item.subject == subject).unwrap();
            let revision = store
                .selected_desired_revision("observer/repo")
                .unwrap()
                .unwrap();
            (
                revision,
                subject,
                vec![(
                    spec.subject.clone(),
                    crate::graph::subscription_spec(&spec.desired).unwrap(),
                )],
            )
        };
        let observe = |revision: &str,
                       subscriptions: &Vec<(String, crate::model::SubscriptionSpec)>,
                       pulls: Value| {
            store.record_resource_observation("observer/repo", revision, None, "resource/repo", None, &serde_json::json!({"repository_id": 17, "pull_requests": pulls}), now_ms() + 60_000, subscriptions, None)
                .unwrap()
        };
        let requested = |subject: &str| {
            store
                .claims_for(subject, Some("subscription.mission-requested"))
                .unwrap()
                .into_iter()
                .map(|claim| {
                    claim.body["fields"]["resource"]
                        .as_str()
                        .unwrap()
                        .to_owned()
                })
                .collect::<Vec<_>>()
        };
        let head = |letter: char| letter.to_string().repeat(40);

        // The older build listed items without a state and kept every item it had seen.
        let (_, old_subject, _) = publish_watch("old");
        let old_listing = serde_json::json!([
            {"number": 24, "head": head('a')},
            {"number": 25, "head": head('b')},
            {"number": 73, "head": head('c')},
            {"number": 75, "head": head('d')},
        ]);
        store
            .append_claim(&ClaimInput {
                subject: "resource/repo".into(),
                kind: "resource.observed".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("kind".into(), Value::String("vcs.repository".into())),
                    ("observer".into(), Value::String("observer/repo".into())),
                    (
                        "facts".into(),
                        serde_json::json!({"repository_id": 17, "pull_requests": old_listing}),
                    ),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some("legacy-listing".into()),
            })
            .unwrap();
        // Before item claims carried `head_sha`, #24 was requested without a delivery key; its
        // item claim cites the listing that named its head.
        let listing = store
            .claims_for("resource/repo", Some("resource.observed"))
            .unwrap()
            .pop()
            .unwrap();
        let legacy_item = store
            .append_claim(&ClaimInput {
                subject: "resource/repo/pull-request/24".into(),
                kind: "resource.observed".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("kind".into(), Value::String("vcs.pull-request".into())),
                    (
                        "facts".into(),
                        serde_json::json!({
                            "repository": "resource/repo", "number": 24,
                            "state": "open", "draft": false, "merged": false,
                        }),
                    ),
                ]),
                evidence: vec![listing.id],
                expected_subject: None,
                idempotency_key: Some("legacy-item".into()),
            })
            .unwrap();
        store
            .append_claim(&ClaimInput {
                subject: old_subject.clone(),
                kind: "subscription.mission-requested".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("mission".into(), Value::String("mission/review".into())),
                    (
                        "resource".into(),
                        Value::String("resource/repo/pull-request/24".into()),
                    ),
                    ("resource_input".into(), Value::String("source".into())),
                    ("workspace".into(), Value::String("/srv/reviews".into())),
                    ("discovery".into(), Value::String(legacy_item.id)),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some("legacy-request".into()),
            })
            .unwrap();

        // A new intake run starts over that history, and the newer build lists a state for each
        // item. Merged and closed items stay in the listing as closed.
        let (revision, new_subject, subscriptions) = publish_watch("new");
        observe(
            &revision,
            &subscriptions,
            serde_json::json!([
                {"number": 24, "head": head('a'), "state": "closed", "draft": false},
                {"number": 25, "head": head('b'), "state": "closed", "draft": false},
                {"number": 73, "head": head('c'), "state": "open", "draft": false},
                {"number": 75, "head": head('e'), "state": "open", "draft": false},
                {"number": 99, "head": head('f'), "state": "open", "draft": false},
                {"number": 100, "head": head('g'), "state": "open", "draft": true},
            ]),
        );
        assert_eq!(
            requested(&new_subject),
            [
                "resource/repo/pull-request/75",
                "resource/repo/pull-request/99"
            ],
            "only a new head of an open, ready pull request is reviewed"
        );
        assert_eq!(
            store
                .latest_actual_value("resource/repo/pull-request/24")
                .unwrap()
                .unwrap()["facts"]["state"],
            "closed",
            "the item resource still follows the closure"
        );

        // #24 reopens as a draft and becomes ready at the head the legacy request reviewed.
        for draft in [true, false] {
            observe(
                &revision,
                &subscriptions,
                serde_json::json!([
                    {"number": 24, "head": head('a'), "state": "open", "draft": draft},
                    {"number": 25, "head": head('b'), "state": "closed", "draft": false},
                    {"number": 73, "head": head('c'), "state": "open", "draft": false},
                    {"number": 75, "head": head('e'), "state": "open", "draft": false},
                    {"number": 99, "head": head('f'), "state": "open", "draft": false},
                    {"number": 100, "head": head('g'), "state": "open", "draft": true},
                ]),
            );
        }
        assert_eq!(requested(&new_subject).len(), 2);

        // Before the requests start, #75 moves to a newer head and #99 closes.
        observe(
            &revision,
            &subscriptions,
            serde_json::json!([
                {"number": 24, "head": head('a'), "state": "open", "draft": false},
                {"number": 25, "head": head('b'), "state": "closed", "draft": false},
                {"number": 73, "head": head('c'), "state": "open", "draft": false},
                {"number": 75, "head": head('h'), "state": "open", "draft": false},
                {"number": 99, "head": head('f'), "state": "closed", "draft": false},
                {"number": 100, "head": head('g'), "state": "open", "draft": true},
            ]),
        );
        assert_eq!(
            requested(&new_subject),
            [
                "resource/repo/pull-request/75",
                "resource/repo/pull-request/99",
                "resource/repo/pull-request/75",
            ]
        );
        let desired = store.desired_subjects().unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        reconciler
            .reconcile_subscription_missions(&desired)
            .unwrap();
        let started = store
            .claims_for(&new_subject, Some("subscription.mission-started"))
            .unwrap();
        assert_eq!(started.len(), 1, "only the current head of #75 is reviewed");
        let run = started[0].body["fields"]["mission_run"].as_str().unwrap();
        let run = store.mission_run(run).unwrap().unwrap();
        let pinned = store
            .claim_by_id(run.inputs["source"].claim_id.as_deref().unwrap())
            .unwrap()
            .unwrap();
        assert_eq!(pinned.body["fields"]["facts"]["head_sha"], head('h'));
        let mut reasons = store
            .claims_for(&new_subject, Some("subscription.mission-request-cancelled"))
            .unwrap()
            .into_iter()
            .map(|claim| claim.body["fields"]["reason"].as_str().unwrap().to_owned())
            .collect::<Vec<_>>();
        reasons.sort();
        assert_eq!(
            reasons,
            [
                format!(
                    "pull request #75 moved from head {} to {}",
                    head('e')[..12].to_owned(),
                    head('h')[..12].to_owned()
                ),
                "pull request #99 is closed".to_owned(),
            ]
        );
    }

    #[test]
    fn run_scoped_intake_replacement_keeps_its_local_delivery_history() {
        let store = Store::open_memory("node").unwrap();
        apply_source(&store, REDELIVERY_REVIEW_SOURCE, "review");
        let publish_watch = |run: &str| {
            apply_source(
                &store,
                &format!(
                    r#"version 2
resource "repo" {{ kind "vcs.repository" }}
observer "repo" {{ resource "resource/repo"; provider "github.repository"; locator "example/repo"; field "pull_requests" }}
subscription "run/{run}/reviews" {{
  observer "observer/repo"; on "pull_requests"
  delivery "mission" {{ mission "review"; resource "source"; workspace "/srv/reviews" }}
}}"#
                ),
                &format!("watch-{run}"),
            );
            let subject = format!("subscription/run/{run}/reviews");
            let desired = store.desired_subjects().unwrap();
            let spec = desired.iter().find(|item| item.subject == subject).unwrap();
            let revision = store
                .selected_desired_revision("observer/repo")
                .unwrap()
                .unwrap();
            (
                revision,
                subject,
                vec![(
                    spec.subject.clone(),
                    crate::graph::subscription_spec(&spec.desired).unwrap(),
                )],
            )
        };
        let observe = |revision: &str,
                       subscriptions: &Vec<(String, crate::model::SubscriptionSpec)>,
                       head: Option<&str>,
                       state: &str| {
            let pulls = head.map(|head| serde_json::json!([{"number": 4, "head": head, "state": state, "draft": false}])).unwrap_or_else(|| serde_json::json!([]));
            store.record_resource_observation("observer/repo", revision, None, "resource/repo", None, &serde_json::json!({"repository_id": 17, "pull_requests": pulls}), now_ms() + 60_000, subscriptions, None)
                .unwrap();
        };
        let a = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
        let b = "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
        let (revision, old_subject, subscriptions) = publish_watch("old");
        observe(&revision, &subscriptions, None, "open");
        observe(&revision, &subscriptions, Some(a), "open");
        assert_eq!(
            store
                .claims_for(&old_subject, Some("subscription.mission-requested"))
                .unwrap()
                .len(),
            1
        );
        let (revision, new_subject, subscriptions) = publish_watch("new");
        observe(&revision, &subscriptions, Some(a), "closed");
        assert!(
            store
                .claims_for(&new_subject, Some("subscription.mission-requested"))
                .unwrap()
                .is_empty()
        );
        observe(&revision, &subscriptions, Some(b), "open");
        assert_eq!(
            store
                .claims_for(&new_subject, Some("subscription.mission-requested"))
                .unwrap()
                .len(),
            1
        );
    }

    #[test]
    fn persisted_intake_history_survives_reopen_for_heads_and_issues() {
        let directory = tempfile::tempdir().unwrap();
        let path = directory.path().join("intake.sqlite");
        let a = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
        let b = "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
        let watch = |store: &Store, name: &str| {
            apply_source(
                store,
                &format!(
                    r#"version 2
resource "repo" {{ kind "vcs.repository" }}
observer "repo" {{ resource "resource/repo"; provider "github.repository"; locator "example/repo"; field "pull_requests"; field "issues" }}
subscription "reviews" {{
  observer "observer/repo"; on "pull_requests"
  delivery "mission" {{ mission "review"; resource "source"; workspace "/srv/reviews" }}
}}
subscription "triage" {{
  observer "observer/repo"; on "issues"
  delivery "mission" {{ mission "triage"; resource "source"; workspace "/srv/triage" }}
}}"#
                ),
                &format!("watch-{name}"),
            );
            let desired = store.desired_subjects().unwrap();
            let subscriptions = desired
                .iter()
                .filter(|item| {
                    item.subject == "subscription/reviews" || item.subject == "subscription/triage"
                })
                .map(|item| {
                    (
                        item.subject.clone(),
                        crate::graph::subscription_spec(&item.desired).unwrap(),
                    )
                })
                .collect::<Vec<_>>();
            let revision = store
                .selected_desired_revision("observer/repo")
                .unwrap()
                .unwrap();
            (revision, subscriptions)
        };
        let observe = |store: &Store,
                       revision: &str,
                       subscriptions: &Vec<(String, crate::model::SubscriptionSpec)>,
                       head: Option<&str>,
                       issue_title: Option<&str>,
                       state: &str| {
            let pulls = head.map(|head| serde_json::json!([{"number": 4, "head": head, "state": state, "draft": false}])).unwrap_or_else(|| serde_json::json!([]));
            let issues = issue_title
                .map(|title| serde_json::json!([{"number": 5, "title": title}]))
                .unwrap_or_else(|| serde_json::json!([]));
            store.record_resource_observation("observer/repo", revision, None, "resource/repo", None, &serde_json::json!({"repository_id": 17, "pull_requests": pulls, "issues": issues}), now_ms() + 60_000, subscriptions, None).unwrap();
        };
        {
            let store = Store::open(&path, "node").unwrap();
            apply_source(&store, REDELIVERY_REVIEW_SOURCE, "review");
            apply_source(
                &store,
                &REDELIVERY_REVIEW_SOURCE.replace("mission \"review\"", "mission \"triage\""),
                "triage",
            );
            let (revision, subscriptions) = watch(&store, "old");
            observe(&store, &revision, &subscriptions, None, None, "open");
            observe(
                &store,
                &revision,
                &subscriptions,
                Some(a),
                Some("bug"),
                "open",
            );
            assert_eq!(
                store
                    .claims_for(
                        "subscription/reviews",
                        Some("subscription.mission-requested")
                    )
                    .unwrap()
                    .len(),
                1
            );
            assert_eq!(
                store
                    .claims_for(
                        "subscription/triage",
                        Some("subscription.mission-requested")
                    )
                    .unwrap()
                    .len(),
                1
            );
        }
        {
            let store = Store::open(&path, "node").unwrap();
            let (revision, subscriptions) = watch(&store, "new");
            observe(
                &store,
                &revision,
                &subscriptions,
                Some(a),
                Some("edited bug"),
                "closed",
            );
            assert!(
                store
                    .claims_for(
                        "subscription/reviews",
                        Some("subscription.mission-requested")
                    )
                    .unwrap()
                    .len()
                    == 1
            );
            assert!(
                store
                    .claims_for(
                        "subscription/triage",
                        Some("subscription.mission-requested")
                    )
                    .unwrap()
                    .len()
                    == 1
            );
            observe(
                &store,
                &revision,
                &subscriptions,
                Some(b),
                Some("edited bug"),
                "open",
            );
            assert_eq!(
                store
                    .claims_for(
                        "subscription/reviews",
                        Some("subscription.mission-requested")
                    )
                    .unwrap()
                    .len(),
                2
            );
            assert!(
                store
                    .claims_for(
                        "subscription/triage",
                        Some("subscription.mission-requested")
                    )
                    .unwrap()
                    .len()
                    == 1
            );
        }
    }

    #[test]
    fn unpinned_intake_uses_the_review_revision_current_at_start() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(&store, REDELIVERY_REVIEW_SOURCE, "review-one");
        let first = store
            .mission_spec("review", None)
            .unwrap()
            .unwrap()
            .revision;
        apply_source(
            &store,
            r#"version 2
resource "repo" { kind "vcs.repository" }
observer "repo" { resource "resource/repo"; provider "github.repository"; locator "example/repo"; field "pull_requests" }
subscription "reviews" {
  observer "observer/repo"
  on "pull_requests"
  delivery "mission" { mission "review"; resource "source"; workspace "/srv/reviews" }
}"#,
            "unpinned-watch",
        );
        let desired = store.desired_subjects().unwrap();
        let subscription = desired
            .iter()
            .find(|item| item.subject == "subscription/reviews")
            .unwrap();
        let subscriptions = vec![(
            subscription.subject.clone(),
            crate::graph::subscription_spec(&subscription.desired).unwrap(),
        )];
        let observer_revision = store
            .selected_desired_revision("observer/repo")
            .unwrap()
            .unwrap();
        let observe = |pulls: Value| {
            store.record_resource_observation("observer/repo", &observer_revision, None, "resource/repo", None, &serde_json::json!({"repository_id": 17, "pull_requests": pulls}), now_ms() + 60_000, &subscriptions, None)
                .unwrap();
        };
        observe(serde_json::json!([]));
        observe(
            serde_json::json!([{"number": 4, "head": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa", "state": "open", "draft": false}]),
        );
        let request = store
            .claims_for(
                "subscription/reviews",
                Some("subscription.mission-requested"),
            )
            .unwrap();
        assert_eq!(request.len(), 1);
        assert!(
            request[0]
                .body
                .pointer("/fields/mission_revision")
                .is_none()
        );

        apply_source(
            &store,
            &REDELIVERY_REVIEW_SOURCE
                .replace("Review one discovered item.", "Review the updated item."),
            "review-two",
        );
        let current = store
            .mission_spec("review", None)
            .unwrap()
            .unwrap()
            .revision;
        assert_ne!(first, current);
        Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        )
        .reconcile_subscription_missions(&desired)
        .unwrap();
        let runs = store.active_mission_runs_for_mission("review").unwrap();
        assert_eq!(runs.len(), 1);
        assert_eq!(runs[0].revision, current);
    }

    #[test]
    fn intake_skips_a_pull_request_with_its_own_mission_review_gate() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(&store, REDELIVERY_REVIEW_SOURCE, "intake-review");
        apply_source(
            &store,
            r#"version 2
mission "author" state="ready" {
  goal "Open and approve one pull request."
  step "open" {
    agentless
    produces { resource "mission-run/${ST_MISSION_RUN}/pull-request" { kind "vcs.pull-request" } }
  }
  step "approve" {
    agentless
    depends-on { step "open" completed }
    gate "approve the exact pull request" type="human" {
      reviewer "person/owner"
      review "resource/mission-run/${ST_MISSION_RUN}/pull-request"
    }
  }
}"#,
            "author-mission",
        );
        let author = store
            .create_mission_run(&MissionRunRequest {
                mission: "author".into(),
                revision: None,
                workspace: "/srv/author".into(),
                requester: Some("person/owner".into()),
                mode: None,
                inputs: BTreeMap::new(),
                idempotency_key: "author-run".into(),
            })
            .unwrap();
        let authored_resource = format!("resource/{}/pull-request", author.subject);
        apply_source(
            &store,
            &format!(
                "version 2\nresource \"{}/pull-request\" {{ kind \"vcs.pull-request\" }}",
                author.subject
            ),
            "authored-resource",
        );
        store
            .append_claim(&ClaimInput {
                subject: authored_resource,
                kind: "resource.observed".into(),
                actor: Some("person/owner".into()),
                fields: BTreeMap::from([
                    ("kind".into(), Value::String("vcs.pull-request".into())),
                    (
                        "facts".into(),
                        serde_json::json!({
                            "repository": "resource/repo", "number": 4,
                            "url": "https://example.test/repo/pull/4",
                            "head_sha": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
                            "state": "open", "draft": false, "merged": false
                        }),
                    ),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some("authored-pr".into()),
            })
            .unwrap();
        apply_source(
            &store,
            r#"version 2
resource "repo" { kind "vcs.repository" }
observer "repo" { resource "resource/repo"; provider "github.repository"; locator "example/repo"; field "pull_requests" }
subscription "reviews" {
  observer "observer/repo"; on "pull_requests"
  delivery "mission" { mission "review"; resource "source"; workspace "/srv/reviews" }
}"#,
            "intake-watch",
        );
        let desired = store.desired_subjects().unwrap();
        let subscription = desired
            .iter()
            .find(|item| item.subject == "subscription/reviews")
            .unwrap();
        let subscriptions = vec![(
            subscription.subject.clone(),
            crate::graph::subscription_spec(&subscription.desired).unwrap(),
        )];
        let observer_revision = store
            .selected_desired_revision("observer/repo")
            .unwrap()
            .unwrap();
        for pulls in [
            serde_json::json!([]),
            serde_json::json!([{
                "number": 4, "head": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
                "html_url": "https://example.test/repo/pull/4", "url": "https://example.test/repo/pull/4",
                "state": "open", "draft": false
            }]),
        ] {
            store.record_resource_observation("observer/repo", &observer_revision, None, "resource/repo", None, &serde_json::json!({"repository_id": 17, "pull_requests": pulls}), now_ms() + 60_000, &subscriptions, None)
                .unwrap();
        }
        assert_eq!(
            store
                .latest_actual_value("resource/repo/pull-request/4")
                .unwrap()
                .unwrap()["facts"]["opened_by_run"],
            author.subject.as_str(),
            "the pull request names the run that published its resource"
        );
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        reconciler
            .reconcile_subscription_missions(&desired)
            .unwrap();
        assert!(
            store
                .active_mission_runs_for_mission("review")
                .unwrap()
                .is_empty()
        );
        let decisions = store
            .claims_for(
                "subscription/reviews",
                Some("subscription.mission-request-cancelled"),
            )
            .unwrap();
        assert_eq!(decisions.len(), 1);
        assert!(
            decisions[0].body["fields"]["reason"]
                .as_str()
                .unwrap()
                .contains(&author.subject)
        );
    }

    /// Declare one repository observer at `locator` and one issue-triage subscription.
    fn watch_repository(
        store: &Store,
        locator: &str,
        review: &str,
        key: &str,
    ) -> Vec<(String, crate::model::SubscriptionSpec)> {
        apply_source(
            store,
            &format!(
                r#"version 2
resource "repo" {{ kind "vcs.repository" }}
observer "repo" {{ resource "resource/repo"; provider "github.repository"; locator "{locator}"; field "issues" }}
subscription "triage" {{
  observer "observer/repo"
  on "issues"
  delivery "mission" {{
    mission "review@{review}"
    resource "source"
    workspace "/tmp/st3-triage"
  }}
}}"#
            ),
            key,
        );
        let desired = store.desired_subjects().unwrap();
        let subscription = desired
            .iter()
            .find(|item| item.subject == "subscription/triage")
            .unwrap();
        vec![(
            subscription.subject.clone(),
            crate::graph::subscription_spec(&subscription.desired).unwrap(),
        )]
    }

    fn record_issues(
        store: &Store,
        facts: &Value,
        subscriptions: &[(String, crate::model::SubscriptionSpec)],
    ) {
        store.record_resource_observation("observer/repo", &store
            .selected_desired_revision("observer/repo")
            .unwrap()
            .unwrap(), None, "resource/repo", None, facts, now_ms() + 60_000, subscriptions, None)
            .unwrap();
    }

    /// Record a complete listing of open issues the way the GitHub repository provider reports
    /// one: each issue it saw, with the facts it read.
    fn observe_issues(
        store: &Store,
        locator: &str,
        numbers: impl IntoIterator<Item = u64>,
        subscriptions: &[(String, crate::model::SubscriptionSpec)],
    ) {
        let issues = numbers
            .into_iter()
            .map(|number| {
                serde_json::json!({
                    "number": number,
                    "title": format!("Issue {number}"),
                    "url": format!("https://github.com/{locator}/issues/{number}"),
                    "state": "open",
                })
            })
            .collect::<Vec<_>>();
        record_issues(
            store,
            &serde_json::json!({"repository_id": 7, "issues": issues}),
            subscriptions,
        );
    }

    /// One repository observer records each item it sees as that item's latest state. An
    /// unchanged poll records nothing, a poll that read only some facts keeps the others, and the
    /// repository resource keeps only its own facts.
    #[test]
    fn a_repository_observer_records_each_item_as_its_own_latest_state() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"version 2
resource "repo" { kind "vcs.repository" }
observer "repo" {
  resource "resource/repo"; provider "github.repository"; locator "acme/garden"
  field "pull_requests"; field "issues"; field "comments"; field "mentions"
}
agent "example.reader" { workspace "/tmp"; command "true" }
subscription "mentions" { observer "observer/repo"; on "mentions"; to "agent/example.reader"; delivery "message" }"#,
            "watch",
        );
        let desired = store.desired_subjects().unwrap();
        let subscription = desired
            .iter()
            .find(|item| item.subject == "subscription/mentions")
            .unwrap();
        let subscriptions = vec![(
            subscription.subject.clone(),
            crate::graph::subscription_spec(&subscription.desired).unwrap(),
        )];
        let revision = store
            .selected_desired_revision("observer/repo")
            .unwrap()
            .unwrap();
        let observe = |facts: Value| {
            store.record_resource_observation("observer/repo", &revision, None, "resource/repo", None, &facts, now_ms() + 60_000, &subscriptions, None)
                .unwrap()
        };
        let facts_of =
            |subject: &str| store.latest_actual_value(subject).unwrap().unwrap()["facts"].clone();
        let head = "a".repeat(40);
        // An older build kept every item in the repository facts.
        store
            .append_claim(&ClaimInput {
                subject: "resource/repo".into(),
                kind: "resource.observed".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("kind".into(), Value::String("vcs.repository".into())),
                    (
                        "facts".into(),
                        serde_json::json!({"repository_id": 7, "pull_requests": [], "issues": [{"number": 3, "title": "Old"}]}),
                    ),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some("legacy-listing".into()),
            })
            .unwrap();
        let first = observe(serde_json::json!({"repository_id": 7, "pull_requests": [{
            "number": 7, "head": head, "branch": "agent/seven", "state": "open", "draft": false,
            "checks_state": "pending", "checks": [{"name": "garden/ci", "status": "pending"}],
        }], "issues": [{"number": 3, "title": "Old", "state": "open", "comments": 0, "new": false}]}));
        assert_eq!(
            facts_of("resource/repo"),
            serde_json::json!({"repository_id": 7}),
            "the repository keeps only its own facts"
        );
        assert!(first.observation_claim.is_some());
        let pull = facts_of("resource/repo/pull-request/7");
        assert_eq!(pull["head_sha"], head);
        assert_eq!(pull["checks_state"], "pending");
        assert_eq!(facts_of("resource/repo/issue/3")["comments"], 0);

        // Nothing changed: no claim at all.
        let before = store.index().unwrap();
        let unchanged = observe(serde_json::json!({"repository_id": 7, "pull_requests": [{
            "number": 7, "head": head, "state": "open", "checks_state": "pending",
            "checks": [{"name": "garden/ci", "status": "pending"}],
        }]}));
        assert!(unchanged.changed_fields.is_empty());
        assert_eq!(store.index().unwrap(), before);

        // A comment that mentions someone changes only what the comment read.
        let comment = serde_json::json!({"number": 7, "new": false,
            "last_comment": {"id": 91, "author": "fern", "created_at": "2026-09-10T05:00:00Z"},
            "mentions": [{"login": "orchid-bot", "by": "fern", "at": "2026-09-10T05:00:00Z"}]});
        let commented =
            observe(serde_json::json!({"repository_id": 7, "pull_requests": [comment]}));
        assert!(commented.observation_claim.is_none());
        assert_eq!(
            commented.changed_fields,
            vec!["comments".to_owned(), "mentions".to_owned()]
        );
        let pull = facts_of("resource/repo/pull-request/7");
        assert_eq!(pull["head_sha"], head, "a fact the poll did not read stays");
        assert_eq!(pull["checks_state"], "pending");
        assert_eq!(pull["last_comment"]["id"], 91);
        let item_claims = store
            .claims_for("resource/repo/pull-request/7", Some("resource.observed"))
            .unwrap();
        assert_eq!(item_claims.len(), 2);
        let changed = item_claims[1].body["fields"]["changed_fields"].clone();
        assert_eq!(changed, serde_json::json!(["last_comment", "mentions"]));
        // The mention subscription hears one message naming the item.
        assert_eq!(commented.message_subjects.len(), 1);
        let message = store
            .claims_for(&commented.message_subjects[0], Some("message.sent"))
            .unwrap()
            .remove(0);
        let content: Value =
            serde_json::from_str(message.body["fields"]["content"].as_str().unwrap()).unwrap();
        assert_eq!(content["changed_fields"], serde_json::json!(["mentions"]));
        assert_eq!(
            content["items"][0]["resource"],
            "resource/repo/pull-request/7"
        );
        assert_eq!(
            content["items"][0]["facts"]["mentions"][0]["login"],
            "orchid-bot"
        );
        assert_eq!(content["items_changed"], 1);

        // A check that finishes is a pull request change, which the mention subscription does
        // not hear.
        let checked = observe(serde_json::json!({"repository_id": 7, "pull_requests": [{
            "number": 7, "checks_state": "success",
            "checks": [{"name": "garden/ci", "status": "completed", "conclusion": "success"}],
        }]}));
        assert_eq!(checked.changed_fields, vec!["pull_requests".to_owned()]);
        assert!(checked.message_subjects.is_empty());

        // An edit to an older comment keeps the last comment, and a later mention of someone
        // else adds to the mentions.
        observe(
            serde_json::json!({"repository_id": 7, "pull_requests": [{"number": 7, "new": false,
            "last_comment": {"id": 80, "author": "moss", "created_at": "2026-09-09T00:00:00Z"},
            "mentions": [{"login": "fern", "by": "moss", "at": "2026-09-11T00:00:00Z"}]}]}),
        );
        let pull = facts_of("resource/repo/pull-request/7");
        assert_eq!(pull["last_comment"]["id"], 91);
        assert_eq!(
            pull["mentions"]
                .as_array()
                .unwrap()
                .iter()
                .map(|mention| mention["login"].as_str().unwrap())
                .collect::<Vec<_>>(),
            ["fern", "orchid-bot"]
        );
    }

    /// Every comment and review an item receives is kept once in `recent_comments`, the newest
    /// twenty, whichever read saw it. A new one is a comments change, which a pull request
    /// subscription does not hear, and an unchanged list records nothing.
    #[test]
    fn recent_comments_keep_each_comment_and_review_once_as_a_comments_change() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"version 2
resource "repo" { kind "vcs.repository" }
observer "repo" {
  resource "resource/repo"; provider "github.repository"; locator "acme/garden"
  field "pull_requests"; field "issues"; field "comments"
}
agent "example.reader" { workspace "/tmp"; command "true" }
subscription "comments" { observer "observer/repo"; on "comments"; to "agent/example.reader"; delivery "message" }
subscription "pulls" { observer "observer/repo"; on "pull_requests"; to "agent/example.reader"; delivery "message" }"#,
            "watch",
        );
        let desired = store.desired_subjects().unwrap();
        let subscriptions = desired
            .iter()
            .filter(|item| item.kind == "subscription")
            .map(|item| {
                (
                    item.subject.clone(),
                    crate::graph::subscription_spec(&item.desired).unwrap(),
                )
            })
            .collect::<Vec<_>>();
        let revision = store
            .selected_desired_revision("observer/repo")
            .unwrap()
            .unwrap();
        let observe = |facts: Value| {
            store.record_resource_observation("observer/repo", &revision, None, "resource/repo", None, &facts, now_ms() + 60_000, &subscriptions, None)
                .unwrap()
        };
        let recent = |number: u64| {
            store
                .latest_actual_value(&format!("resource/repo/pull-request/{number}"))
                .unwrap()
                .unwrap()["facts"]["recent_comments"]
                .as_array()
                .cloned()
                .unwrap_or_default()
                .into_iter()
                .map(|entry| format!("{}:{}", entry["kind"].as_str().unwrap(), entry["id"]))
                .collect::<Vec<_>>()
        };
        let entry = |kind: &str, id: u64, minute: u64| {
            serde_json::json!({"kind": kind, "id": id, "author": "fern",
                "at": format!("2026-09-10T05:{minute:02}:00Z")})
        };
        // What the pull request read adds is valid item facts.
        observe(serde_json::json!({"repository_id": 7, "pull_requests": [{
            "number": 7, "head": "a".repeat(40), "state": "open", "draft": false,
            "base_branch": "main",
            "required_checks": {"state": "pending", "source": "rules", "checks": ["build"], "failed": []},
        }]}));
        let pull = store
            .latest_actual_value("resource/repo/pull-request/7")
            .unwrap()
            .unwrap()["facts"]
            .clone();
        assert_eq!(pull["base_branch"], "main");
        assert_eq!(pull["required_checks"]["state"], "pending");
        fractal_schema::registry()
            .validate_resource_facts(
                "vcs.pull-request",
                &pull
                    .as_object()
                    .unwrap()
                    .iter()
                    .map(|(name, value)| (name.clone(), value.clone()))
                    .collect(),
            )
            .unwrap();

        // Two comments in one poll are two entries, oldest first, and wake only comments.
        let commented = observe(serde_json::json!({"repository_id": 7, "pull_requests": [{
            "number": 7, "new": false,
            "recent_comments": [entry("comment", 92, 2), entry("comment", 91, 1)],
        }]}));
        assert_eq!(commented.changed_fields, vec!["comments".to_owned()]);
        assert_eq!(commented.message_subjects.len(), 1);
        assert_eq!(recent(7), ["comment:91", "comment:92"]);

        // A review from the pull request read joins the comments; a repeated entry stays once.
        observe(serde_json::json!({"repository_id": 7, "pull_requests": [{
            "number": 7, "new": false,
            "recent_comments": [entry("review", 5001, 3), entry("comment", 92, 2)],
        }]}));
        assert_eq!(recent(7), ["comment:91", "comment:92", "review:5001"]);
        let pull = store
            .latest_actual_value("resource/repo/pull-request/7")
            .unwrap()
            .unwrap()["facts"]
            .clone();
        fractal_schema::registry()
            .validate_resource_facts(
                "vcs.pull-request",
                &pull
                    .as_object()
                    .unwrap()
                    .iter()
                    .map(|(name, value)| (name.clone(), value.clone()))
                    .collect(),
            )
            .unwrap();

        // The same entries again record nothing.
        let before = store.index().unwrap();
        let unchanged = observe(serde_json::json!({"repository_id": 7, "pull_requests": [{
            "number": 7, "recent_comments": [entry("comment", 91, 1), entry("review", 5001, 3)],
        }]}));
        assert!(unchanged.changed_fields.is_empty());
        assert_eq!(store.index().unwrap(), before);

        // Only the newest twenty stay.
        let burst = (0..25)
            .map(|index| entry("comment", 100 + index, 10 + index))
            .collect::<Vec<_>>();
        observe(serde_json::json!({"repository_id": 7, "pull_requests": [{
            "number": 7, "new": false, "recent_comments": burst,
        }]}));
        let kept = recent(7);
        assert_eq!(kept.len(), crate::resource::RECENT_COMMENTS);
        assert_eq!(kept.first().unwrap(), "comment:105");
        assert_eq!(kept.last().unwrap(), "comment:124");
    }

    /// The observation writes and their watches, on one store: what `record_resource_observation`
    /// sends each watch of the standing observer.
    struct WatchFixture {
        store: Arc<Store>,
        observer: String,
        resource: String,
    }

    impl WatchFixture {
        fn new() -> Self {
            let store = Arc::new(Store::open_memory("node").unwrap());
            apply_source(
                &store,
                r#"version 2
agent "example.planner" { workspace "/tmp"; command "true" }
agent "example.reviewer" { workspace "/tmp"; command "true" }"#,
                "watch-seats",
            );
            let thread = crate::github_watch::ThreadRef::parse("acme/garden#12").unwrap();
            Self {
                observer: thread.observer(),
                resource: thread.resource(),
                store,
            }
        }

        fn watch(&self, thread: &str, agent: &str) -> String {
            let thread = crate::github_watch::ThreadRef::parse(thread).unwrap();
            self.store.declare_watch(&thread, agent, None).unwrap();
            thread.watch(agent)
        }

        fn observe(&self, facts: Value) -> crate::model::ResourceObservationOutcome {
            let subscriptions = self
                .store
                .desired_subjects()
                .unwrap()
                .into_iter()
                .filter(|item| item.kind == "subscription")
                .filter_map(|item| {
                    Some((
                        item.subject.clone(),
                        crate::graph::subscription_spec(&item.desired)?,
                    ))
                })
                .filter(|(_, spec)| !spec.stopped)
                .collect::<Vec<_>>();
            let revision = self
                .store
                .selected_desired_revision(&self.observer)
                .unwrap()
                .unwrap();
            self.store.record_resource_observation(&self.observer, &revision, None, &self.resource, None, &facts, now_ms() + 60_000, &subscriptions, None)
                .unwrap()
        }

        /// The wakes each seat has, oldest first, as their titles.
        fn wakes(&self, agent: &str) -> Vec<String> {
            self.store
                .messages(Some(agent), true)
                .unwrap()
                .into_iter()
                .filter(|message| message.tags.iter().any(|tag| tag == "github-watch"))
                .map(|message| message.title.unwrap_or_default())
                .collect()
        }

        fn reconcile(&self) {
            let reconciler = Reconciler::new(
                self.store.clone(),
                Arc::new(FakeRuntime::default()),
                "node".into(),
                Arc::new(Notify::new()),
            );
            reconciler
                .reconcile_github_watches(&self.store.desired_subjects().unwrap())
                .unwrap();
        }

        fn running(&self, subject: &str) -> bool {
            self.store
                .desired_subjects_named(&[subject.to_owned()])
                .unwrap()
                .into_iter()
                .next()
                .is_some_and(|desired| desired.desired["children"][0]["name"] != "stop")
        }
    }

    fn watched_pull(number: u64, extra: Value) -> Value {
        let mut pull = serde_json::json!({
            "number": number, "title": format!("Pull {number}"),
            "url": format!("https://github.com/acme/garden/pull/{number}"),
            "head": "a".repeat(40), "state": "open", "draft": false,
            "merge_queue": null,
            "required_checks": {"state": "pending", "source": "rules", "checks": ["build"], "failed": []},
        });
        for (name, value) in extra.as_object().unwrap() {
            pull[name] = value.clone();
        }
        pull
    }

    fn just_now(seconds_ago: i64) -> String {
        (Utc::now() - chrono::Duration::seconds(seconds_ago))
            .to_rfc3339_opts(SecondsFormat::Secs, true)
    }

    /// A seat's watch wakes it once for each comment and review anyone else posts, once for each
    /// move of the required checks into pass or fail on the current head, and a last time when
    /// the pull request merges, which ends that watch only. The baseline and a repeated
    /// observation wake nobody.
    #[test]
    fn a_watch_wakes_once_per_comment_review_and_check_move_and_ends_on_merge() {
        let fixture = WatchFixture::new();
        let planner = "agent/example.planner";
        let reviewer = "agent/example.reviewer";
        let watch = fixture.watch("acme/garden#12", planner);
        fixture.watch("acme/garden#13", reviewer);
        let comment = |id: u64, seconds_ago: i64| serde_json::json!({"kind": "comment", "id": id, "author": "fern", "at": just_now(seconds_ago)});

        // The first observation is the baseline.
        let baseline = fixture.observe(serde_json::json!({"repository_id": 7, "pull_requests": [
            watched_pull(12, serde_json::json!({"recent_comments": [comment(90, 3_600)]})),
            watched_pull(13, serde_json::json!({})),
        ]}));
        assert!(baseline.baseline);
        assert!(fixture.wakes(planner).is_empty());

        // Two comments in one poll are two wakes.
        let both = serde_json::json!({"repository_id": 7, "pull_requests": [watched_pull(12, serde_json::json!({
            "new": false, "recent_comments": [comment(92, 20), comment(91, 30)]}))]});
        fixture.observe(both.clone());
        assert_eq!(
            fixture.wakes(planner),
            [
                "@fern commented on acme/garden#12",
                "@fern commented on acme/garden#12"
            ]
        );
        // The same observation again, and the same comments seen again, wake nobody.
        fixture.observe(both);
        fixture.observe(serde_json::json!({"repository_id": 7, "pull_requests": [watched_pull(12, serde_json::json!({
            "new": false, "recent_comments": [comment(91, 30), comment(92, 20)]}))]}));
        assert_eq!(fixture.wakes(planner).len(), 2);
        assert!(
            fixture.wakes(reviewer).is_empty(),
            "another thread's watch hears nothing"
        );

        // A review.
        fixture.observe(serde_json::json!({"repository_id": 7, "pull_requests": [watched_pull(12, serde_json::json!({
            "new": false, "recent_comments": [{"kind": "review", "id": 5001, "author": "moss",
                "at": just_now(10), "state": "changes_requested"}]}))]}));
        assert_eq!(
            fixture.wakes(planner).last().unwrap(),
            "@moss requested changes on acme/garden#12"
        );

        // The required checks fail, are rerun, and fail again on the same head: two wakes. A new
        // head wakes while pending, then again when its required checks pass.
        let checks = |head: &str, state: &str| {
            serde_json::json!({"repository_id": 7, "pull_requests": [watched_pull(12, serde_json::json!({
                "new": false, "head": head,
                "required_checks": {"state": state, "source": "rules", "checks": ["build"],
                    "failed": if state == "fail" { serde_json::json!(["build"]) } else { serde_json::json!([]) }}}))]})
        };
        for (head, state) in [
            ("a", "fail"),
            ("a", "pending"),
            ("a", "fail"),
            ("b", "pending"),
            ("b", "pass"),
        ] {
            fixture.observe(checks(&head.repeat(40), state));
        }
        let wakes = fixture.wakes(planner);
        assert_eq!(
            wakes[3..],
            [
                "Required checks failed on acme/garden#12",
                "Required checks failed on acme/garden#12",
                "Pull request changed on acme/garden#12",
                "Required checks passed on acme/garden#12",
            ]
        );

        // Queue membership and draft changes arrive once each; position churn is silent.
        let queued = |position: u64, draft: bool| serde_json::json!({"repository_id": 7,
            "pull_requests": [watched_pull(12, serde_json::json!({"new": false,
                "head": "b".repeat(40), "draft": draft,
                "required_checks": {"state": "pass", "source": "rules", "checks": ["build"], "failed": []},
                "merge_queue": {"state": "queued", "position": position}}))]});
        fixture.observe(queued(3, false));
        let after_queue = fixture.wakes(planner).len();
        assert_eq!(fixture.wakes(planner).last().unwrap(), "Pull request changed on acme/garden#12");
        fixture.observe(queued(3, false));
        fixture.observe(queued(2, false));
        assert_eq!(fixture.wakes(planner).len(), after_queue);
        fixture.observe(queued(2, true));
        assert_eq!(fixture.wakes(planner).len(), after_queue + 1);
        let ejected = serde_json::json!({"repository_id": 7,
            "pull_requests": [watched_pull(12, serde_json::json!({"new": false,
                "head": "b".repeat(40), "draft": false,
                "required_checks": {"state": "pass", "source": "rules", "checks": ["build"], "failed": []},
                "merge_queue": null}))]});
        fixture.observe(ejected.clone());
        fixture.observe(ejected);
        assert_eq!(fixture.wakes(planner).len(), after_queue + 2);
        assert!(fixture.wakes(reviewer).is_empty());

        // The merge is the last wake, and ends that watch only.
        fixture.observe(serde_json::json!({"repository_id": 7, "pull_requests": [
            {"number": 12, "state": "closed", "merged": true},
        ]}));
        assert_eq!(
            fixture.wakes(planner).last().unwrap(),
            "acme/garden#12 merged"
        );
        let ended = fixture
            .store
            .claims_for(&watch, Some("subscription.watch-ended"))
            .unwrap();
        assert_eq!(ended.len(), 1);
        assert_eq!(ended[0].body["fields"]["reason"], "merged");
        let after_merge = fixture.wakes(planner).len();
        fixture.observe(serde_json::json!({"repository_id": 7, "pull_requests": [
            watched_pull(12, serde_json::json!({"new": false, "state": "closed", "merged": true,
                "recent_comments": [comment(93, 5)]})),
            watched_pull(13, serde_json::json!({"new": false, "recent_comments": [comment(94, 5)]})),
        ]}));
        assert_eq!(
            fixture.wakes(planner).len(),
            after_merge,
            "an ended watch hears nothing"
        );
        assert_eq!(
            fixture.wakes(reviewer),
            ["@fern commented on acme/garden#13"],
            "the other seat's watch goes on"
        );
        let view = fixture.store.watch_view(&watch).unwrap().unwrap();
        assert_eq!(view["state"], "ended");
        assert_eq!(view["ended"], "merged");
    }

    /// Two seats post as one GitHub login and watch one thread. A comment one seat recorded as
    /// its own wakes only the other, which hears whose it was; an unrecorded comment from that
    /// login wakes both, since a person may share it. A wake that reached the poster before its
    /// record did closes when the record lands.
    #[test]
    fn a_seats_own_comment_wakes_only_the_other_seat_by_its_github_id() {
        let fixture = WatchFixture::new();
        let planner = "agent/example.planner";
        let reviewer = "agent/example.reviewer";
        let thread = crate::github_watch::ThreadRef::parse("acme/garden#12").unwrap();
        fixture.watch("acme/garden#12", planner);
        fixture.watch("acme/garden#12", reviewer);
        let by = |id: u64, login: &str, seconds_ago: i64| serde_json::json!({"kind": "comment", "id": id, "author": login, "at": just_now(seconds_ago)});
        fixture.observe(serde_json::json!({"repository_id": 7, "pull_requests": [watched_pull(12, serde_json::json!({}))]}));
        fixture
            .store
            .record_github_post(
                planner,
                &thread,
                "comment",
                95,
                "https://github.com/acme/garden/pull/12#issuecomment-95",
                "fleet-login",
            )
            .unwrap();
        fixture.observe(serde_json::json!({"repository_id": 7, "pull_requests": [watched_pull(12, serde_json::json!({
            "new": false, "recent_comments": [by(95, "fleet-login", 30), by(96, "fleet-login", 20), by(97, "fern", 10)]}))]}));
        assert_eq!(
            fixture.wakes(planner),
            [
                "@fleet-login commented on acme/garden#12",
                "@fern commented on acme/garden#12"
            ]
        );
        assert_eq!(
            fixture.wakes(reviewer),
            [
                "agent/example.planner (as @fleet-login) commented on acme/garden#12",
                "@fleet-login commented on acme/garden#12",
                "@fern commented on acme/garden#12",
            ]
        );

        // The observing host saw the reviewer's comment before its record arrived.
        fixture.observe(serde_json::json!({"repository_id": 7, "pull_requests": [watched_pull(12, serde_json::json!({
            "new": false, "recent_comments": [by(98, "fleet-login", 5)]}))]}));
        let open = |agent: &str| {
            fixture
                .store
                .messages(Some(agent), false)
                .unwrap()
                .into_iter()
                .filter(|message| message.content.contains("#issuecomment-98"))
                .count()
        };
        assert_eq!(open(reviewer), 1);
        fixture
            .store
            .record_github_post(
                reviewer,
                &thread,
                "comment",
                98,
                "https://github.com/acme/garden/pull/12#issuecomment-98",
                "fleet-login",
            )
            .unwrap();
        assert_eq!(open(reviewer), 0, "the record closes the reviewer's wake");
        assert_eq!(open(planner), 1, "the planner still hears it");

        // The first seat to record an ID keeps it.
        let refused = fixture
            .store
            .record_github_post(planner, &thread, "comment", 98, "", "fleet-login")
            .unwrap_err();
        assert_eq!(refused.code, "github-post-registered");
        fixture
            .store
            .record_github_post(reviewer, &thread, "comment", 98, "", "fleet-login")
            .unwrap();
    }

    #[tokio::test]
    async fn a_stopped_seat_keeps_its_watch_and_the_repository_observer() {
        let fixture = WatchFixture::new();
        let planner = "agent/example.planner";
        let watch = fixture.watch("acme/garden#12", planner);
        apply_source(
            &fixture.store,
            "version 2\nstop \"agent/example.planner\"\n",
            "planner-stops",
        );
        fixture.reconcile();
        assert!(fixture.running(&watch));
        assert!(fixture.running(&fixture.observer));
        assert!(fixture.wakes(planner).is_empty());

        apply_source(
            &fixture.store,
            "version 2\nagent \"example.planner\" { workspace \"/tmp\"; command \"true\" }",
            "planner-starts",
        );
        fixture.reconcile();
        assert!(fixture.running(&watch));
        assert!(fixture.running(&fixture.observer));
        assert_eq!(
            fixture.store.watch_view(&watch).unwrap().unwrap()["state"],
            "active"
        );
    }

    #[tokio::test]
    async fn a_fresh_conversation_ends_only_its_existing_watches_silently() {
        let fixture = WatchFixture::new();
        let planner = "agent/example.planner";
        let thread = crate::github_watch::ThreadRef::parse("acme/garden#12").unwrap();
        let watch = fixture.watch("acme/garden#12", planner);
        let other = fixture.watch("acme/garden#13", "agent/example.reviewer");
        // This is the reset that prepare_fresh_context records for a new conversation.
        fixture
            .store
            .append_claim(&ClaimInput {
                subject: planner.into(),
                kind: "runtime.action.requested".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("action".into(), serde_json::json!("fresh-context")),
                    ("operation".into(), serde_json::json!("example/fresh")),
                    ("incarnation_id".into(), serde_json::json!("old")),
                ]),
                evidence: vec![],
                expected_subject: None,
                idempotency_key: Some("example-fresh".into()),
            })
            .unwrap();
        // Extending the deadline does not hide a reset since the watch began.
        fixture
            .store
            .declare_watch(&thread, planner, Some(now_ms() + 60_000))
            .unwrap();
        fixture.reconcile();
        assert_eq!(
            fixture.store.watch_view(&watch).unwrap().unwrap()["ended"],
            "seat-ended"
        );
        assert!(!fixture.running(&watch));
        assert!(fixture.running(&other) && fixture.running(&fixture.observer));
        assert!(fixture.wakes(planner).is_empty());

        // A watch declared in the new conversation survives the old reset.
        fixture.store.declare_watch(&thread, planner, None).unwrap();
        fixture.reconcile();
        assert!(fixture.running(&watch));
        assert_eq!(
            fixture.store.watch_view(&watch).unwrap().unwrap()["state"],
            "active"
        );
    }

    #[tokio::test]
    async fn a_watch_deadline_wakes_a_stopped_seat_and_the_last_ending_stops_the_observer() {
        let fixture = WatchFixture::new();
        let planner = "agent/example.planner";
        let reviewer = "agent/example.reviewer";
        let twelve = crate::github_watch::ThreadRef::parse("acme/garden#12").unwrap();
        let planner_watch = fixture.watch("acme/garden#12", planner);
        let reviewer_watch = fixture.watch("acme/garden#13", reviewer);
        apply_source(
            &fixture.store,
            "version 2\nstop \"agent/example.planner\"\nstop \"agent/example.reviewer\"\n",
            "watchers-stop",
        );
        let (_, watch) = fixture.store.live_watch(&planner_watch).unwrap().unwrap();
        // Install an elapsed deadline directly so the proof needs no wall-clock sleep.
        let source = crate::github_watch::watch_source(
            &twelve,
            planner,
            watch.since_unix_ms,
            Some(now_ms() - 1),
        );
        let intent = crate::graph::parse_internal_intent(&source, "node").unwrap();
        fixture
            .store
            .apply_internal(&intent, "elapsed-deadline")
            .unwrap();
        fixture.reconcile();
        assert_eq!(
            fixture.wakes(planner),
            ["Your watch on acme/garden#12 reached its deadline"]
        );
        assert_eq!(
            fixture.store.watch_view(&planner_watch).unwrap().unwrap()["ended"],
            "deadline"
        );
        assert!(!fixture.running(&planner_watch));
        assert!(fixture.running(&reviewer_watch) && fixture.running(&fixture.observer));

        fixture
            .store
            .end_watch(&reviewer_watch, "unwatched", None)
            .unwrap();
        fixture.reconcile();
        assert!(!fixture.running(&fixture.observer));
        fixture.reconcile();
        assert_eq!(
            fixture.wakes(planner).len(),
            1,
            "the final wake is not repeated"
        );

        // Watching again starts the observer again.
        fixture.store.declare_watch(&twelve, planner, None).unwrap();
        assert!(fixture.running(&fixture.observer) && fixture.running(&planner_watch));
    }

    /// `st gh watch` declares the standing observer, which reads issues, before the watch that
    /// adds pull requests and comments. A poll between the two reads issues alone, so the arm the
    /// watch brings polls at once instead of waiting out the cadence that poll set (#4470).
    #[tokio::test]
    async fn an_observer_whose_fields_widen_after_a_poll_polls_again_at_once() {
        struct FieldsProvider {
            requests: Arc<Mutex<Vec<BTreeSet<String>>>>,
        }
        impl ResourceProvider for FieldsProvider {
            fn observe(&self, request: ObservationRequest) -> std::pin::Pin<Box<
                dyn Future<Output = Result<crate::resource::ProviderObservation>> + Send + '_
            >> {
                self.requests.lock().unwrap().push(request.fields);
                Box::pin(async {
                    Ok(crate::resource::ProviderObservation {
                        facts: serde_json::json!({"repository_id": 7, "issues": []}),
                        cursor: Some("read".into()),
                        next_check_unix_ms: now_ms() + 300_000,
                    })
                })
            }
        }
        let fixture = WatchFixture::new();
        let thread = crate::github_watch::ThreadRef::parse("acme/garden#12").unwrap();
        let requests = Arc::new(Mutex::new(Vec::new()));
        let reconciler = Reconciler::new(
            fixture.store.clone(), Arc::new(FakeRuntime::default()), "node".into(), Arc::new(Notify::new()),
        ).with_resource_provider(Arc::new(FieldsProvider { requests: requests.clone() }));
        let poll = |count: usize| {
            reconciler.reconcile_resource_observers(&reconciler.store.desired_subjects().unwrap(), &[]).unwrap();
            let requests = requests.clone();
            let deadlines = reconciler.observer_deadlines.clone();
            async move {
                tokio::time::timeout(Duration::from_secs(2), async {
                    while requests.lock().unwrap().len() < count || deadlines.lock().unwrap().is_empty() {
                        tokio::task::yield_now().await;
                    }
                }).await.unwrap_or_else(|_| panic!("poll {count} did not run at once: {:?}", requests.lock().unwrap()));
            }
        };

        // The observer alone polls, reads issues, and sets its standing cadence.
        fixture.store.ensure_watch_observer(&thread).unwrap();
        poll(1).await;
        assert_eq!(requests.lock().unwrap()[0], BTreeSet::from(["issues".to_owned()]));
        let deadline = *reconciler.observer_deadlines.lock().unwrap().values().next().unwrap();
        assert!(deadline >= now_ms() + 170_000, "the standing cadence is three minutes");

        // The watch widens what it reads: the next poll comes now, not at that deadline.
        fixture.watch("acme/garden#12", "agent/example.planner");
        poll(2).await;
        assert!(requests.lock().unwrap()[1].contains("pull_requests"), "{:?}", requests.lock().unwrap());

        // The same fields again keep the cadence.
        fixture.store.declare_watch(&thread, "agent/example.reviewer", None).unwrap();
        reconciler.reconcile_resource_observers(&reconciler.store.desired_subjects().unwrap(), &[]).unwrap();
        tokio::time::sleep(Duration::from_millis(100)).await;
        assert_eq!(requests.lock().unwrap().len(), 2, "{:?}", requests.lock().unwrap());
    }

    /// A watch on a repository that an intake already observes uses the intake's resource, so
    /// the repository's item facts live in one place and either observer's poll serves both.
    #[test]
    fn a_standing_observer_takes_the_resource_a_running_observer_of_its_repository_uses() {
        let fixture = WatchFixture::new();
        apply_source(
            &fixture.store,
            r#"version 2
resource "github/acme/old" { kind "vcs.repository" }
observer "intake" {
  resource "resource/github/acme/old"; provider "github.repository"; locator "Acme/Garden"
  field "pull_requests"
}"#,
            "intake-observer",
        );
        fixture.watch("acme/garden#12", "agent/example.planner");
        let standing = fixture
            .store
            .desired_subjects_named(std::slice::from_ref(&fixture.observer))
            .unwrap()
            .into_iter()
            .next()
            .and_then(|observer| crate::graph::observer_spec(&observer.desired))
            .unwrap();
        assert_eq!(standing.resource, "resource/github/acme/old");
        assert!(
            fixture
                .store
                .desired_subjects_named(std::slice::from_ref(&fixture.resource))
                .unwrap()
                .is_empty(),
            "the standing observer declares no resource of its own"
        );
    }

    /// A repository observer's cursor lives in the polling member's GitHub plugin database; its
    /// claim carries only how far it has read. Across mixed builds: a claim an older build wrote
    /// hands its whole cursor over once, even when the first poll is quiet and writes no claim; a
    /// restart continues from the plugin database; an older build reads the read position from
    /// the folded actual state; and a member without the database resumes from the claim, which
    /// delivers only the item opened meanwhile.
    #[tokio::test]
    async fn a_repository_cursor_moves_to_the_plugin_database_without_flooding() {
        /// Answers one poll with `facts` and `cursor`, and keeps the cursor it was asked from.
        struct OnePoll {
            asked: Arc<Mutex<Vec<Option<String>>>>,
            facts: Value,
            cursor: String,
        }
        impl ResourceProvider for OnePoll {
            fn observe(&self, request: ObservationRequest) -> std::pin::Pin<Box<
                dyn Future<Output = Result<crate::resource::ProviderObservation>> + Send + '_
            >> {
                self.asked.lock().unwrap().push(request.cursor);
                Box::pin(async move { Ok(crate::resource::ProviderObservation {
                    facts: self.facts.clone(),
                    cursor: Some(self.cursor.clone()),
                    next_check_unix_ms: now_ms() + 300_000,
                }) })
            }
        }
        // A repository cursor as the provider writes one: how far it has read, and a version map.
        let cursor = |day: u32| serde_json::json!({
            "items_since": format!("2026-09-{day}T00:00:00Z"),
            "seen": {"items": format!("listing-{day}")},
        }).to_string();
        let position = |day: u32| serde_json::json!({"items_since": format!("2026-09-{day}T00:00:00Z")});
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"version 2
resource "repo" { kind "vcs.repository" }
observer "repo" {
  resource "resource/repo"; provider "github.repository"; locator "acme/garden"
  field "issues"
}
agent "example.reader" { workspace "/tmp"; command "true" }
subscription "issues" { observer "observer/repo"; on "issues"; to "agent/example.reader"; delivery "message" }"#,
            "cursor-watch",
        );
        let revision = store.selected_desired_revision("observer/repo").unwrap().unwrap();
        let issue = |number: u64| serde_json::json!({
            "node_id": format!("I_fixture{number}"), "number": number, "state": "open",
            "url": format!("https://github.com/acme/garden/issues/{number}"),
            "title": format!("issue {number}"),
        });
        let listing = |numbers: &[u64]| serde_json::json!({
            "repository_id": 7,
            "issues": numbers.iter().map(|number| issue(*number)).collect::<Vec<_>>(),
        });
        let subscriptions = store.desired_subjects().unwrap().iter()
            .filter(|item| item.kind == "subscription")
            .map(|item| (item.subject.clone(), crate::graph::subscription_spec(&item.desired).unwrap()))
            .collect::<Vec<_>>();
        // An older build polled first: its baseline knows issue 1, and its claim holds its cursor.
        store.record_resource_observation("observer/repo", &revision, None, "resource/repo",
            Some("old-build"), &listing(&[1]), now_ms() + 60_000, &subscriptions, None).unwrap();
        store.append_claim(&ClaimInput {
            subject: "observer/repo".into(),
            kind: "observer.observed".into(),
            actor: None,
            fields: BTreeMap::from([
                ("status".into(), Value::String("healthy".into())),
                ("revision".into(), Value::String(revision.clone())),
                ("cursor".into(), Value::String("old-build".into())),
                ("changed".into(), Value::Bool(true)),
            ]),
            evidence: Vec::new(),
            expected_subject: None,
            idempotency_key: None,
        }).unwrap();
        let delivered = || store.messages(Some("agent/example.reader"), true).unwrap().len();
        assert_eq!(delivered(), 0, "a baseline delivers nothing");

        let state = tempfile::tempdir().unwrap();
        let asked = Arc::new(Mutex::new(Vec::new()));
        // One poll by a reconciler that keeps cursors in `plugin`, as one daemon process does.
        let poll = |plugin: Arc<github_plugin_store::GithubPluginStore>, facts: Value, cursor: String| {
            let reconciler = Reconciler::new(
                store.clone(), Arc::new(FakeRuntime::default()), "node".into(), Arc::new(Notify::new()),
            )
            .with_github_plugin(plugin.clone())
            .with_mirror_refill(true)
            .with_resource_provider(Arc::new(OnePoll { asked: asked.clone(), facts, cursor: cursor.clone() }));
            // Due now, rather than at the deadline the last poll recorded.
            reconciler.observer_deadlines.lock().unwrap().insert(format!("observer/repo:{revision}"), 0);
            async move {
                reconciler.reconcile_resource_observers(&reconciler.store.desired_subjects().unwrap(), &[]).unwrap();
                // A bound for a loaded machine, not an expected duration.
                tokio::time::timeout(Duration::from_secs(60), async {
                    while plugin.cursor("observer/repo").unwrap() != Some(Some(cursor.clone())) {
                        tokio::time::sleep(Duration::from_millis(20)).await;
                    }
                }).await.expect("the poll keeps its cursor in the plugin database");
            }
        };
        let newest_observed = || store.latest_claim("observer/repo", Some("observer.observed"))
            .unwrap().unwrap().body["fields"].clone();

        // The first poll of this build continues from the older build's claim. Nothing changed,
        // so it writes no claim, and the older build's claim stays the newest.
        let disk = || Arc::new(github_plugin_store::GithubPluginStore::open(state.path()).unwrap());
        poll(disk(), listing(&[1]), cursor(11)).await;
        assert_eq!(delivered(), 0);
        assert_eq!(store.claimed_observer_cursor("observer/repo").unwrap().as_deref(), Some("old-build"));

        // A restart reopens the plugin database: the older build's claim is not adopted again.
        poll(disk(), listing(&[1, 3]), cursor(12)).await;
        assert_eq!(delivered(), 1, "issue 3 opened after the last poll");
        // The poller's new mirror refilled from a look at GitHub of its own, then took each item
        // the poll recorded; a first sighting is a baseline and holds no event.
        let mirror = disk();
        assert!(mirror.filled("resource/repo").unwrap());
        assert_eq!(mirror.item("resource/repo", 1).unwrap().expect("filled from GitHub")["facts"]["title"], "issue 1");
        assert_eq!(mirror.item("resource/repo", 3).unwrap().expect("mirrored from the poll")["kind"], "vcs.issue");
        assert_eq!(mirror.repositories("acme/garden").unwrap()[0]["observer"], "observer/repo");
        assert!(mirror.events("resource/repo", None, 10).unwrap().is_empty());
        let observed = newest_observed();
        assert_eq!(observed["changed"], true);
        // The claim carries how far the poll read, not the version maps.
        let claimed = |observed: &Value| -> Value {
            serde_json::from_str(observed["cursor"].as_str().expect("the claim has a read position")).unwrap()
        };
        assert_eq!(claimed(&observed), position(12), "{observed}");
        // An older build reads the observer's folded actual state: taking over, it reads on from
        // the same position.
        let actual = store.latest_actual_value("observer/repo").unwrap().unwrap();
        assert_eq!(claimed(&actual), position(12));

        // A member without the plugin database, such as one that takes over polling, reads on
        // from the claim's position: only issue 4, opened meanwhile, delivers.
        poll(Arc::new(github_plugin_store::GithubPluginStore::memory()), listing(&[1, 3, 4]), cursor(13)).await;
        assert_eq!(delivered(), 2, "a lost database delivers only what is new");
        // Each poller whose mirror was not filled also looked once from no cursor, recording
        // nothing: the first poll of this build, and the member without the database.
        assert_eq!(*asked.lock().unwrap(), [
            Some("old-build".into()), None, Some(cursor(11)), Some(position(12).to_string()), None,
        ]);
        assert_eq!(claimed(&newest_observed()), position(13));

        // Back on the member with the plugin database, a change the poll records is one keyed
        // event in its mirror.
        let mut closed = issue(3);
        closed["state"] = Value::String("closed".into());
        poll(disk(), serde_json::json!({"repository_id": 7, "issues": [issue(1), closed, issue(4)]}), cursor(14)).await;
        let events = disk().events("resource/repo", Some(3), 10).unwrap();
        assert_eq!(events.len(), 1, "{events:?}");
        assert_eq!(events[0]["event"], "closed");
        assert_eq!(events[0]["subject"], "github-event/repo/issue/3/closed");
    }

    /// In compact mode a poller records a change confined to compact facts as `vcs.item.state`
    /// alone, and each derived event as one `github.event` claim. A change to a fact a wake or
    /// a delivery reads, such as a new comment, still writes a full snapshot, so when polling
    /// moves to a member without the mirror, nothing is delivered twice: the facts that drifted
    /// in the graph are a baseline for its first look.
    #[tokio::test]
    async fn compact_mode_records_compact_changes_alone_and_a_move_delivers_nothing_twice() {
        struct OnePoll {
            facts: Value,
            cursor: String,
        }
        impl ResourceProvider for OnePoll {
            fn observe(&self, _: ObservationRequest) -> std::pin::Pin<Box<
                dyn Future<Output = Result<crate::resource::ProviderObservation>> + Send + '_
            >> {
                Box::pin(async move { Ok(crate::resource::ProviderObservation {
                    facts: self.facts.clone(),
                    cursor: Some(self.cursor.clone()),
                    next_check_unix_ms: now_ms() + 300_000,
                }) })
            }
        }
        let store = Arc::new(Store::open_memory("node").unwrap());
        const EVENT_FLEET: &str = "018f6f0d-4a5d-7b8c-9d0e-123456789abc";
        store.bind_fleet(EVENT_FLEET).unwrap();
        apply_source(
            &store,
            r#"version 2
resource "repo" { kind "vcs.repository" }
observer "repo" {
  resource "resource/repo"; provider "github.repository"; locator "acme/garden"
  field "issues"; field "comments"
}
agent "example.reader" { workspace "/tmp"; command "true" }
subscription "issues" { observer "observer/repo"; on "issues"; to "agent/example.reader"; delivery "message" }
subscription "comments" { observer "observer/repo"; on "comments"; to "agent/example.reader"; delivery "message" }"#,
            "compact-mode",
        );
        let revision = store.selected_desired_revision("observer/repo").unwrap().unwrap();
        let issue = |state: &str, title: &str, comments: &[u64]| serde_json::json!({
            "node_id": "I_orchid", "number": 1, "state": state, "title": title,
            "url": "https://github.com/acme/garden/issues/1",
            "comments": comments.len(),
            "recent_comments": comments.iter().map(|id| serde_json::json!({
                "kind": "comment", "id": id, "author": "fern", "at": format!("2026-10-30T10:0{id}:00Z"),
            })).collect::<Vec<_>>(),
        });
        let listing = |state: &str, title: &str, comments: &[u64]| serde_json::json!({"repository_id": 7, "issues": [issue(state, title, comments)]});
        let poll = |plugin: Arc<github_plugin_store::GithubPluginStore>, facts: Value, cursor: &str| {
            let reconciler = Reconciler::new(
                store.clone(), Arc::new(FakeRuntime::default()), "node".into(), Arc::new(Notify::new()),
            )
            .with_github_plugin(plugin.clone())
            .with_mirror_refill(true)
            .with_resource_provider(Arc::new(OnePoll { facts, cursor: cursor.to_owned() }));
            reconciler.observer_deadlines.lock().unwrap().insert(format!("observer/repo:{revision}"), 0);
            let cursor = cursor.to_owned();
            async move {
                reconciler.reconcile_resource_observers(&reconciler.store.desired_subjects().unwrap(), &[]).unwrap();
                tokio::time::timeout(Duration::from_secs(60), async {
                    while plugin.cursor("observer/repo").unwrap() != Some(Some(cursor.clone())) {
                        tokio::time::sleep(Duration::from_millis(20)).await;
                    }
                }).await.expect("the poll keeps its cursor");
            }
        };
        let item = "resource/repo/issue/1";
        let count = |kind: &str| store.claims_for(item, None).unwrap().into_iter()
            .filter(|claim| claim.kind == kind).count();
        let delivered = || store.messages(Some("agent/example.reader"), true).unwrap().len();
        let plugin = Arc::new(github_plugin_store::GithubPluginStore::memory());

        // The first look is a baseline, and the mirror fills from it.
        poll(plugin.clone(), listing("open", "Orchid", &[]), "c1").await;
        assert!(plugin.filled("resource/repo").unwrap());
        assert_eq!(delivered(), 0);

        // A comment is a delivery fact: it is delivered once and keeps a full snapshot.
        let snapshots = count("resource.observed");
        poll(plugin.clone(), listing("open", "Orchid", &[1]), "c2").await;
        assert_eq!(delivered(), 1);
        assert_eq!(count("resource.observed"), snapshots + 1, "a comment writes a snapshot");
        // An older poller raced this look, before receiving its event. Its global operation
        // and node-local payload must not cause another listing row or subscription delivery.
        let old = Store::open_memory("old-poller").unwrap();
        old.bind_fleet(EVENT_FLEET).unwrap();
        let subject = "github-event/repo/issue/1/comment/1";
        old.append_claim(&ClaimInput {
            subject: subject.into(), kind: fractal_schema::github_plugin::EVENT.into(),
            actor: None,
            fields: BTreeMap::from([
                ("version".into(), serde_json::json!(1)),
                ("item".into(), serde_json::json!(item)),
                ("event".into(), serde_json::json!("comment")),
                ("observer".into(), serde_json::json!("observer/old")),
                ("at".into(), serde_json::json!("2026-11-11T10:00:01Z")),
                ("detail".into(), serde_json::json!({"author": "fern"})),
            ]),
            evidence: Vec::new(), expected_subject: None,
            idempotency_key: Some(format!("github-event:{subject}")),
        }).unwrap();
        let exchange = old.export_replication_exchange_answering(
            EVENT_FLEET, &store.replication_inventory().unwrap(),
            &store.replication_signature_requests().unwrap(),
        ).unwrap();
        store.receive_replication_exchange(&old.origin, EVENT_FLEET, &exchange).unwrap();
        store.validate_replication_backlog().unwrap();
        store.project_replication_backlog().unwrap();
        assert_eq!(store.claims_for(subject, None).unwrap().len(), 2);
        assert_eq!(store.github_events("resource/repo", Some(1), 10).unwrap().len(), 1);
        assert_eq!(store.idempotency_conflicts(10).unwrap().0, 0);
        assert_eq!(delivered(), 1, "event provenance does not deliver mail");
        poll(plugin.clone(), listing("open", "Orchid", &[1]), "c3").await;
        assert_eq!(delivered(), 1, "a known comment is not delivered again");

        // A close and a new title are not delivery facts: the close is compact state and one
        // keyed event, and neither writes a snapshot.
        let snapshots = count("resource.observed");
        let states = count("vcs.item.state");
        // A suspended poll keeps the completed mirror position inside its private cursor.
        let checkpoint = serde_json::json!({"poll_started_ms": 1, "cursor": "c3"}).to_string();
        plugin.set_cursor("observer/repo", "resource/repo", Some(&checkpoint)).unwrap();
        poll(plugin.clone(), listing("closed", "Orchid, renamed", &[1]), "c4").await;
        assert!(plugin.filled("resource/repo").unwrap(), "a resumed poll keeps mirror continuity");
        assert_eq!(count("resource.observed"), snapshots, "a compact-only change writes no snapshot");
        assert_eq!(count("vcs.item.state"), states + 1);
        assert_eq!(store.latest_actual_value(item).unwrap().unwrap()["facts"]["state"], "closed");
        assert_eq!(store.claims_for("github-event/repo/issue/1/closed", None).unwrap().len(), 1);
        let after_close = delivered();
        // The same facts again: an unchanged look writes no snapshot and no state.
        let (snapshots, states) = (count("resource.observed"), count("vcs.item.state"));
        poll(plugin.clone(), listing("closed", "Orchid, renamed", &[1]), "c4b").await;
        assert_eq!((count("resource.observed"), count("vcs.item.state")), (snapshots, states), "an unchanged look records nothing");

        // A new title alone leaves the compact state as it was, but the issues subscription
        // delivers it: the message gets a state of its own rather than sharing the close's, and
        // the observer stays healthy (#4553).
        poll(plugin.clone(), listing("closed", "Orchid, renamed again", &[1]), "c4c").await;
        assert_eq!(delivered(), after_close + 1, "a new title is delivered");
        assert_eq!((count("resource.observed"), count("vcs.item.state")), (snapshots, states + 1));
        assert_eq!(store.latest_actual_value("observer/repo").unwrap().unwrap()["state"], "healthy");
        let after_close = delivered();

        // Polling moves to a member with no mirror. Its first look finds the title the graph
        // never recorded: that is a baseline, and nothing is delivered twice.
        poll(Arc::new(github_plugin_store::GithubPluginStore::memory()), listing("closed", "Orchid, renamed again", &[1]), "c5").await;
        assert_eq!(delivered(), after_close, "a move after compact-only changes delivers nothing twice");

        // A filled mirror that missed a look, as when its write failed after the graph write, is
        // not a look's prior: the look is compared with the graph.
        let spec = crate::graph::observer_spec(
            &store.desired_subjects_named(&["observer/repo".into()]).unwrap()[0].desired,
        ).unwrap();
        let facts = listing("closed", "Orchid, renamed again", &[1]);
        assert!(mirrored_prior(&store, &plugin, "node", &spec, &facts, Some("c4c")).is_some());
        assert!(mirrored_prior(&store, &plugin, "node", &spec, &facts, Some("c9")).is_none(), "behind the cursor");

        // The graph moves on while this mirror and its cursor stay at the earlier look, as when
        // the daemon stops between the graph write and the mirror write. The look from that
        // cursor sees a comment the graph already delivered: it is not delivered again.
        let comments = delivered();
        poll(Arc::new(github_plugin_store::GithubPluginStore::memory()), listing("closed", "Orchid, renamed again", &[1, 2]), "c6").await;
        assert_eq!(delivered(), comments + 1, "the second comment is delivered");
        poll(plugin.clone(), listing("closed", "Orchid, renamed again", &[1, 2]), "c7").await;
        assert_eq!(delivered(), comments + 1, "a mirror behind the graph delivers it nothing twice");
    }

    /// In compact mode a look that changes only facts outside the compact state, such as an
    /// issue's title or a pull request's per-check list, records nothing for an item no
    /// subscription delivers: its stored state compares equal to the new one (#4553).
    #[tokio::test]
    async fn compact_mode_records_no_state_for_an_undelivered_change_outside_it() {
        struct OnePoll {
            facts: Value,
            cursor: String,
        }
        impl ResourceProvider for OnePoll {
            fn observe(&self, _: ObservationRequest) -> std::pin::Pin<Box<
                dyn Future<Output = Result<crate::resource::ProviderObservation>> + Send + '_
            >> {
                Box::pin(async move { Ok(crate::resource::ProviderObservation {
                    facts: self.facts.clone(),
                    cursor: Some(self.cursor.clone()),
                    next_check_unix_ms: now_ms() + 300_000,
                }) })
            }
        }
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"version 2
resource "repo" { kind "vcs.repository" }
observer "repo" {
  resource "resource/repo"; provider "github.repository"; locator "acme/garden"
  field "issues"; field "pull_requests"; field "comments"
}
agent "example.reader" { workspace "/tmp"; command "true" }
subscription "comments" { observer "observer/repo"; on "comments"; to "agent/example.reader"; delivery "message" }"#,
            "compact-undelivered",
        );
        let revision = store.selected_desired_revision("observer/repo").unwrap().unwrap();
        let listing = |title: &str, checks: &[&str]| serde_json::json!({
            "repository_id": 7,
            "issues": [{
                "node_id": "I_fern", "number": 1, "state": "open", "title": title,
                "url": "https://github.com/acme/garden/issues/1",
            }],
            "pull_requests": [{
                "node_id": "PR_moss", "number": 2, "state": "open", "title": "Moss", "draft": false,
                "head": "a1b2c3", "url": "https://github.com/acme/garden/pull/2",
                "required_checks": {
                    "state": "pass", "source": "rollup",
                    "checks": checks.iter().map(|name| serde_json::json!({"name": name, "state": "pass"})).collect::<Vec<_>>(),
                },
            }],
        });
        let poll = |plugin: Arc<github_plugin_store::GithubPluginStore>, facts: Value, cursor: &str| {
            let reconciler = Reconciler::new(
                store.clone(), Arc::new(FakeRuntime::default()), "node".into(), Arc::new(Notify::new()),
            )
            .with_github_plugin(plugin.clone())
            .with_mirror_refill(true)
            .with_resource_provider(Arc::new(OnePoll { facts, cursor: cursor.to_owned() }));
            reconciler.observer_deadlines.lock().unwrap().insert(format!("observer/repo:{revision}"), 0);
            let cursor = cursor.to_owned();
            async move {
                reconciler.reconcile_resource_observers(&reconciler.store.desired_subjects().unwrap(), &[]).unwrap();
                // A bound for a loaded machine, not an expected duration.
                tokio::time::timeout(Duration::from_secs(60), async {
                    while plugin.cursor("observer/repo").unwrap() != Some(Some(cursor.clone())) {
                        tokio::time::sleep(Duration::from_millis(20)).await;
                    }
                }).await.expect("the poll keeps its cursor");
            }
        };
        let recorded = || ["resource/repo/issue/1", "resource/repo/pull-request/2"].map(|item| {
            store.claims_for(item, None).unwrap().into_iter()
                .filter(|claim| matches!(claim.kind.as_str(), "resource.observed" | "vcs.item.state"))
                .count()
        });
        let plugin = Arc::new(github_plugin_store::GithubPluginStore::memory());

        poll(plugin.clone(), listing("Fern", &["lint"]), "c1").await;
        let baseline = recorded();
        assert!(baseline.iter().all(|claims| *claims > 0), "{baseline:?}");

        // A new title and a new passing check: neither item's compact state moved.
        poll(plugin.clone(), listing("Fern, renamed", &["lint", "fmt"]), "c2").await;
        assert_eq!(recorded(), baseline, "a change outside the compact state records nothing");
        assert!(store.messages(Some("agent/example.reader"), true).unwrap().is_empty());
        assert_eq!(plugin.item("resource/repo", 1).unwrap().unwrap()["facts"]["title"], "Fern, renamed");
    }

    /// The observer `repo` on acme/garden, a subscription so it polls, and its revision.
    /// The store for this file's multi-threaded look tests. A look task writes while the test
    /// reads, and a shared-cache memory store fails one of them at once with SQLITE_LOCKED, which
    /// no busy timeout waits out (#4720), so it is file-backed. The tempdir comes first so a caller's
    /// binding drops it after the store.
    fn one_look_fixture(source: &str) -> (tempfile::TempDir, Arc<Store>, String) {
        let root = tempfile::tempdir().unwrap();
        let store = Arc::new(Store::open(&root.path().join("graph.db"), "node").unwrap());
        apply_source(
            &store,
            r#"version 2
resource "repo" { kind "vcs.repository" }
observer "repo" {
  resource "resource/repo"; provider "github.repository"; locator "acme/garden"
  field "issues"
}
agent "example.reader" { workspace "/tmp"; command "true" }
subscription "issues" { observer "observer/repo"; on "issues"; to "agent/example.reader"; delivery "message" }"#,
            source,
        );
        let revision = store.selected_desired_revision("observer/repo").unwrap().unwrap();
        (root, store, revision)
    }

    #[test]
    fn the_look_fixture_store_takes_a_write_while_a_reader_holds_a_snapshot() {
        let (_root, store, _) = one_look_fixture("reader-writer");
        store.read_snapshot(|_| {
            assert!(store.latest_claim("agent/reader-writer", None)?.is_none());
            // Join the other thread's commit while this thread still holds its read snapshot.
            std::thread::scope(|scope| scope.spawn(|| {
                store.append_claim(&ClaimInput {
                    subject: "agent/reader-writer".into(),
                    kind: "runtime.observed".into(),
                    actor: Some("agent/reader-writer".into()),
                    fields: BTreeMap::from([("status".into(), Value::String("running".into()))]),
                    evidence: Vec::new(),
                    expected_subject: None,
                    idempotency_key: None,
                })
            }).join().unwrap())?;
            assert!(store.latest_claim("agent/reader-writer", None)?.is_none());
            Ok(())
        }).unwrap();
        assert!(store.latest_claim("agent/reader-writer", None).unwrap().is_some());
    }

    /// One look's listing: issue 1 titled `title`, and the cursor `cursor`.
    fn one_look(title: &str, cursor: &str) -> crate::resource::ProviderObservation {
        crate::resource::ProviderObservation {
            facts: serde_json::json!({"repository_id": 7, "issues": [{
                "node_id": "I_fern", "number": 1, "state": "open", "title": title,
                "url": "https://github.com/acme/garden/issues/1",
            }]}),
            cursor: Some(cursor.to_owned()),
            next_check_unix_ms: now_ms() + 300_000,
        }
    }

    /// Retire every arm of `observer/repo` and arm a new one, due now, as a refresh or a changed
    /// declaration does.
    fn rearm_repo(reconciler: &Reconciler<FakeRuntime>, revision: &str) {
        reconciler.armed_observers.lock().unwrap().retain(|operation| !operation.starts_with("observer/repo:"));
        reconciler.observer_deadlines.lock().unwrap().insert(format!("observer/repo:{revision}"), 0);
        reconciler.reconcile_resource_observers(&reconciler.store.desired_subjects().unwrap(), &[]).unwrap();
    }

    async fn until(what: &str, mut done: impl FnMut() -> bool) {
        // A bound for a loaded machine, not an expected duration.
        tokio::time::timeout(Duration::from_secs(60), async {
            while !done() { tokio::time::sleep(Duration::from_millis(10)).await; }
        }).await.unwrap_or_else(|_| panic!("timed out waiting until {what}"));
    }

    /// A look that recorded and kept its cursor, and was retired before it published it, as a
    /// refresh or a scheduled arm retires the arm before it, is the observer's position: the
    /// arm armed meanwhile waits for that look, then reads on from its cursor. Reading from the
    /// cursor before, it found the poller's mirror ahead of it and recorded a full snapshot.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn an_arm_armed_during_a_look_reads_on_from_the_cursor_that_look_kept() {
        struct Counter { asked: Arc<Mutex<Vec<Option<String>>>> }
        impl ResourceProvider for Counter {
            fn observe(&self, request: ObservationRequest) -> std::pin::Pin<Box<
                dyn Future<Output = Result<crate::resource::ProviderObservation>> + Send + '_
            >> {
                let mut asked = self.asked.lock().unwrap();
                asked.push(request.cursor);
                let n = asked.len();
                Box::pin(async move { Ok(one_look(&format!("title {n}"), &format!("c{n}"))) })
            }
        }
        /// Holds the second look that keeps a cursor until the test lets it go.
        struct HoldSecondKept {
            kept: AtomicUsize,
            reached: Mutex<std::sync::mpsc::Sender<()>>,
            release: Mutex<std::sync::mpsc::Receiver<()>>,
        }
        impl FaultInjection for HoldSecondKept {
            fn fault(&self, scope: &str, _subject: &str) -> Option<String> {
                if scope == "observer-cursor-kept" && self.kept.fetch_add(1, Ordering::SeqCst) == 1 {
                    self.reached.lock().unwrap().send(()).unwrap();
                    self.release.lock().unwrap().recv().unwrap();
                }
                None
            }
        }
        let (_root, store, revision) = one_look_fixture("one-look");
        let asked = Arc::new(Mutex::new(Vec::new()));
        let (reached_tx, reached) = std::sync::mpsc::channel();
        let (release, release_rx) = std::sync::mpsc::channel();
        let reconciler = Reconciler::new(
            store.clone(), Arc::new(FakeRuntime::default()), "node".into(), Arc::new(Notify::new()),
        )
        .with_resource_provider(Arc::new(Counter { asked: asked.clone() }))
        .with_fault_injection(Arc::new(HoldSecondKept {
            kept: AtomicUsize::new(0),
            reached: Mutex::new(reached_tx),
            release: Mutex::new(release_rx),
        }));
        let key = format!("observer/repo:{revision}");
        let published = || reconciler.observer_cursors.lock().unwrap().get(&key).cloned().flatten();

        // The first look keeps c1.
        rearm_repo(&reconciler, &revision);
        until("the first look publishes c1", || published().as_deref() == Some("c1")).await;

        // The second look records and keeps c2, and is held there.
        rearm_repo(&reconciler, &revision);
        tokio::task::spawn_blocking(move || reached.recv().unwrap()).await.unwrap();
        // An arm armed now retires it, and is due at once.
        rearm_repo(&reconciler, &revision);
        tokio::time::sleep(Duration::from_millis(200)).await;
        assert_eq!(asked.lock().unwrap().len(), 2, "the new arm waits for the look in flight");
        release.send(()).unwrap();

        until("the third look", || asked.lock().unwrap().len() == 3).await;
        assert_eq!(*asked.lock().unwrap(), [None, Some("c1".into()), Some("c2".into())]);
        until("the third look publishes c3", || published().as_deref() == Some("c3")).await;
    }

    /// A look holds its observer at most `look_limit`: a mirror refill that never answers, and
    /// then a look that never answers, each end at the limit, and the next look still runs.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn a_look_that_never_answers_frees_its_observer_at_the_limit() {
        struct Stalls { asked: Arc<Mutex<Vec<Option<String>>>> }
        impl ResourceProvider for Stalls {
            fn observe(&self, request: ObservationRequest) -> std::pin::Pin<Box<
                dyn Future<Output = Result<crate::resource::ProviderObservation>> + Send + '_
            >> {
                let mut asked = self.asked.lock().unwrap();
                asked.push(request.cursor);
                // The first look answers; the refill after it and the next look never do.
                match asked.len() {
                    1 => Box::pin(async { Ok(one_look("first", "c1")) }),
                    2 | 3 => Box::pin(std::future::pending()),
                    _ => Box::pin(async { Ok(one_look("last", "c2")) }),
                }
            }
        }
        let (_root, store, revision) = one_look_fixture("one-look-limit");
        let asked = Arc::new(Mutex::new(Vec::new()));
        let mut reconciler = Reconciler::new(
            store.clone(), Arc::new(FakeRuntime::default()), "node".into(), Arc::new(Notify::new()),
        )
        .with_mirror_refill(true)
        .with_resource_provider(Arc::new(Stalls { asked: asked.clone() }));
        reconciler.look_limit = Duration::from_millis(300);
        let key = format!("observer/repo:{revision}");
        let published = || reconciler.observer_cursors.lock().unwrap().get(&key).cloned().flatten();

        // The first look records; its refill stalls and ends at the limit, and the look still
        // keeps c1.
        rearm_repo(&reconciler, &revision);
        until("the first look publishes c1 past its stalled refill", || published().as_deref() == Some("c1")).await;
        assert_eq!(asked.lock().unwrap().len(), 2, "the refill asked once");

        // The next look stalls and ends at the limit as a failure.
        rearm_repo(&reconciler, &revision);
        until("the stalled look ends as a failure", || {
            reconciler.store.latest_actual_value("observer/repo").unwrap().is_some_and(|actual| {
                actual["reason"].as_str().is_some_and(|reason| reason.contains("ran past its"))
            })
        }).await;

        // The observer is free: an arm armed now looks again.
        rearm_repo(&reconciler, &revision);
        until("the look after the stalled one", || published().as_deref() == Some("c2")).await;
        assert_eq!(*asked.lock().unwrap(), [None, None, Some("c1".into()), Some("c1".into())]);
    }

    /// A mirror refilled from GitHub keeps the comments the graph recorded on each item, which
    /// a fresh listing does not reach: the next look at an item it filled hands out no event
    /// for an old comment, and a new comment is still one event (#4549).
    #[tokio::test]
    async fn a_refilled_mirror_hands_out_no_event_for_an_old_comment() {
        /// Answers a look from a cursor with `look`, and the refill's look from none with
        /// `refill`, a listing that names no comment.
        struct Answers {
            look: Value,
            refill: Value,
            cursor: String,
        }
        impl ResourceProvider for Answers {
            fn observe(&self, request: ObservationRequest) -> std::pin::Pin<Box<
                dyn Future<Output = Result<crate::resource::ProviderObservation>> + Send + '_
            >> {
                let facts = if request.cursor.is_some() { self.look.clone() } else { self.refill.clone() };
                Box::pin(async move { Ok(crate::resource::ProviderObservation {
                    facts,
                    cursor: Some(self.cursor.clone()),
                    next_check_unix_ms: now_ms() + 300_000,
                }) })
            }
        }
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"version 2
resource "repo" { kind "vcs.repository" }
observer "repo" {
  resource "resource/repo"; provider "github.repository"; locator "acme/garden"
  field "issues"; field "comments"
}
agent "example.reader" { workspace "/tmp"; command "true" }
subscription "comments" { observer "observer/repo"; on "comments"; to "agent/example.reader"; delivery "message" }"#,
            "refill-comments",
        );
        let revision = store.selected_desired_revision("observer/repo").unwrap().unwrap();
        let issue = |number: u64, title: &str, comments: &[u64]| {
            let mut issue = serde_json::json!({
                "node_id": format!("I_moss{number}"), "number": number, "state": "open", "title": title,
                "url": format!("https://github.com/acme/garden/issues/{number}"),
            });
            if !comments.is_empty() {
                issue["comments"] = Value::from(comments.len());
                issue["recent_comments"] = comments.iter().map(|id| serde_json::json!({
                    "kind": "comment", "id": id, "author": "fern", "at": format!("2026-10-2{id}T10:00:00Z"),
                })).collect();
            }
            issue
        };
        let listing = |issues: Vec<Value>| serde_json::json!({"repository_id": 7, "issues": issues});
        let poll = |plugin: Arc<github_plugin_store::GithubPluginStore>, look: Value, refill: Value, cursor: &str| {
            let reconciler = Reconciler::new(
                store.clone(), Arc::new(FakeRuntime::default()), "node".into(), Arc::new(Notify::new()),
            )
            .with_github_plugin(plugin.clone())
            .with_mirror_refill(true)
            .with_resource_provider(Arc::new(Answers { look, refill, cursor: cursor.to_owned() }));
            reconciler.observer_deadlines.lock().unwrap().insert(format!("observer/repo:{revision}"), 0);
            let cursor = cursor.to_owned();
            async move {
                reconciler.reconcile_resource_observers(&reconciler.store.desired_subjects().unwrap(), &[]).unwrap();
                // A bound for a loaded machine, not an expected duration.
                tokio::time::timeout(Duration::from_secs(60), async {
                    while plugin.cursor("observer/repo").unwrap() != Some(Some(cursor.clone())) {
                        tokio::time::sleep(Duration::from_millis(20)).await;
                    }
                }).await.expect("the poll keeps its cursor");
            }
        };
        let comment_event = |id: u64| store.claims_for(&format!("github-event/repo/issue/2/comment/{id}"), None).unwrap().len();

        // Issue 2's comment 3 is recorded in the graph, by a poller whose mirror is then lost.
        let first = Arc::new(github_plugin_store::GithubPluginStore::memory());
        let both = listing(vec![issue(1, "Fern", &[]), issue(2, "Moss", &[3])]);
        poll(first.clone(), both.clone(), both, "c1").await;
        let commented = listing(vec![issue(2, "Moss", &[3, 4])]);
        poll(first, commented.clone(), commented, "c2").await;
        assert_eq!(comment_event(4), 1, "a new comment is one event");

        // A poller with no mirror looks at issue 1 alone, then refills from a listing that names
        // neither issue's comments.
        let plugin = Arc::new(github_plugin_store::GithubPluginStore::memory());
        let bare = listing(vec![issue(1, "Fern", &[]), issue(2, "Moss", &[])]);
        poll(plugin.clone(), listing(vec![issue(1, "Fern, renamed", &[])]), bare.clone(), "c3").await;
        assert!(plugin.filled("resource/repo").unwrap());

        // Its next look sees issue 2 with the comments it already had: none is an event.
        poll(plugin.clone(), listing(vec![issue(2, "Moss, renamed", &[3, 4])]), bare.clone(), "c4").await;
        let events = plugin.events("resource/repo", Some(2), 10).unwrap();
        assert!(events.is_empty(), "an old comment is no event: {events:?}");
        assert_eq!((comment_event(3), comment_event(4)), (0, 1));

        // A comment written after the refill is one event.
        poll(plugin.clone(), listing(vec![issue(2, "Moss, renamed", &[3, 4, 5])]), bare, "c5").await;
        let events = plugin.events("resource/repo", Some(2), 10).unwrap();
        assert_eq!(events.len(), 1, "{events:?}");
        assert_eq!(events[0]["subject"], "github-event/repo/issue/2/comment/5");
        assert_eq!(comment_event(5), 1);
    }

    /// Polling moves to a member without the plugin database, between two polls by the real
    /// repository provider. The issue closed and the comment written in the gap are each
    /// delivered once, and the comment from before the gap is not delivered again: the new
    /// poller reads on from how far the observer's claim says it had read.
    #[tokio::test]
    async fn a_closure_and_a_comment_between_two_pollers_are_each_delivered_once() {
        use crate::resource::test_github::{FakeGithub, age_pull_request_check, observe};
        /// The real repository provider, against the test GitHub at its base. Each poll
        /// revalidates instead of reusing this process's cached response, as polls minutes apart do.
        struct Real(String);
        impl ResourceProvider for Real {
            fn observe(&self, mut request: ObservationRequest) -> std::pin::Pin<Box<
                dyn Future<Output = Result<crate::resource::ProviderObservation>> + Send + '_
            >> {
                request.every_ms = Some(0);
                Box::pin(observe(request, &self.0))
            }
        }
        let (github, base) = FakeGithub::start().await;
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"version 2
resource "repo" { kind "vcs.repository" }
observer "repo" {
  resource "resource/repo"; provider "github.repository"; locator "acme/garden"
  field "issues"; field "comments"
}
agent "example.reader" { workspace "/tmp"; command "true" }
subscription "issues" { observer "observer/repo"; on "issues"; to "agent/example.reader"; delivery "message" }
subscription "comments" { observer "observer/repo"; on "comments"; to "agent/example.reader"; delivery "message" }"#,
            "two-pollers",
        );
        let revision = store.selected_desired_revision("observer/repo").unwrap().unwrap();
        // An older build read the repository up to the tenth: its claim carries that position.
        store.append_claim(&ClaimInput {
            subject: "observer/repo".into(),
            kind: "observer.observed".into(),
            actor: None,
            fields: BTreeMap::from([
                ("status".into(), Value::String("healthy".into())),
                ("revision".into(), Value::String(revision.clone())),
                ("cursor".into(), Value::String(serde_json::json!({
                    "items_since": "2026-09-10T00:00:00Z", "comments_since": "2026-09-10T00:00:00Z",
                }).to_string())),
                ("changed".into(), Value::Bool(true)),
            ]),
            evidence: Vec::new(),
            expected_subject: None,
            idempotency_key: None,
        }).unwrap();

        let issue = |state: &str, updated_at: &str, comments: u64| serde_json::json!({
            "number": 1, "node_id": "I_orchid", "title": "Orchid", "state": state,
            "html_url": "https://github.com/acme/garden/issues/1", "user": {"login": "fern"},
            "created_at": "2026-09-01T00:00:00Z", "updated_at": updated_at,
            "comments": comments, "body": "", "reactions": {"total_count": 0, "+1": 0},
        });
        let comment = |id: u64, at: &str, body: &str| serde_json::json!({
            "id": id, "issue_url": "https://api.github.com/repos/acme/garden/issues/1",
            "html_url": format!("https://github.com/acme/garden/issues/1#issuecomment-{id}"),
            "user": {"login": "fern"}, "body": body, "created_at": at, "updated_at": at,
        });
        let since = |at: &str| (
            format!("/repos/acme/garden/issues?state=all&sort=updated&direction=asc&since={at}&per_page=100"),
            format!("/repos/acme/garden/issues/comments?sort=updated&direction=asc&since={at}&per_page=100"),
        );
        let node = |state: &str| serde_json::json!([{"id": "I_orchid", "state": state, "number": 1,
            "url": "https://github.com/acme/garden/issues/1"}]);
        github.route("/repos/acme/garden", serde_json::json!({"id": 7}));
        github.open_pull_requests(serde_json::json!([]));
        github.resolved_nodes(node("OPEN"));

        // One poll by a member whose reconciler keeps cursors in `plugin`, once it has recorded.
        let poll = |plugin: Arc<github_plugin_store::GithubPluginStore>| {
            let reconciler = Reconciler::new(
                store.clone(), Arc::new(FakeRuntime::default()), "node".into(), Arc::new(Notify::new()),
            )
            .with_github_plugin(plugin)
            .with_resource_provider(Arc::new(Real(base.clone())));
            let key = format!("observer/repo:{revision}");
            reconciler.observer_deadlines.lock().unwrap().insert(key.clone(), 0);
            // Each poll asks GraphQL again, rather than reusing this host's last answer.
            if !github.graphql_requests.lock().is_empty() {
                age_pull_request_check(&base, Duration::from_secs(3600));
            }
            async move {
                reconciler.reconcile_resource_observers(&reconciler.store.desired_subjects().unwrap(), &[]).unwrap();
                // A bound for a loaded machine, not an expected duration.
                tokio::time::timeout(Duration::from_secs(60), async {
                    while reconciler.observer_deadlines.lock().unwrap().get(&key).is_none_or(|deadline| *deadline == 0) {
                        tokio::time::sleep(Duration::from_millis(20)).await;
                    }
                }).await.expect("the poll records");
            }
        };
        // Each delivery: the subscription, the item's state, and the item's last comment.
        let delivered = || {
            let mut delivered = store.messages(Some("agent/example.reader"), true).unwrap().into_iter()
                .flat_map(|message| {
                    let subscription = message.tags.iter()
                        .find_map(|tag| tag.strip_prefix("subscription/")).unwrap_or_default().to_owned();
                    let content: Value = serde_json::from_str(&message.content).unwrap();
                    content["items"].as_array().cloned().unwrap_or_default().into_iter()
                        .map(move |item| (
                            subscription.clone(),
                            item["facts"]["state"].as_str().unwrap_or_default().to_owned(),
                            item["facts"]["last_comment"]["id"].as_u64(),
                        ))
                })
                .collect::<Vec<_>>();
            delivered.sort();
            delivered
        };
        let delivery = |subscription: &str, state: &str, comment: u64| (subscription.to_owned(), state.to_owned(), Some(comment));

        // Member A: the first poll records the baseline, which wakes nobody.
        let (issues, comments) = since("2026-09-09T23:59:59Z");
        // Resuming from the claim's bare position, a poll also reads the open listing once.
        github.route("/repos/acme/garden/issues?state=open&per_page=100",
            serde_json::json!([issue("open", "2026-09-10T00:00:00Z", 0)]));
        github.route(&issues, serde_json::json!([issue("open", "2026-09-10T00:00:00Z", 0)]));
        github.route(&comments, serde_json::json!([]));
        let member_a = Arc::new(github_plugin_store::GithubPluginStore::memory());
        poll(member_a.clone()).await;
        assert_eq!(delivered(), [], "a baseline delivers nothing");

        // Then a comment before the gap, delivered once.
        github.route(&issues, serde_json::json!([issue("open", "2026-09-11T00:00:00Z", 1)]));
        github.route(&comments, serde_json::json!([comment(91, "2026-09-11T00:00:00Z", "before the gap")]));
        poll(member_a.clone()).await;
        let before = vec![delivery("comments", "open", 91), delivery("issues", "open", 91)];
        assert_eq!(delivered(), before);

        // In the gap the issue closes and a second comment lands. The open listing no longer
        // names it, so only reading on from the claim's position shows the closure.
        let (issues, comments) = since("2026-09-10T23:59:59Z");
        github.route("/repos/acme/garden/issues?state=open&per_page=100", serde_json::json!([]));
        github.route(&issues, serde_json::json!([issue("closed", "2026-09-12T00:00:00Z", 2)]));
        github.route(&comments, serde_json::json!([
            comment(91, "2026-09-11T00:00:00Z", "before the gap"),
            comment(92, "2026-09-12T00:00:00Z", "in the gap"),
        ]));
        github.resolved_nodes(node("CLOSED"));

        // Member B never polled this observer: it reads on from the claim.
        let member_b = Arc::new(github_plugin_store::GithubPluginStore::memory());
        poll(member_b.clone()).await;
        let mut after = before.clone();
        after.extend([delivery("comments", "closed", 92), delivery("issues", "closed", 92)]);
        after.sort();
        assert_eq!(delivered(), after, "the closure and the gap's comment, once each, and nothing older");
        assert_eq!(
            store.latest_actual_value("resource/repo/issue/1").unwrap().unwrap()["facts"]["state"],
            "closed",
        );
        // Polling again delivers nothing more.
        poll(member_b).await;
        assert_eq!(delivered(), after);
    }

    /// A plugin database that fails is the observer's failure, never hidden. A read that fails
    /// leaves no arm behind, so the observer polls once the database reads again. A cursor the
    /// database does not keep holds the observer degraded, and GitHub is not asked again, until
    /// the database takes it, whichever arm polls next. A later failure records its own receipt,
    /// even when a refresh met it and its first write failed.
    #[tokio::test(start_paused = true)]
    async fn a_failing_plugin_database_degrades_the_observer_until_it_recovers() {
        /// Fails the next observer.state receipt once `armed` is set.
        struct FailReceiptOnce(Arc<std::sync::atomic::AtomicBool>);
        impl FaultInjection for FailReceiptOnce {
            fn fault(&self, scope: &str, _subject: &str) -> Option<String> {
                (scope == "observer-receipt-write" && self.0.swap(false, Ordering::SeqCst))
                    .then(|| "injected observer.state write failure".into())
            }
        }
        struct Polls {
            asked: Arc<Mutex<Vec<Option<String>>>>,
            cursor: Arc<Mutex<&'static str>>,
        }
        impl ResourceProvider for Polls {
            fn observe(&self, request: ObservationRequest) -> std::pin::Pin<Box<
                dyn Future<Output = Result<crate::resource::ProviderObservation>> + Send + '_
            >> {
                self.asked.lock().unwrap().push(request.cursor);
                let cursor = *self.cursor.lock().unwrap();
                Box::pin(async move { Ok(crate::resource::ProviderObservation {
                    facts: serde_json::json!({"repository_id": 7, "issues": []}),
                    cursor: Some(cursor.into()),
                    next_check_unix_ms: now_ms() + 300_000,
                }) })
            }
        }
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"version 2
resource "repo" { kind "vcs.repository" }
observer "repo" {
  resource "resource/repo"; provider "github.repository"; locator "acme/garden"
  field "issues"
}"#,
            "cursor-failure",
        );
        let revision = store.selected_desired_revision("observer/repo").unwrap().unwrap();
        let plugin = Arc::new(github_plugin_store::GithubPluginStore::memory());
        let asked = Arc::new(Mutex::new(Vec::new()));
        let cursor = Arc::new(Mutex::new("c1"));
        let reconciler = Reconciler::new(
            store.clone(), Arc::new(FakeRuntime::default()), "node".into(), Arc::new(Notify::new()),
        )
        .with_github_plugin(plugin.clone())
        .with_resource_provider(Arc::new(Polls { asked: asked.clone(), cursor: cursor.clone() }));
        let fail_receipt = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let reconciler = reconciler.with_fault_injection(Arc::new(FailReceiptOnce(fail_receipt.clone())));
        let pass = || {
            reconciler.observer_deadlines.lock().unwrap().insert(format!("observer/repo:{revision}"), 0);
            reconciler.reconcile_resource_observers(&store.desired_subjects().unwrap(), &[]).unwrap();
        };
        let state = || store.latest_claim("observer/repo", Some("observer.state")).unwrap()
            .map(|claim| (claim.id, claim.body["fields"]["state"].as_str().unwrap_or_default().to_owned()));
        async fn until(what: &str, mut done: impl FnMut() -> bool) {
            tokio::time::timeout(Duration::from_secs(3_600), async {
                while !done() { tokio::time::sleep(Duration::from_millis(50)).await; }
            }).await.unwrap_or_else(|_| panic!("{what}"));
        }

        plugin.fail_reads(true);
        pass();
        tokio::time::sleep(Duration::from_secs(1)).await;
        assert!(asked.lock().unwrap().is_empty(), "no poll without the cursor it would start from");
        plugin.fail_reads(false);
        pass();
        until("the observer polls once the database reads again", || asked.lock().unwrap().len() == 1).await;
        until("the cursor is kept", || plugin.cursor("observer/repo").unwrap() == Some(Some("c1".into()))).await;

        plugin.refuse_writes(true);
        *cursor.lock().unwrap() = "c2";
        pass();
        until("an unkept cursor degrades the observer", || state().is_some_and(|(_, state)| state == "degraded")).await;
        let (first, _) = state().unwrap();
        let fields = store.latest_claim("observer/repo", Some("observer.state")).unwrap().unwrap().body["fields"].clone();
        assert_eq!(fields["error_code"], "github-plugin-database", "{fields}");
        let polls = asked.lock().unwrap().len();
        tokio::time::sleep(Duration::from_secs(600)).await;
        assert_eq!(asked.lock().unwrap().len(), polls, "GitHub is not asked again until the cursor is kept");
        assert_eq!(state().unwrap(), (first.clone(), "degraded".into()));

        plugin.refuse_writes(false);
        until("the database takes the cursor", || plugin.cursor("observer/repo").unwrap() == Some(Some("c2".into()))).await;
        pass();
        until("the next poll continues from it", || asked.lock().unwrap().last() == Some(&Some("c2".into()))).await;
        until("the observer is healthy again", || state().is_some_and(|(_, state)| state == "healthy")).await;

        // A refresh meets the next failure, and its degraded receipt fails to write once.
        let healthy = state().unwrap().0;
        plugin.refuse_writes(true);
        fail_receipt.store(true, Ordering::SeqCst);
        *cursor.lock().unwrap() = "c3";
        store.append_claim(&ClaimInput {
            subject: "observer/repo".into(),
            kind: "observer.refresh-requested".into(),
            actor: None,
            fields: BTreeMap::from([
                ("attempt".into(), Value::String("manual".into())),
                ("revision".into(), Value::String(revision.clone())),
            ]),
            evidence: Vec::new(),
            expected_subject: None,
            idempotency_key: None,
        }).unwrap();
        let polls = asked.lock().unwrap().len();
        pass();
        until("the refresh polls", || asked.lock().unwrap().len() == polls + 1).await;
        until("the receipt write was refused", || !fail_receipt.load(Ordering::SeqCst)).await;
        assert_eq!(state().unwrap().0, healthy, "the failed receipt wrote nothing");
        pass();
        until("a later failure degrades the observer again", || state().is_some_and(|(_, state)| state == "degraded")).await;
        assert_ne!(state().unwrap().0, first, "a later failure records its own receipt");
        tokio::time::sleep(Duration::from_secs(600)).await;
        pass();
        tokio::time::sleep(Duration::from_secs(600)).await;
        assert_eq!(asked.lock().unwrap().len(), polls + 1, "no arm asks GitHub until the cursor is kept");
        plugin.refuse_writes(false);
        until("the database takes the refresh's cursor", || plugin.cursor("observer/repo").unwrap() == Some(Some("c3".into()))).await;
        pass();
        until("the next poll continues from it", || asked.lock().unwrap().last() == Some(&Some("c3".into()))).await;
    }

    /// An intake run revised onto its repository's standing observer keeps its subscriptions,
    /// and the standing observer takes over the intake observer's resource and cursor: what the
    /// intake already delivered is not delivered again, and what changed afterwards is delivered
    /// once. Cancelling the run stops only its own subscriptions, and the standing observer stops
    /// when nothing uses it; declared again, it keeps the resource.
    #[test]
    fn an_intake_revised_onto_the_standing_observer_delivers_each_item_once() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(&store, REDELIVERY_REVIEW_SOURCE, "review-mission");
        let intake = |observer: &str, own: &str| {
            format!(
                r#"version 2
resource "github/acme/old" {{ kind "vcs.repository" }}
resource "retired" {{ kind "human.review" }}
mission "intake" state="ready" {{
  goal "Review every new pull request head and triage every new issue."
  {own}
  subscription "reviews" {{
    observer "{observer}"; on "pull_requests"
    delivery "mission" {{ mission "review"; resource "source"; workspace "/tmp/st3-reviews" }}
  }}
  subscription "triage" {{
    observer "{observer}"; on "issues"
    delivery "mission" {{ mission "review"; resource "source"; workspace "/tmp/st3-triage" }}
  }}
  step "retire" {{
    agentless
    gate "retired" {{ field "retired" "resource/retired" "is" "true" }}
  }}
}}"#
            )
        };
        apply_source(
            &store,
            &intake(
                "observer/repository",
                r#"observer "repository" {
    resource "resource/github/acme/old"; provider "github.repository"; locator "Acme/Garden"
    field "pull_requests"; field "issues"
  }"#,
            ),
            "intake-first",
        );
        let first = store.mission_spec("intake", None).unwrap().unwrap();
        let standing = "observer/github/acme/garden";
        apply_source(&store, &intake(standing, ""), "intake-second");
        let second = store.mission_spec("intake", None).unwrap().unwrap();
        let run = store
            .create_mission_run(&crate::model::MissionRunRequest {
                mission: first.id,
                revision: Some(first.revision),
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: Some("run".into()),
                inputs: BTreeMap::new(),
                idempotency_key: "intake-run".into(),
            })
            .unwrap();
        // The poll loop keeps each cursor in the plugin database; `observe` stands in for it.
        let plugin = Arc::new(github_plugin_store::GithubPluginStore::memory());
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        )
        .with_github_plugin(plugin.clone());
        for _ in 0..3 {
            reconciler.reconcile_once().unwrap();
        }
        let own = format!("observer/{}/repository", run.id);
        let resource = "resource/github/acme/old";
        let reviews = format!("subscription/{}/reviews", run.id);
        let triage = format!("subscription/{}/triage", run.id);
        let declared = |subject: &str| {
            store
                .desired_subjects_named(&[subject.to_owned()])
                .unwrap()
                .into_iter()
                .next()
        };
        let observer = |subject: &str| {
            declared(subject).and_then(|item| crate::graph::observer_spec(&item.desired))
        };
        let subscription = |subject: &str| {
            declared(subject).and_then(|item| crate::graph::subscription_spec(&item.desired))
        };
        let observe = |observer_subject: &str, cursor: &str, pulls: Value, issues: Value| {
            let desired = store.desired_subjects().unwrap();
            let resources = desired
                .iter()
                .filter_map(|item| {
                    let spec = crate::graph::observer_spec(&item.desired)?;
                    (!spec.stopped).then(|| (item.subject.clone(), spec.resource))
                })
                .collect::<HashMap<_, _>>();
            let subscriptions = desired
                .iter()
                .filter_map(|item| {
                    let spec = crate::graph::subscription_spec(&item.desired)?;
                    (!spec.stopped
                        && resources.get(&spec.observer).map(String::as_str) == Some(resource))
                    .then(|| (item.subject.clone(), spec))
                })
                .collect::<Vec<_>>();
            store.record_resource_observation(observer_subject, &store.selected_desired_revision(observer_subject).unwrap().unwrap(), None, resource, Some(cursor), &serde_json::json!({"repository_id": 41, "pull_requests": pulls, "issues": issues}), now_ms() + 60_000, &subscriptions, None)
                .unwrap();
            plugin.set_cursor(observer_subject, resource, Some(cursor)).unwrap();
        };
        let requested = |subscription: &str| {
            store
                .claims_for(subscription, Some("subscription.mission-requested"))
                .unwrap()
                .into_iter()
                .map(|claim| {
                    claim.body["fields"]["resource"]
                        .as_str()
                        .unwrap()
                        .rsplit('/')
                        .next()
                        .unwrap()
                        .parse::<u64>()
                        .unwrap()
                })
                .collect::<Vec<_>>()
        };
        let pull = |number: u64, head: char| serde_json::json!({"number": number, "head": head.to_string().repeat(40), "state": "open", "draft": false});
        let issue = |number: u64| serde_json::json!({"number": number, "state": "open"});

        // The intake's own observer: a baseline, then a new head and a new issue.
        assert!(observer(&own).is_some_and(|spec| !spec.stopped));
        observe(
            &own,
            "c1",
            serde_json::json!([pull(1, 'a')]),
            serde_json::json!([issue(2)]),
        );
        observe(
            &own,
            "c2",
            serde_json::json!([pull(1, 'b')]),
            serde_json::json!([issue(3)]),
        );
        assert_eq!(requested(&reviews), [1]);
        assert_eq!(requested(&triage), [3]);

        // The revision moves both subscriptions onto the standing observer, which takes the
        // intake observer's resource; the intake observer stops.
        store
            .adopt_mission_revision(
                &run.id,
                &second,
                "person/test",
                "intake reads the standing observer",
                "intake-move",
            )
            .unwrap();
        for _ in 0..2 {
            reconciler.reconcile_once().unwrap();
        }
        let moved = observer(standing).expect("the revision declares the standing observer");
        assert!(!moved.stopped);
        assert_eq!(moved.resource, resource);
        assert!(declared(standing).unwrap().owner_run.is_none());
        assert!(observer(&own).is_none_or(|spec| spec.stopped));
        for subject in [&reviews, &triage] {
            let spec = subscription(subject).unwrap();
            assert!(!spec.stopped, "{subject} keeps running");
            assert_eq!(spec.observer, standing);
        }
        assert_eq!(
            reconciler
                .inherited_observer_cursor(resource, standing)
                .unwrap()
                .as_deref(),
            Some("c2"),
            "the standing observer starts where the intake observer left off"
        );

        // The standing observer sees what the intake observer saw, and what changed since.
        observe(
            standing,
            "c3",
            serde_json::json!([pull(1, 'b'), pull(4, 'c')]),
            serde_json::json!([issue(3), issue(5)]),
        );
        observe(
            standing,
            "c4",
            serde_json::json!([pull(1, 'd')]),
            serde_json::json!([]),
        );
        observe(
            standing,
            "c4",
            serde_json::json!([pull(1, 'd')]),
            serde_json::json!([]),
        );
        assert_eq!(requested(&reviews), [1, 4, 1]);
        assert_eq!(requested(&triage), [3, 5]);

        // Another subscription to the standing observer outlives the intake run.
        apply_source(
            &store,
            r#"version 2
agent "example.watcher" { workspace "/tmp"; command "true" }
subscription "elsewhere" {
  observer "observer/github/acme/garden"; on "issues"; to "agent/example.watcher"
  delivery "message"
}"#,
            "elsewhere",
        );
        store
            .request_mission_run_cancellation(&run.id, "intake retired")
            .unwrap();
        for _ in 0..3 {
            reconciler.reconcile_once().unwrap();
        }
        for subject in [&reviews, &triage] {
            assert!(
                subscription(subject).is_none_or(|spec| spec.stopped),
                "{subject} stops with its run"
            );
        }
        assert!(subscription("subscription/elsewhere").is_some_and(|spec| !spec.stopped));
        assert!(observer(standing).is_some_and(|spec| !spec.stopped));

        apply_source(
            &store,
            "version 2\nsubscription \"elsewhere\" { stop }\n",
            "elsewhere-stops",
        );
        reconciler.reconcile_once().unwrap();
        assert!(
            observer(standing).is_some_and(|spec| spec.stopped),
            "nothing uses the standing observer"
        );
        let observers = store.repository_observers().unwrap();
        assert!(
            store
                .ensure_standing_observer("acme/garden", &observers)
                .unwrap()
        );
        assert_eq!(observer(standing).unwrap().resource, resource);
    }

    /// The intake pipeline: a new pull request head that a live agent owns reaches that agent as
    /// one message and requests no review; one nobody owns requests one review. New mentions of a
    /// named login reach an agent, never a person directly: those on items nobody owns go to one
    /// mission run per observation as a text input, and one on an owned item goes to its owner.
    /// Nothing is delivered twice, at the baseline, for a new item's own body, or for an old
    /// mention.
    #[test]
    fn the_intake_pipeline_routes_each_item_once_to_its_owner_or_an_agent() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(&store, REDELIVERY_REVIEW_SOURCE, "review-mission");
        apply_source(
            &store,
            r#"version 2
mission "mentions" state="ready" {
  input "source" kind="resource"
  input "mentions" kind="text"
  goal "Group, summarize, and ask once about new mentions."
  step "ask" { agentless }
}"#,
            "mentions-mission",
        );
        let review = store
            .mission_spec("review", None)
            .unwrap()
            .unwrap()
            .revision;
        apply_source(
            &store,
            &format!(
                r#"version 2
resource "repo" {{ kind "vcs.repository" }}
agent "builder" {{ workspace "/tmp"; command "true" }}
observer "repo" {{
  resource "resource/repo"; provider "github.repository"; locator "acme/garden"
  field "pull_requests"; field "mentions"
}}
subscription "reviews" {{
  observer "observer/repo"; on "pull_requests"
  delivery "mission" {{ mission "review@{review}"; resource "source"; workspace "/tmp/st3-reviews"; owner "message" }}
}}
subscription "mentions" {{
  observer "observer/repo"; on "mentions"
  mention "orchid"
  mention "fern"
  delivery "mission" {{ mission "mentions"; resource "source"; text "mentions"; workspace "/tmp/st3-mentions"; owner "message" }}
}}"#
            ),
            "watch",
        );
        let desired = store.desired_subjects().unwrap();
        let subscriptions = ["subscription/reviews", "subscription/mentions"]
            .into_iter()
            .map(|subject| {
                let item = desired.iter().find(|item| item.subject == subject).unwrap();
                (
                    item.subject.clone(),
                    crate::graph::subscription_spec(&item.desired).unwrap(),
                )
            })
            .collect::<Vec<_>>();
        let revision = store
            .selected_desired_revision("observer/repo")
            .unwrap()
            .unwrap();
        let observe = |pulls: Value| {
            store.record_resource_observation("observer/repo", &revision, None, "resource/repo", None, &serde_json::json!({"repository_id": 7, "pull_requests": pulls}), now_ms() + 60_000, &subscriptions, None)
                .unwrap()
        };
        let requests = |subscription: &str| {
            store
                .claims_for(subscription, Some("subscription.mission-requested"))
                .unwrap()
        };
        let reviews = || {
            requests("subscription/reviews")
                .into_iter()
                .map(|claim| {
                    claim.body["fields"]["resource"]
                        .as_str()
                        .unwrap()
                        .to_owned()
                })
                .collect::<Vec<_>>()
        };
        let mention_requests = || {
            requests("subscription/mentions")
                .into_iter()
                .map(|claim| {
                    let text = claim.body["fields"]["text"].as_str().unwrap();
                    serde_json::from_str::<Vec<Value>>(text)
                        .unwrap()
                        .into_iter()
                        .map(|mention| {
                            format!(
                                "{} #{} {}",
                                mention["by"].as_str().unwrap(),
                                mention["number"],
                                mention["login"].as_str().unwrap()
                            )
                        })
                        .collect::<Vec<_>>()
                })
                .collect::<Vec<_>>()
        };
        let routed = |outcome: &crate::model::ResourceObservationOutcome| {
            outcome
                .message_subjects
                .iter()
                .map(|subject| {
                    let message = store
                        .latest_claim(subject, Some("message.sent"))
                        .unwrap()
                        .unwrap();
                    (
                        message.body["fields"]["to"].as_str().unwrap().to_owned(),
                        message.body["fields"]["title"].as_str().unwrap().to_owned(),
                    )
                })
                .collect::<Vec<_>>()
        };
        let pull = |number: u64, head: char, opened_by: Option<&str>| {
            let mut pull = serde_json::json!({
                "number": number, "title": format!("Pull {number}"), "head": head.to_string().repeat(40),
                "state": "open", "draft": false,
                "url": format!("https://github.com/acme/garden/pull/{number}"),
            });
            if let Some(agent) = opened_by {
                pull["opened_by"] = Value::String(agent.into());
            }
            pull
        };
        let mention = |login: &str, by: &str, at: &str| {
            serde_json::json!({"login": login, "by": by, "at": at,
                "url": format!("https://github.com/acme/garden/pull/2#issuecomment-{login}-{by}")})
        };
        let now = chrono::Utc::now().to_rfc3339();
        // The baseline delivers nothing, even a mention.
        let mut baseline = pull(1, 'a', None);
        baseline["mentions"] = serde_json::json!([mention("orchid", "moss", &now)]);
        assert!(
            observe(serde_json::json!([baseline]))
                .message_subjects
                .is_empty()
        );
        assert!(reviews().is_empty() && mention_requests().is_empty());

        // A new pull request the builder opened reaches the builder; one nobody owns, or whose
        // opener is not a live agent, requests a review. A new item's own mentions go with it.
        let mut unowned = pull(3, 'c', None);
        unowned["mentions"] = serde_json::json!([mention("orchid", "moss", &now)]);
        let opened = observe(serde_json::json!([
            pull(2, 'b', Some("agent/node.builder")),
            unowned,
            pull(4, 'd', Some("agent/departed")),
        ]));
        assert_eq!(
            routed(&opened),
            [(
                "agent/node.builder".to_owned(),
                "Pull request #2 is at a new head: Pull 2".to_owned()
            )]
        );
        assert_eq!(
            reviews(),
            [
                "resource/repo/pull-request/3",
                "resource/repo/pull-request/4"
            ]
        );
        assert!(
            mention_requests().is_empty(),
            "a new item's body goes to its review"
        );

        // A new head of the builder's pull request reaches it again, once.
        let pushed = observe(serde_json::json!([pull(2, 'e', None)]));
        assert_eq!(
            routed(&pushed).len(),
            1,
            "the opener stays with its pull request"
        );
        assert!(
            observe(serde_json::json!([pull(2, 'e', None)]))
                .message_subjects
                .is_empty()
        );
        assert_eq!(reviews().len(), 2);

        // New comments that mention orchid and fern on pull requests nobody owns reach one
        // mission run together. A login's mention of itself, and a login no `mention` names,
        // reach nobody.
        let mut three = pull(3, 'c', None);
        three["mentions"] = serde_json::json!([
            mention("orchid", "moss", &now),
            mention("orchid", "lark", &now),
            mention("rook", "moss", &now),
        ]);
        let mut four = pull(4, 'd', None);
        four["mentions"] =
            serde_json::json!([mention("fern", "moss", &now), mention("lark", "lark", &now)]);
        observe(serde_json::json!([three, four]));
        assert_eq!(
            mention_requests(),
            [["lark #3 orchid", "moss #4 fern"]],
            "each item keeps the newest mention of each login"
        );
        // On the builder's pull request a mention reaches the builder instead.
        let mut owned = pull(2, 'e', None);
        owned["mentions"] = serde_json::json!([mention("orchid", "moss", &now)]);
        let to_owner = observe(serde_json::json!([owned]));
        assert_eq!(
            routed(&to_owner),
            [(
                "agent/node.builder".to_owned(),
                "moss mentioned @orchid on #2: Pull 2".to_owned()
            )]
        );
        assert_eq!(mention_requests().len(), 1);

        // An old mention that turns up later, such as one in a body read again, reaches nobody.
        let mut old = pull(4, 'd', None);
        old["mentions"] = serde_json::json!([mention("orchid", "moss", "2026-01-02T00:00:00Z")]);
        assert!(
            observe(serde_json::json!([old]))
                .message_subjects
                .is_empty()
        );
        assert_eq!(mention_requests().len(), 1);

        // The mention run gets the repository as its source and the mentions as its text input.
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        reconciler
            .reconcile_subscription_missions(&store.desired_subjects().unwrap())
            .unwrap();
        let started = store
            .claims_for(
                "subscription/mentions",
                Some("subscription.mission-started"),
            )
            .unwrap();
        assert_eq!(started.len(), 1);
        let run = store
            .mission_run(started[0].body["fields"]["mission_run"].as_str().unwrap())
            .unwrap()
            .unwrap();
        assert_eq!(
            run.inputs["source"].subject.as_deref(),
            Some("resource/repo")
        );
        let text: Vec<Value> = serde_json::from_str(&run.inputs["mentions"].value).unwrap();
        assert_eq!(
            text[0]["url"],
            "https://github.com/acme/garden/pull/2#issuecomment-orchid-lark"
        );
        assert_eq!(text[0]["resource"], "resource/repo/pull-request/3");
        // No step of this pipeline asks a person directly.
        assert!(
            store
                .claims_for_kind_at("work.person-asked", None, false, 10)
                .unwrap()
                .claims
                .is_empty()
        );
    }

    /// A batched message collects new pull request heads, issues, and mentions from several
    /// observations and sends them to its agent together: at most once per interval, never when
    /// nothing arrived, and each item once.
    #[test]
    fn a_batched_delivery_sends_what_arrived_together_at_most_once_per_interval() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"version 2
resource "repo" { kind "vcs.repository" }
agent "curator" { workspace "/tmp"; command "true" }
agent "builder" { workspace "/tmp"; command "true" }
observer "repo" {
  resource "resource/repo"; provider "github.repository"; locator "acme/garden"
  field "pull_requests"; field "issues"; field "mentions"
}
subscription "curate" {
  observer "observer/repo"; on "pull_requests"; on "issues"; on "mentions"
  mention "orchid"
  to "agent/node.curator"
  delivery "message" { every "1s"; owner "message" }
}"#,
            "watch",
        );
        let desired = store.desired_subjects().unwrap();
        let item = desired
            .iter()
            .find(|item| item.subject == "subscription/curate")
            .unwrap();
        let subscriptions = vec![(
            item.subject.clone(),
            crate::graph::subscription_spec(&item.desired).unwrap(),
        )];
        let revision = store
            .selected_desired_revision("observer/repo")
            .unwrap()
            .unwrap();
        let observe = |facts: Value| {
            store.record_resource_observation("observer/repo", &revision, None, "resource/repo", None, &facts, now_ms() + 60_000, &subscriptions, None)
                .unwrap()
        };
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        let flush = || {
            reconciler
                .reconcile_subscription_missions(&store.desired_subjects().unwrap())
                .unwrap()
        };
        let batches = || {
            store
                .claims_for("subscription/curate", Some("subscription.batch-sent"))
                .unwrap()
                .into_iter()
                .map(|sent| {
                    let message = store
                        .latest_claim(
                            sent.body["fields"]["message"].as_str().unwrap(),
                            Some("message.sent"),
                        )
                        .unwrap()
                        .unwrap();
                    (
                        message.body["fields"]["to"].as_str().unwrap().to_owned(),
                        message.body["fields"]["title"].as_str().unwrap().to_owned(),
                        message.body["fields"]["content"]
                            .as_str()
                            .unwrap()
                            .to_owned(),
                    )
                })
                .collect::<Vec<_>>()
        };
        let now = chrono::Utc::now().to_rfc3339();
        let pull = |number: u64, head: char| {
            serde_json::json!({
                "number": number, "title": format!("Pull {number}"), "head": head.to_string().repeat(40),
                "state": "open", "draft": false, "author": "lark",
                "url": format!("https://github.com/acme/garden/pull/{number}"),
            })
        };
        observe(
            serde_json::json!({"repository_id": 7, "pull_requests": [pull(1, 'a')], "issues": []}),
        );
        flush();
        assert!(batches().is_empty(), "the baseline collects nothing");

        // Two observations collect a new pull request, a new issue, and a mention; one owned by
        // the builder goes to it alone.
        let mut owned = pull(2, 'b');
        owned["opened_by"] = Value::String("agent/node.builder".into());
        observe(
            serde_json::json!({"repository_id": 7, "pull_requests": [pull(3, 'c'), owned],
            "issues": [{"number": 4, "title": "Bug", "url": "https://github.com/acme/garden/issues/4", "author": "moss", "state": "open"}]}),
        );
        let mut mentioned = pull(1, 'a');
        mentioned["mentions"] = serde_json::json!([{"login": "orchid", "by": "moss", "at": now,
            "url": "https://github.com/acme/garden/pull/1#issuecomment-9"}]);
        observe(serde_json::json!({"repository_id": 7, "pull_requests": [mentioned]}));
        flush();
        let sent = batches();
        assert_eq!(sent.len(), 1);
        let (to, title, content) = &sent[0];
        assert_eq!(to, "agent/node.curator");
        assert_eq!(title, "3 GitHub items headed for a person");
        assert!(
            content.contains("resource/repo #3 pull request: Pull 3"),
            "{content}"
        );
        assert!(content.contains("resource/repo #4 issue: Bug"), "{content}");
        assert!(content.contains("moss mentioned @orchid"), "{content}");
        assert!(
            content.contains("https://github.com/acme/garden/pull/1#issuecomment-9"),
            "{content}"
        );
        assert!(content.contains("marker "), "{content}");
        assert!(
            !content.contains("#2 "),
            "the builder's pull request went to the builder"
        );

        // Quiet: nothing more is sent.
        flush();
        assert_eq!(batches().len(), 1);

        // A new head arrives inside the interval: it waits, then goes out once.
        observe(serde_json::json!({"repository_id": 7, "pull_requests": [pull(3, 'd')]}));
        flush();
        assert_eq!(batches().len(), 1, "the interval has not passed");
        std::thread::sleep(Duration::from_millis(1_100));
        flush();
        flush();
        let sent = batches();
        assert_eq!(sent.len(), 2);
        assert_eq!(sent[1].1, "1 GitHub item headed for a person");
        assert!(sent[1].2.contains("#3 pull request"), "{}", sent[1].2);
    }

    #[test]
    fn a_renamed_locator_and_a_first_complete_listing_deliver_nothing() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(&store, REDELIVERY_REVIEW_SOURCE, "review-mission");
        let review = store
            .mission_spec("review", None)
            .unwrap()
            .unwrap()
            .revision;
        let subscriptions = watch_repository(&store, "acme/old", &review, "watch-old");
        // Facts from the first-page reader: it only ever saw the newest issues.
        let first_page = (145..=150)
            .map(|number| serde_json::json!({"number": number, "title": format!("Issue {number}")}))
            .collect::<Vec<_>>();
        record_issues(
            &store,
            &serde_json::json!({"issues": first_page}),
            &subscriptions,
        );
        let requests = || {
            store
                .claims_for(
                    "subscription/triage",
                    Some("subscription.mission-requested"),
                )
                .unwrap()
        };

        observe_issues(&store, "acme/old", 20..=150, &subscriptions);
        assert!(
            requests().is_empty(),
            "a first complete listing finds missed issues, not new ones"
        );

        let subscriptions = watch_repository(&store, "acme/new", &review, "watch-renamed");
        observe_issues(&store, "acme/new", 20..=150, &subscriptions);
        assert!(
            requests().is_empty(),
            "a renamed locator keeps every item identity"
        );

        observe_issues(&store, "acme/new", (20..=150).chain([151]), &subscriptions);
        let requests = requests();
        assert_eq!(requests.len(), 1);
        assert_eq!(
            requests[0].body["fields"]["resource"],
            "resource/repo/issue/151"
        );
    }

    const QUEUED_REVIEW_SOURCE: &str = r#"version 2
mission "review" state="ready" {
  concurrent-runs max=1
  input "source" kind="resource"
  completion { when "all-steps-exhausted" }
  goal "Review one discovered item."
  step "review" { agentless }
}"#;

    #[test]
    fn twenty_subscription_deliveries_start_in_order_without_holds() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(&store, QUEUED_REVIEW_SOURCE, "review-mission");
        let review = store
            .mission_spec("review", None)
            .unwrap()
            .unwrap()
            .revision;
        let subscriptions = watch_repository(&store, "acme/repo", &review, "watch");
        observe_issues(&store, "acme/repo", [1], &subscriptions);
        observe_issues(&store, "acme/repo", 1..=21, &subscriptions);
        let requests = store.subscription_requests("subscription/triage").unwrap();
        assert_eq!(requests.len(), 20);
        assert!(requests.iter().all(|request| request.status == "pending"));
        assert!(
            store
                .claims_for(
                    "subscription/triage",
                    Some("subscription.mission-requested")
                )
                .unwrap()
                .iter()
                .all(|claim| claim.body["fields"].get("held").is_none())
        );
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        let desired = store.desired_subjects().unwrap();
        for (position, request) in requests.iter().enumerate() {
            // Expire the local retry deadline rather than sleeping through twenty backoffs.
            if let Some((_, attempts)) = store
                .subscription_mission_deferral("subscription/triage", &request.request)
                .unwrap()
            {
                store
                    .record_subscription_mission_deferral(
                        "subscription/triage",
                        &request.request,
                        0,
                        attempts,
                    )
                    .unwrap();
            }
            reconciler
                .reconcile_subscription_missions(&desired)
                .unwrap();
            let active = store.active_mission_runs_for_mission("review").unwrap();
            assert_eq!(active.len(), 1, "mission capacity must control the queue");
            assert_eq!(
                active[0].inputs["source"].subject.as_deref(),
                Some(request.resource.as_str())
            );
            let statuses = store.subscription_requests("subscription/triage").unwrap();
            assert!(
                statuses[..=position]
                    .iter()
                    .all(|request| request.status == "started")
            );
            assert!(
                statuses[position + 1..]
                    .iter()
                    .all(|request| request.status == "pending")
            );
            for _ in 0..5 {
                reconciler.evaluate_mission_runs().unwrap();
            }
            assert!(
                store
                    .active_mission_runs_for_mission("review")
                    .unwrap()
                    .is_empty()
            );
        }
        let started = store
            .claims_for("subscription/triage", Some("subscription.mission-started"))
            .unwrap();
        assert_eq!(
            started
                .iter()
                .map(|claim| claim.body["fields"]["request"].as_str().unwrap())
                .collect::<Vec<_>>(),
            requests
                .iter()
                .map(|request| request.request.as_str())
                .collect::<Vec<_>>()
        );
        reconciler
            .reconcile_subscription_missions(&desired)
            .unwrap();
        assert_eq!(
            store
                .claims_for("subscription/triage", Some("subscription.mission-started"))
                .unwrap()
                .len(),
            20
        );
        assert!(
            store
                .attention_requests(Some("person/operator"), true)
                .unwrap()
                .is_empty()
        );
    }

    #[test]
    fn a_new_delivery_cannot_pass_an_older_capacity_retry() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(&store, QUEUED_REVIEW_SOURCE, "review-mission");
        let review = store
            .mission_spec("review", None)
            .unwrap()
            .unwrap()
            .revision;
        let subscriptions = watch_repository(&store, "acme/repo", &review, "watch");
        observe_issues(&store, "acme/repo", [1], &subscriptions);
        observe_issues(&store, "acme/repo", 1..=3, &subscriptions);
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        let desired = store.desired_subjects().unwrap();
        reconciler
            .reconcile_subscription_missions(&desired)
            .unwrap();
        let older = store.subscription_requests("subscription/triage").unwrap()[1]
            .request
            .clone();
        // Keep the older capacity retry in the future after its predecessor finishes.
        store
            .record_subscription_mission_deferral(
                "subscription/triage",
                &older,
                now_ms() + 60_000,
                1,
            )
            .unwrap();
        for _ in 0..5 {
            reconciler.evaluate_mission_runs().unwrap();
        }
        observe_issues(&store, "acme/repo", 1..=4, &subscriptions);
        reconciler
            .reconcile_subscription_missions(&desired)
            .unwrap();
        assert!(
            store
                .active_mission_runs_for_mission("review")
                .unwrap()
                .is_empty(),
            "the new request must wait behind the older retry"
        );
        store
            .record_subscription_mission_deferral("subscription/triage", &older, 0, 1)
            .unwrap();
        reconciler
            .reconcile_subscription_missions(&desired)
            .unwrap();
        assert_eq!(
            store.active_mission_runs_for_mission("review").unwrap()[0].inputs["source"]
                .subject
                .as_deref(),
            Some("resource/repo/issue/3")
        );
    }

    #[test]
    fn legacy_held_requests_migrate_and_stale_requests_cancel_across_restart() {
        let directory = tempfile::tempdir().unwrap();
        let path = directory.path().join("queue.sqlite");
        let store = Arc::new(Store::open(&path, "node").unwrap());
        apply_source(&store, QUEUED_REVIEW_SOURCE, "review");
        apply_source(
            &store,
            r#"version 2
resource "repo" { kind "vcs.repository" }
observer "repo" { resource "resource/repo"; provider "github.repository"; locator "acme/repo"; field "pull_requests" }
subscription "reviews" {
  observer "observer/repo"; on "pull_requests"
  delivery "mission" { mission "review"; resource "source"; workspace "/tmp/st3-queue-reviews" }
}"#,
            "watch",
        );
        let desired = store.desired_subjects().unwrap();
        let item = desired
            .iter()
            .find(|item| item.subject == "subscription/reviews")
            .unwrap();
        let subscriptions = vec![(
            item.subject.clone(),
            crate::graph::subscription_spec(&item.desired).unwrap(),
        )];
        let observer_revision = store
            .selected_desired_revision("observer/repo")
            .unwrap()
            .unwrap();
        let observe = |pulls, deliveries: &[(String, crate::model::SubscriptionSpec)]| {
            store.record_resource_observation("observer/repo", &observer_revision, None, "resource/repo", None, &serde_json::json!({"repository_id": 7, "pull_requests": pulls}), now_ms() + 60_000, deliveries, None)
                .unwrap()
        };
        observe(serde_json::json!([]), &[]);
        let head = "a".repeat(40);
        observe(
            serde_json::json!([
                {"number": 1, "head": head, "state": "open", "draft": false},
                {"number": 2, "head": head, "state": "open", "draft": false},
                {"number": 3, "head": head, "state": "open", "draft": false},
                {"number": 4, "head": head, "state": "open", "draft": false},
            ]),
            &[],
        );
        let legacy = (1..=4)
            .map(|number| {
                let resource = format!("resource/repo/pull-request/{number}");
                let mut discovery = store
                    .claims_for(&resource, Some("resource.observed"))
                    .unwrap()
                    .pop()
                    .unwrap();
                if number == 2 {
                    // This held request predates item head_sha. Its cited listing still pins
                    // the old head, so migration must cancel it when the new head arrives.
                    let mut facts = discovery.body["fields"]["facts"].clone();
                    facts.as_object_mut().unwrap().remove("head_sha");
                    // An older build's listing kept every item in the repository facts.
                    let listing = store
                        .append_claim(&ClaimInput {
                            subject: "resource/repo".into(),
                            kind: "resource.observed".into(),
                            actor: None,
                            fields: BTreeMap::from([
                                ("kind".into(), Value::String("vcs.repository".into())),
                                (
                                    "facts".into(),
                                    serde_json::json!({"repository_id": 7, "pull_requests": [
                                        {"number": 2, "head": head, "state": "open", "draft": false},
                                    ]}),
                                ),
                            ]),
                            evidence: Vec::new(),
                            expected_subject: None,
                            idempotency_key: Some("legacy-listing".into()),
                        })
                        .unwrap();
                    discovery = store
                        .append_claim(&ClaimInput {
                            subject: resource.clone(),
                            kind: "resource.observed".into(),
                            actor: None,
                            fields: BTreeMap::from([
                                ("kind".into(), Value::String("vcs.pull-request".into())),
                                ("facts".into(), facts),
                            ]),
                            evidence: vec![listing.id],
                            expected_subject: None,
                            idempotency_key: Some("legacy-headless-item".into()),
                        })
                        .unwrap();
                }
                store
                    .append_claim(&ClaimInput {
                        subject: "subscription/reviews".into(),
                        kind: "subscription.mission-requested".into(),
                        actor: None,
                        fields: BTreeMap::from([
                            ("mission".into(), Value::String("mission/review".into())),
                            ("resource".into(), Value::String(resource)),
                            ("resource_input".into(), Value::String("source".into())),
                            (
                                "workspace".into(),
                                Value::String(directory.path().to_string_lossy().into_owned()),
                            ),
                            ("discovery".into(), Value::String(discovery.id)),
                            ("held".into(), Value::Bool(true)),
                        ]),
                        evidence: vec![],
                        expected_subject: None,
                        idempotency_key: Some(format!("legacy-request-{number}")),
                    })
                    .unwrap()
            })
            .collect::<Vec<_>>();
        store
            .request_attention(
                "attention/legacy-held",
                &AttentionRequest {
                    reviewer: "person/operator".into(),
                    title: "A subscription is holding mission requests".into(),
                    reason: "one observation exceeded the old burst cap".into(),
                    severity: "warning".into(),
                    targets: vec!["subscription/reviews".into()],
                    actor: RECONCILER_ACTOR.into(),
                    idempotency_key: "legacy-held-attention".into(),
                },
            )
            .unwrap();
        // Occupy capacity with another snapshot: completing the valid hold's own snapshot
        // would correctly suppress its later delivery rather than test queue migration.
        let discovery = legacy[1].body["fields"]["discovery"].as_str().unwrap();
        let occupied = store
            .create_mission_run(&MissionRunRequest {
                mission: "review".into(),
                revision: None,
                workspace: directory.path().to_string_lossy().into_owned(),
                requester: None,
                mode: None,
                inputs: BTreeMap::from([(
                    "source".into(),
                    format!("resource/repo/pull-request/2@{discovery}"),
                )]),
                idempotency_key: "occupied".into(),
            })
            .unwrap();
        observe(
            serde_json::json!([
                {"number": 1, "head": head, "state": "open", "draft": false},
                {"number": 2, "head": "b".repeat(40), "state": "open", "draft": false},
                {"number": 3, "head": head, "state": "closed", "draft": false},
                {"number": 4, "head": head, "state": "open", "draft": true},
            ]),
            &subscriptions,
        );
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        reconciler
            .reconcile_subscription_missions(&desired)
            .unwrap();
        let queue = store.subscription_requests("subscription/reviews").unwrap();
        assert_eq!(
            queue
                .iter()
                .map(|request| request.status.as_str())
                .collect::<Vec<_>>(),
            ["pending", "cancelled", "cancelled", "cancelled", "pending"]
        );
        let cancelled = store
            .claims_for(
                "subscription/reviews",
                Some("subscription.mission-request-cancelled"),
            )
            .unwrap();
        assert!(
            cancelled[0].body["fields"]["reason"]
                .as_str()
                .unwrap()
                .contains("moved from head")
        );
        assert_eq!(
            cancelled[1].body["fields"]["reason"],
            "pull request #3 is closed"
        );
        assert_eq!(
            cancelled[2].body["fields"]["reason"],
            "pull request #4 is a draft again"
        );
        let attention = store
            .attention_request("attention/legacy-held")
            .unwrap()
            .unwrap();
        assert_eq!(
            attention.status, "resolved",
            "the queue never asks a person, even at capacity"
        );
        for _ in 0..5 {
            reconciler.evaluate_mission_runs().unwrap();
        }
        assert_eq!(
            store.mission_run(&occupied.id).unwrap().unwrap().status,
            "completed"
        );
        drop(reconciler);
        drop(store);

        let store = Arc::new(Store::open(&path, "node").unwrap());
        let desired = store.desired_subjects().unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        for request in [&legacy[0].id, &queue[4].request] {
            if let Some((_, attempts)) = store
                .subscription_mission_deferral("subscription/reviews", request)
                .unwrap()
            {
                store
                    .record_subscription_mission_deferral(
                        "subscription/reviews",
                        request,
                        0,
                        attempts,
                    )
                    .unwrap();
            }
            reconciler
                .reconcile_subscription_missions(&desired)
                .unwrap();
            let active = store.active_mission_runs_for_mission("review").unwrap();
            assert_eq!(active.len(), 1);
            for _ in 0..5 {
                reconciler.evaluate_mission_runs().unwrap();
            }
        }
        let started = store
            .claims_for("subscription/reviews", Some("subscription.mission-started"))
            .unwrap();
        assert_eq!(
            started
                .iter()
                .map(|claim| claim.body["fields"]["request"].as_str().unwrap())
                .collect::<Vec<_>>(),
            [&legacy[0].id, &queue[4].request]
        );
        let released = store
            .claims_for(
                "subscription/reviews",
                Some("subscription.mission-request-released"),
            )
            .unwrap();
        assert_eq!(released.len(), 1, "migration is durable and happens once");
        assert!(
            released[0].actor.is_none(),
            "no person releases the migrated request"
        );
        assert_eq!(
            store
                .attention_requests(Some("person/operator"), true)
                .unwrap()
                .len(),
            1
        );
    }

    const INTAKE_REVIEW_SOURCE: &str = r#"version 2
mission "review" state="ready" {
  input "source" kind="resource"
  goal "Review one discovered item."
  step "review" { agentless }
}"#;

    /// A standing mission whose seat keeps the run open while it declares `intake`.
    fn standing_intake_source(intake: &str) -> String {
        format!(
            r#"version 2
resource "repo" {{ kind "vcs.repository" }}
mission "standing" state="ready" {{
  goal "Watch one repository."
  agent "seat" {{ workspace "/tmp"; command "true"; restart "never" }}
  step "watch" {{ assigned-to "agent/${{ST_MISSION_RUN}}/seat"; goal "Keep watching." }}
{intake}
}}"#
        )
    }

    fn standing_intake(review_revision: &str) -> String {
        format!(
            r#"  observer "repo" {{ resource "resource/repo"; provider "github.repository"; locator "owner/repo"; field "pull_requests" }}
  subscription "reviews" {{
    observer "observer/repo"
    on "pull_requests"
    delivery "mission" {{
      mission "review@{review_revision}"
      resource "source"
      workspace "/tmp/st3-review"
    }}
  }}"#
        )
    }

    fn request_review(store: &Store, subscription: &str, review_revision: &str, key: &str) {
        store
            .append_claim(&ClaimInput {
                subject: subscription.into(),
                kind: "subscription.mission-requested".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("mission".into(), Value::String("mission/review".into())),
                    (
                        "mission_revision".into(),
                        Value::String(review_revision.into()),
                    ),
                    (
                        "resource".into(),
                        Value::String("resource/repo/pull-request/7".into()),
                    ),
                    ("resource_input".into(), Value::String("source".into())),
                    ("workspace".into(), Value::String("/tmp/st3-review".into())),
                    ("discovery".into(), Value::String("discovery-claim".into())),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some(key.into()),
            })
            .unwrap();
    }

    #[test]
    fn a_revision_keeps_a_still_declared_member_and_its_claim() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
version 2

  mission "keep" state="ready" {
    goal "Keep the seat through a revision."
    agent "worker" { workspace "/tmp"; command "true"; restart "never" }
    step "work" { assigned-to "agent/${ST_MISSION_RUN}/worker"; goal "Do the work." }
    step "other" { assigned-to "agent/${ST_MISSION_RUN}/worker"; goal "Use the first goal." }
  }

"#;
        apply_source(&store, source, "publish-keep");
        let first = store.mission_spec("keep", None).unwrap().unwrap();
        apply_source(
            &store,
            &source.replace("Use the first goal.", "Use the second goal."),
            "publish-keep-two",
        );
        let revised = store.mission_spec("keep", None).unwrap().unwrap();
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "keep".into(),
                revision: Some(first.revision),
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: None,
                inputs: BTreeMap::new(),
                idempotency_key: "run-keep".into(),
            })
            .unwrap();
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        );
        for _ in 0..3 {
            if !runtime.started_members.lock().unwrap().is_empty() {
                break;
            }
            reconciler.reconcile_once().unwrap();
        }
        let worker = format!("agent/{}/worker", run.id);
        let member = runtime.started_members.lock().unwrap()[0].clone();
        runtime.ptys.lock().unwrap().push(RuntimeObservation {
            runtime_id: member.runtime_id.clone(),
            terminal: true,
            status: "running".into(),
            exit_code: None,
            incarnation_id: Some("keep-incarnation".into()),
        });
        for _ in 0..3 {
            reconciler.reconcile_once().unwrap();
        }
        let work = |run: &crate::model::MissionRunView| {
            run.steps
                .iter()
                .find(|step| step.step == "work")
                .unwrap()
                .clone()
        };
        let old = work(&store.mission_run(&run.id).unwrap().unwrap());
        assert_eq!(old.status, "ready");
        store
            .work_action(
                &old.subject,
                "claim",
                &crate::model::WorkRequest {
                    wait_ms: None,
                    actor: Some(worker.clone()),
                    incarnation: Some("keep-incarnation".into()),
                    summary: None,
                    reason: None,
                    evidence: Vec::new(),
                    idempotency_key: "keep-claim".into(),
                },
            )
            .unwrap();
        let adopted = store
            .adopt_mission_revision(
                &run.id,
                &revised,
                "person/test",
                "the other step needs a second goal",
                "keep-revision",
            )
            .unwrap();

        for _ in 0..3 {
            reconciler.reconcile_once().unwrap();
        }

        assert!(
            runtime.stops.lock().unwrap().is_empty(),
            "a revision must not stop a member that its successor still declares"
        );
        assert_eq!(runtime.started_members.lock().unwrap().len(), 1);
        let desired = store
            .desired_subjects()
            .unwrap()
            .into_iter()
            .find(|desired| desired.subject == worker)
            .unwrap();
        assert_eq!(desired.kind, "agent");
        assert_eq!(
            desired.owner_generation.as_deref(),
            Some(adopted.generation.as_str())
        );
        let carried = work(&store.mission_run(&run.id).unwrap().unwrap());
        assert_ne!(carried.subject, old.subject);
        assert_eq!(
            (
                carried.status.as_str(),
                carried.claimant.as_deref(),
                carried.claim_incarnation.as_deref()
            ),
            ("claimed", Some(worker.as_str()), Some("keep-incarnation"))
        );
    }

    #[test]
    fn a_revision_that_removes_intake_retires_it_and_cancels_unstarted_requests() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(&store, INTAKE_REVIEW_SOURCE, "review-mission");
        let review = store
            .mission_spec("review", None)
            .unwrap()
            .unwrap()
            .revision;
        apply_source(
            &store,
            &standing_intake_source(&standing_intake(&review)),
            "standing-with-intake",
        );
        let first = store.mission_spec("standing", None).unwrap().unwrap();
        apply_source(
            &store,
            &standing_intake_source(""),
            "standing-without-intake",
        );
        let revised = store.mission_spec("standing", None).unwrap().unwrap();
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "standing".into(),
                revision: Some(first.revision),
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: None,
                inputs: BTreeMap::new(),
                idempotency_key: "run-standing".into(),
            })
            .unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        for _ in 0..3 {
            reconciler.reconcile_once().unwrap();
        }
        let observer = format!("observer/{}/repo", run.id);
        let subscription = format!("subscription/{}/reviews", run.id);
        let desired = |subject: &str| {
            store
                .desired_subjects()
                .unwrap()
                .into_iter()
                .find(|desired| desired.subject == subject)
                .unwrap_or_else(|| panic!("`{subject}` is desired"))
        };
        assert!(!intake_is_stopped(&desired(&subscription), "node"));
        store
            .adopt_mission_revision(
                &run.id,
                &revised,
                "person/test",
                "stop the old intake",
                "drop-intake",
            )
            .unwrap();
        request_review(&store, &subscription, &review, "pending-review");

        for _ in 0..3 {
            reconciler.reconcile_once().unwrap();
        }

        assert!(
            store
                .claims_for(&subscription, Some("subscription.mission-started"))
                .unwrap()
                .is_empty(),
            "a removed subscription must not start its pending request"
        );
        assert!(
            store
                .active_mission_runs_for_mission("review")
                .unwrap()
                .is_empty()
        );
        let cancelled = store
            .claims_for(
                &subscription,
                Some("subscription.mission-request-cancelled"),
            )
            .unwrap();
        assert_eq!(cancelled.len(), 1);
        assert!(intake_is_stopped(&desired(&subscription), "node"));
        assert!(intake_is_stopped(&desired(&observer), "node"));
        assert_eq!(
            store
                .latest_actual_value(&observer)
                .unwrap()
                .and_then(|actual| actual.get("state").cloned()),
            Some(Value::String("stopped".into()))
        );

        request_review(&store, &subscription, &review, "late-review");
        reconciler.reconcile_once().unwrap();
        assert_eq!(
            store
                .claims_for(
                    &subscription,
                    Some("subscription.mission-request-cancelled")
                )
                .unwrap()
                .len(),
            2,
            "a request recorded after the stop is closed too"
        );
    }

    #[test]
    fn a_terminal_owner_or_another_host_starts_no_subscription_run() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(&store, INTAKE_REVIEW_SOURCE, "review-mission");
        let review = store
            .mission_spec("review", None)
            .unwrap()
            .unwrap()
            .revision;
        apply_source(
            &store,
            &standing_intake_source(&standing_intake(&review)),
            "standing-with-intake",
        );
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "standing".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: None,
                inputs: BTreeMap::new(),
                idempotency_key: "run-standing".into(),
            })
            .unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        for _ in 0..3 {
            reconciler.reconcile_once().unwrap();
        }
        let owned = format!("subscription/{}/reviews", run.id);
        assert!(
            store
                .set_mission_run_state(&run.id, "completed", "terminal", None)
                .unwrap()
        );
        request_review(&store, &owned, &review, "after-completion");
        reconciler.reconcile_once().unwrap();
        assert!(
            store
                .claims_for(&owned, Some("subscription.mission-started"))
                .unwrap()
                .is_empty(),
            "a completed owner's subscription must not start work"
        );

        apply_source(
            &store,
            &format!(
                "version 2\nresource \"repo\" {{ kind \"vcs.repository\" }}\n{}",
                standing_intake(&review)
            ),
            "top-level-intake",
        );
        request_review(&store, "subscription/reviews", &review, "foreign-review");
        let peer = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "other".into(),
            Arc::new(Notify::new()),
        );
        peer.reconcile_subscription_missions(&store.desired_subjects().unwrap())
            .unwrap();
        assert!(
            store
                .claims_for("subscription/reviews", Some("subscription.mission-started"))
                .unwrap()
                .is_empty(),
            "only the declaring host starts subscription runs"
        );
    }

    #[test]
    fn a_resource_input_gate_reads_its_exact_start_claim() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
version 2

  resource "source" { kind "custom.st3.document-source" }
  mission "resource-input" state="ready" {
    input "source" kind="resource"
    goal "Check the start snapshot."
    completion { when "all-steps-exhausted" }
    step "check" {
      agentless
      gate "the start snapshot is ready" { field "state" "${input.source}" is "ready" }
    }
  }

"#;
        apply_source(&store, source, "publish-resource-input");
        let first = store
            .append_claim(&ClaimInput {
                subject: "resource/source".into(),
                kind: "resource.observed".into(),
                actor: None,
                fields: BTreeMap::from([("state".into(), Value::String("ready".into()))]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some("resource-input-ready".into()),
            })
            .unwrap();
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "resource-input".into(),
                revision: None,
                workspace: ".".into(),
                requester: None,
                mode: None,
                inputs: BTreeMap::from([("source".into(), "resource/source".into())]),
                idempotency_key: "resource-input-run".into(),
            })
            .unwrap();
        store
            .append_claim(&ClaimInput {
                subject: "resource/source".into(),
                kind: "resource.observed".into(),
                actor: None,
                fields: BTreeMap::from([("state".into(), Value::String("changed".into()))]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some("resource-input-changed".into()),
            })
            .unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        for _ in 0..5 {
            reconciler.reconcile_once().unwrap();
        }
        let completed = store.mission_run(&run.id).unwrap().unwrap();
        assert_eq!(completed.status, "completed");
        assert_eq!(completed.inputs["source"].claim_id, Some(first.id));
    }

    #[test]
    fn one_mission_run_rejects_a_runtime_id_in_two_steps_without_holding_later_runs() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
version 2

  mission "collision" state="ready" {
    goal "Reject two owners for one runtime."
    step "one" { agentless;  exec "same" { command "true"; restart "never" }  }
    step "two" { agentless;  exec "same" { command "true"; restart "never" }  }
  }

  mission "later" state="ready" {
    goal "Complete beside a faulted run."
    completion { when "all-steps-exhausted" }
    step "one" { }
  }

"#;
        apply_source(&store, source, "publish-collision");
        let request = |mission: &str| MissionRunRequest {
            mission: mission.into(),
            revision: None,
            workspace: ".".into(),
            requester: None,
            mode: None,
            inputs: BTreeMap::new(),
            idempotency_key: format!("{mission}-run"),
        };
        let collision = store.create_mission_run(&request("collision")).unwrap();
        // The faulted run is older, so it is evaluated first in every pass.
        std::thread::sleep(Duration::from_millis(2));
        let later = store.create_mission_run(&request("later")).unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        )
        .tolerating_faults();
        for _ in 0..8 {
            reconciler.reconcile_once().unwrap();
        }
        // The second step to declare the runtime faults; the run and its first step do not.
        let faults = store
            .mission_run(&collision.id)
            .unwrap()
            .unwrap()
            .steps
            .iter()
            .filter_map(|step| store.reconcile_fault(&step.subject, "step").unwrap())
            .collect::<Vec<_>>();
        assert_eq!(faults.len(), 1, "{faults:?}");
        assert!(
            faults[0].contains("more than one mission or step"),
            "{faults:?}"
        );
        assert_eq!(
            store
                .reconcile_fault(&collision.subject, "mission-run")
                .unwrap(),
            None
        );
        assert_eq!(
            store.mission_run(&later.id).unwrap().unwrap().status,
            "completed"
        );
        assert!(
            store
                .reconcile_fault("daemon/node", "stage/missions")
                .unwrap()
                .is_none()
        );
    }

